}

package com.gielinorwrapped;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.util.ArrayList;
import java.util.List;

/**
 * Draws captions: "|" splits lines, the first line is the headline and the rest are smaller. Lines
 * slide in one after another, and numbers in the headline are picked out in the accent colour.
 */
final class Captions
{
	private static final double INTRO = 0.35;
	private static final double STAGGER = 0.15;
	private static final double OUTRO = 0.25;

	private Captions()
	{
	}

	private static final class Line
	{
		final String[] words;
		final Font font;
		final int width;
		final int height;
		final int ascent;
		final int lineIndex;
		final int firstWord;

		Line(String[] words, Font font, FontMetrics fm, int lineIndex, int firstWord)
		{
			this.words = words;
			this.font = font;
			width = fm.stringWidth(String.join(" ", words));
			height = fm.getHeight();
			ascent = fm.getAscent();
			this.lineIndex = lineIndex;
			this.firstWord = firstWord;
		}
	}

	/**
	 * @param area where the caption may go; it is placed at the top, middle or bottom of it
	 * @param size headline height in pixels
	 * @param t seconds since the caption appeared
	 * @param duration seconds it stays up, for the fade out and word-by-word timing
	 */
	static void draw(Graphics2D g, String text, Rectangle area, GielinorWrappedConfig.CaptionPosition position,
		GielinorWrappedConfig.CaptionStyle style, Theme theme, float size, double t, double duration)
	{
		if (text == null || text.trim().isEmpty() || t < 0)
		{
			return;
		}
		List<Line> lines = layout(g, theme, text, (int) (area.width * 0.9), size);
		if (lines.isEmpty())
		{
			return;
		}
		int gap = Math.round(size * 0.15f);
		int pad = Math.round(size * 0.4f);
		int blockH = -gap;
		int blockW = 0;
		int totalWords = 0;
		for (Line l : lines)
		{
			blockH += l.height + gap;
			blockW = Math.max(blockW, l.width);
			totalWords += l.words.length;
		}
		int y;
		switch (position)
		{
			case TOP:
				y = area.y + pad * 2;
				break;
			case CENTER:
				y = area.y + (area.height - blockH) / 2;
				break;
			default:
				y = area.y + area.height - blockH - pad * 2;
		}
		double fadeOut = duration > 0 ? clamp((duration - t) / OUTRO) : 1;

		if (style == GielinorWrappedConfig.CaptionStyle.BOXED)
		{
			double a = ease(clamp(t / INTRO)) * fadeOut;
			int bx = area.x + (area.width - blockW) / 2 - pad;
			Color panel = theme.panel;
			g.setColor(Theme.alpha(panel, a));
			int arc = Math.round(size * 0.6f);
			g.fillRoundRect(bx, y - pad / 2, blockW + pad * 2, blockH + pad, arc, arc);
			g.setColor(Theme.alpha(theme.accent, a));
			g.fillRect(bx + arc / 2, y + blockH + pad / 2 - Math.max(2, Math.round(size / 12f)), blockW + pad * 2 - arc, Math.max(2, Math.round(size / 12f)));
		}

		double wordTime = totalWords == 0 ? 0 : Math.min(0.4, Math.max(0.1, (duration > 0 ? duration * 0.6 : 2) / totalWords));
		Color outline = theme.light() && style != GielinorWrappedConfig.CaptionStyle.OUTLINE ? new Color(255, 255, 255) : new Color(0, 0, 0);
		Color fill = style == GielinorWrappedConfig.CaptionStyle.BOXED ? theme.text : (theme.light() && style == GielinorWrappedConfig.CaptionStyle.SHADOW ? theme.text : new Color(255, 255, 255));

		for (Line l : lines)
		{
			double p = ease(clamp((t - l.lineIndex * STAGGER) / INTRO));
			double a = p * fadeOut;
			if (a <= 0)
			{
				y += l.height + gap;
				continue;
			}
			int lift = (int) Math.round((1 - p) * size * 0.5);
			g.setFont(l.font);
			FontMetrics fm = g.getFontMetrics();
			int x = area.x + (area.width - l.width) / 2;
			int baseline = y + l.ascent + lift;
			int space = fm.charWidth(' ');
			for (int i = 0; i < l.words.length; i++)
			{
				String word = l.words[i];
				Color c = l.lineIndex == 0 && hasDigit(word) ? theme.accent : fill;
				double wa = a;
				if (style == GielinorWrappedConfig.CaptionStyle.KARAOKE)
				{
					double start = (l.firstWord + i) * wordTime;
					double since = t - start;
					if (since < 0)
					{
						wa *= 0.3;
						c = fill;
					}
					else if (since < wordTime * 1.5)
					{
						c = theme.accent;
					}
				}
				drawWord(g, word, x, baseline, style, Theme.alpha(c, wa), Theme.alpha(outline, wa), size);
				x += fm.stringWidth(word) + space;
			}
			y += l.height + gap;
		}
	}

	private static void drawWord(Graphics2D g, String word, int x, int y, GielinorWrappedConfig.CaptionStyle style, Color fill, Color outline, float size)
	{
		switch (style)
		{
			case OUTLINE:
			case KARAOKE:
			{
				Shape shape = g.getFont().createGlyphVector(g.getFontRenderContext(), word).getOutline(x, y);
				g.setStroke(new BasicStroke(Math.max(2f, size / 9f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.setColor(outline);
				g.draw(shape);
				g.setColor(fill);
				g.fill(shape);
				break;
			}
			case SHADOW:
			{
				int off = Math.max(2, Math.round(size / 14f));
				g.setColor(Theme.alpha(outline, outline.getAlpha() / 255.0 * 0.7));
				g.drawString(word, x + off, y + off);
				g.setColor(fill);
				g.drawString(word, x, y);
				break;
			}
			default:
				g.setColor(fill);
				g.drawString(word, x, y);
		}
	}

	private static List<Line> layout(Graphics2D g, Theme theme, String text, int maxWidth, float size)
	{
		List<Line> lines = new ArrayList<>();
		String[] parts = text.split("\\|");
		int lineIndex = 0;
		int wordIndex = 0;
		for (int p = 0; p < parts.length; p++)
		{
			String part = parts[p].trim();
			if (part.isEmpty())
			{
				continue;
			}
			Font font = lines.isEmpty() ? theme.bold(size) : theme.regular(size * 0.72f);
			FontMetrics fm = g.getFontMetrics(font);
			for (String row : wrap(part, fm, maxWidth))
			{
				String[] words = row.split(" ");
				lines.add(new Line(words, font, fm, lineIndex++, wordIndex));
				wordIndex += words.length;
			}
		}
		return lines;
	}

	/** Greedy word wrap; a single word wider than the line is kept whole. */
	static List<String> wrap(String text, FontMetrics fm, int maxWidth)
	{
		List<String> rows = new ArrayList<>();
		StringBuilder row = new StringBuilder();
		for (String word : text.trim().split("\\s+"))
		{
			if (row.length() > 0 && fm.stringWidth(row + " " + word) > maxWidth)
			{
				rows.add(row.toString());
				row.setLength(0);
			}
			if (row.length() > 0)
			{
				row.append(' ');
			}
			row.append(word);
		}
		if (row.length() > 0)
		{
			rows.add(row.toString());
		}
		return rows;
	}

	/** Draws {@code text} centred on {@code cx} with its baseline at {@code y}, shrinking it to fit {@code maxWidth}. */
	static void centered(Graphics2D g, String text, int cx, int y, Font font, Color color, int maxWidth)
	{
		FontMetrics fm = g.getFontMetrics(font);
		int w = fm.stringWidth(text);
		if (w > maxWidth && w > 0)
		{
			font = font.deriveFont(AffineTransform.getScaleInstance(maxWidth / (double) w, 1));
			w = maxWidth;
		}
		g.setFont(font);
		g.setColor(color);
		g.drawString(text, cx - w / 2, y);
	}

	private static boolean hasDigit(String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			if (Character.isDigit(s.charAt(i)))
			{
				return true;
			}
		}
		return false;
	}

	static double clamp(double v)
	{
		return v < 0 ? 0 : v > 1 ? 1 : v;
	}

	/** Ease-out cubic. */
	static double ease(double p)
	{
		double q = 1 - p;
		return 1 - q * q * q;
	}
}

package com.gielinorwrapped;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.io.ByteArrayOutputStream;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.time.LocalDate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.DrawManager;

/**
 * Keeps a rolling buffer of scaled-down game frames and saves a clip around each highlight moment, plus a
 * still every few seconds for the timelapse. Frames are copied on the client thread into one of two
 * reusable buffers, then scaled, blurred and compressed on the frame thread; if it falls behind, frames
 * are skipped. Files are written on the media thread.
 */
@Slf4j
class Capture
{
	private static final int BUFFERS = 2;
	private static final float CLIP_QUALITY = 0.92f;
	/** Interface parts that cover the game in the resizable layouts; fixed mode keeps them outside the view. */
	private static final int[] INTERFACE_PANELS = {
		InterfaceID.ToplevelOsrsStretch.SIDE_CONTAINER, InterfaceID.ToplevelOsrsStretch.MAP_CONTAINER, InterfaceID.ToplevelOsrsStretch.CHAT_CONTAINER,
		InterfaceID.ToplevelPreEoc.SIDE_CONTAINER, InterfaceID.ToplevelPreEoc.MAP_CONTAINER, InterfaceID.ToplevelPreEoc.CHAT_CONTAINER,
	};
	/** A clip that keeps being extended by new moments is cut off at this length. */
	private static final long MAX_CLIP_MS = 30_000;
	/** Extra footage kept past what a clip needs, for timing jitter. */
	private static final long KEEP_SLACK_MS = 2_000;
	/** Size of the blocks chat is pixelated into, in clip pixels. */
	private static final int BLUR_BLOCK = 10;
	/** Largest share of the frame one hidden chat area may cover. */
	static final double MAX_HIDDEN_SHARE = 0.25;

	private final Client client;
	private final DrawManager drawManager;
	private final GielinorWrappedConfig config;
	private final ClipLibrary library;
	private final Runnable frameListener = this::onFrame;
	private final Deque<ClipFile.Frame> frames = new ArrayDeque<>();
	private final Queue<BufferedImage> spare = new ConcurrentLinkedQueue<>();
	private final AtomicInteger buffers = new AtomicInteger();
	/** The frame scaled to the clip width, reused for each frame. Frame thread only. */
	private BufferedImage scaled;

	private ScheduledThreadPoolExecutor worker;
	private ExecutorService writer;
	private long lastRequest;
	private boolean requestPending;
	private long lastTimelapse;
	/** The clip being recorded; touched on the client thread only. */
	private Pending pending;
	/** The footage recording in progress, or null. */
	private volatile Footage footage;
	/** Waiting for the player to start an emote: the time it was armed, or 0. Client thread. */
	private long emoteArmed;
	private long emoteAccount;
	/** The emote being captured; client thread. */
	private EmoteTake emoteTake;
	/** Gap between cutouts of the same NPC; a later, bigger one replaces the stored picture. */
	static final long NPC_RETRY_MS = 45_000;
	/** NPCs cut out this session, by safe name, with when the next try is due. */
	private final Map<String, Long> npcsCut = new ConcurrentHashMap<>();
	private Listener listener = new Listener()
	{
	};

	/** Hears about recordings starting and stopping, and captures finishing. Called on any thread. */
	interface Listener
	{
		default void footage(boolean recording, long start)
		{
		}

		default void message(String text)
		{
		}

		/** The account's list of recordings changed. Media thread. */
		default void recordings(long account)
		{
		}
	}

	/** A recording the player started; frames are written as they come. */
	private static final class Footage
	{
		final long account;
		final long start;
		final long stopAt;
		/** Opened and used on the media thread. */
		ClipLibrary.FootageWriter out;
		boolean failed;

		Footage(long account, long start, long stopAt)
		{
			this.account = account;
			this.start = start;
			this.stopAt = stopAt;
		}
	}

	/** The player's emote being cut out of the game view, frame by frame. */
	private static final class EmoteTake
	{
		static final int FPS = 15;
		static final long MAX_MS = 8000;
		final long account;
		final long start;
		final List<ClipFile.Frame> frames = new ArrayList<>();
		/** Crop box size in canvas pixels, fixed by the first frame so the player stays put. */
		int boxW;
		int boxH;
		long lastFrame;
		long idleSince;

		EmoteTake(long account, long start)
		{
			this.account = account;
			this.start = start;
		}
	}

	/** A clip waiting for its after-moment footage; more moments can join it. */
	private final class Pending
	{
		final long account;
		final long start;
		long from;
		long to;
		int importance;
		final List<Moment> moments = new ArrayList<>();
		ScheduledFuture<?> due;

		Pending(long account, long start)
		{
			this.account = account;
			this.start = start;
		}
	}

	Capture(Client client, DrawManager drawManager, GielinorWrappedConfig config, ClipLibrary library)
	{
		this.client = client;
		this.drawManager = drawManager;
		this.config = config;
		this.library = library;
	}

	void start()
	{
		worker = new ScheduledThreadPoolExecutor(1, r ->
		{
			Thread t = new Thread(r, "gielinor-wrapped-frames");
			t.setDaemon(true);
			return t;
		});
		worker.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);
		writer = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "gielinor-wrapped-media");
			t.setDaemon(true);
			return t;
		});
		drawManager.registerEveryFrameListener(frameListener);
	}

	void setListener(Listener listener)
	{
		this.listener = listener;
	}

	/** Stops recording; clips already being written are finished. */
	void stop() throws InterruptedException
	{
		drawManager.unregisterEveryFrameListener(frameListener);
		pending = null;
		stopFootage();
		emoteArmed = 0;
		emoteTake = null;
		if (worker != null)
		{
			// Drop queued frame work; a task already running finishes.
			worker.getQueue().clear();
			worker.shutdown();
			worker = null;
		}
		if (writer != null)
		{
			writer.shutdown();
			if (!writer.awaitTermination(5, TimeUnit.SECONDS))
			{
				log.warn("Gielinor Wrapped is still writing a clip; it finishes in the background");
			}
			writer = null;
		}
		clear();
	}

	private void clear()
	{
		synchronized (frames)
		{
			frames.clear();
		}
		while (spare.poll() != null)
		{
			buffers.decrementAndGet();
		}
	}

	/** Whether a moment of this kind gets a clip under the current settings. */
	static boolean wanted(Moment m, GielinorWrappedConfig config)
	{
		switch (m.type)
		{
			case LEVEL_UP:
			case MAX_LEVEL:
				return config.clipLevels();
			case DROP:
				return config.clipDrops();
			case CLUE:
				return config.clipDrops() && m.importance >= 50;
			case PET:
			case COLLECTION_LOG:
				return config.clipPets();
			case PERSONAL_BEST:
			case KILL_COUNT:
			case QUEST:
			case COMBAT_TASK:
			case DIARY:
				return config.clipBosses();
			case DEATH:
				return config.clipDeaths();
			case MANUAL:
				return true;
			default:
				return false;
		}
	}

	/**
	 * Called on the client thread for each new moment. {@code saved} is run on the media thread with each
	 * moment and the clip's file name once it is on disk.
	 */
	void onMoment(long account, Moment m, BiConsumer<Moment, String> saved)
	{
		ScheduledExecutorService w = worker;
		if (w == null || account == -1 || !config.recordClips() || !wanted(m, config))
		{
			return;
		}
		long before = config.clipBefore() * 1000L;
		long after = config.clipAfter() * 1000L;
		Pending p = pending;
		if (p != null && p.account == account && m.time <= p.to && m.time + after - p.from <= MAX_CLIP_MS && p.due != null && p.due.cancel(false))
		{
			p.to = Math.max(p.to, m.time + after);
		}
		else
		{
			p = new Pending(account, m.time);
			p.from = m.time - before;
			p.to = m.time + after;
			pending = p;
		}
		p.importance = Math.max(p.importance, m.importance);
		p.moments.add(m);
		Pending clip = p;
		long delay = Math.max(0, clip.to - System.currentTimeMillis()) + 200;
		try
		{
			clip.due = w.schedule(() -> take(clip, saved), delay, TimeUnit.MILLISECONDS);
		}
		catch (RejectedExecutionException e)
		{
			// Shutting down.
		}
	}

	/** Runs on the frame thread once the clip's last frame is due. */
	private void take(Pending p, BiConsumer<Moment, String> saved)
	{
		List<ClipFile.Frame> clip = new ArrayList<>();
		synchronized (frames)
		{
			for (ClipFile.Frame f : frames)
			{
				if (f.time >= p.from && f.time <= p.to)
				{
					clip.add(f);
				}
			}
		}
		log.debug("Clip: {} frames for {} moments", clip.size(), p.moments.size());
		if (clip.size() < 2)
		{
			return;
		}
		List<Moment> moments = new ArrayList<>(p.moments);
		execute(writer, () ->
		{
			try
			{
				String name = library.writeClip(p.account, p.start, p.importance, clip);
				for (Moment m : moments)
				{
					saved.accept(m, name);
				}
				library.prune(p.account, config.diskBudget() * 1024L * 1024L, LocalDate.now());
			}
			catch (Exception e)
			{
				log.warn("Unable to save clip", e);
			}
		});
	}

	/** Called on the client thread each game tick to take timelapse stills. */
	void onTick(long account)
	{
		if (worker != null && account != -1 && config.bossStickers())
		{
			npcCutout(account);
		}
		if (worker == null || account == -1 || !config.timelapse())
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (now - lastTimelapse < config.timelapseInterval() * 1000L)
		{
			return;
		}
		lastTimelapse = now;
		LocalDate date = LocalDate.now();
		onNextFrame(image ->
		{
			BufferedImage copy = copy(image, null);
			List<Rectangle> hidden = hiddenAreas(image);
			execute(worker, () ->
			{
				try
				{
					ClipFile.Frame frame = new ClipFile.Frame(now, ClipFile.encode(prepare(copy, hidden), CLIP_QUALITY));
					execute(writer, () ->
					{
						try
						{
							library.appendTimelapse(account, date, frame);
						}
						catch (Exception e)
						{
							log.warn("Unable to save timelapse still", e);
						}
					});
				}
				catch (Exception e)
				{
					log.debug("Unable to compress timelapse still", e);
				}
			});
		});
	}

	boolean isRecording()
	{
		return footage != null;
	}

	/** When the recording in progress started, or 0. */
	long recordingStart()
	{
		Footage f = footage;
		return f == null ? 0 : f.start;
	}

	/** Starts recording footage for the video maker; it stops by itself after the longest recording setting. */
	void startFootage(long account)
	{
		ExecutorService wr = writer;
		if (wr == null || account == -1 || footage != null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		Footage f = new Footage(account, now, now + config.footageMax() * 1000L);
		footage = f;
		execute(wr, () ->
		{
			try
			{
				f.out = library.startFootage(f.account, f.start);
			}
			catch (IOException e)
			{
				f.failed = true;
				log.warn("Unable to start a recording", e);
				listener.message("Unable to start recording: " + e.getMessage());
			}
		});
		listener.footage(true, now);
	}

	/** Stops the recording in progress and saves it; does nothing when there is none. */
	void stopFootage()
	{
		Footage f = footage;
		if (f == null)
		{
			return;
		}
		footage = null;
		listener.footage(false, f.start);
		ExecutorService wr = writer;
		if (wr == null)
		{
			return;
		}
		execute(wr, () ->
		{
			if (f.out == null)
			{
				return;
			}
			try
			{
				ClipLibrary.Recording rec = f.out.finish();
				if (rec != null)
				{
					library.pruneFootage(f.account, config.footageBudget() * 1024L * 1024L, rec.name);
					listener.message(String.format("Recording saved (%d:%02d).", rec.length / 60000, rec.length / 1000 % 60));
					listener.recordings(f.account);
				}
			}
			catch (IOException e)
			{
				log.warn("Unable to save the recording", e);
				listener.message("Unable to save the recording: " + e.getMessage());
			}
		});
	}

	private static void writeFootage(Footage f, ClipFile.Frame frame)
	{
		if (f.out == null || f.failed)
		{
			return;
		}
		try
		{
			f.out.add(frame);
		}
		catch (IOException e)
		{
			f.failed = true;
			log.warn("Unable to write a recording frame", e);
		}
	}

	/** Turns leftovers from a crash into recordings. Media thread. */
	void recover(long account)
	{
		execute(writer, () ->
		{
			library.recoverFootage(account);
			listener.recordings(account);
		});
	}

	/** Gets ready to capture the next emote the player does. Client thread. */
	void armEmote(long account)
	{
		if (account == -1 || client.getGameState() != GameState.LOGGED_IN)
		{
			listener.message("Log in to capture your emote.");
			return;
		}
		emoteArmed = System.currentTimeMillis();
		emoteAccount = account;
		emoteTake = null;
		listener.message("Ready: do an emote in game now. Best with the camera facing you and nothing behind.");
	}

	boolean isEmoteArmed()
	{
		return emoteArmed != 0 || emoteTake != null;
	}

	/** Client thread. Starts the capture when the armed player begins an animation. */
	void onAnimation(Actor actor)
	{
		if (emoteArmed == 0 || actor != client.getLocalPlayer() || actor.getAnimation() == -1)
		{
			return;
		}
		emoteArmed = 0;
		emoteTake = new EmoteTake(emoteAccount, System.currentTimeMillis());
	}

	/** Client thread, every frame: grabs the cut-out player while an emote is being captured. */
	private void emoteFrame(long now)
	{
		if (emoteArmed != 0 && now - emoteArmed > 30_000)
		{
			emoteArmed = 0;
			listener.message("Emote capture timed out. Press capture, then do an emote.");
		}
		EmoteTake take = emoteTake;
		if (take == null || now - take.lastFrame < 1000 / EmoteTake.FPS)
		{
			return;
		}
		Player me = client.getLocalPlayer();
		boolean idle = me == null || me.getAnimation() == -1;
		if (idle && take.idleSince == 0)
		{
			take.idleSince = now;
		}
		else if (!idle)
		{
			take.idleSince = 0;
		}
		if (me == null || now - take.start > EmoteTake.MAX_MS || (take.idleSince != 0 && now - take.idleSince > 300))
		{
			emoteTake = null;
			finishEmote(take);
			return;
		}
		take.lastFrame = now;
		onNextFrame(image ->
		{
			Player p = client.getLocalPlayer();
			if (p == null || emoteTake != take)
			{
				return;
			}
			Shape hull = p.getConvexHull();
			LocalPoint lp = p.getLocalLocation();
			Point foot = lp == null ? null : Perspective.localToCanvas(client, lp, p.getWorldView().getPlane());
			if (hull == null || foot == null)
			{
				return;
			}
			Rectangle hb = hull.getBounds();
			if (take.boxH == 0)
			{
				take.boxH = Math.max(40, (int) (hb.height * 1.5));
				take.boxW = take.boxH;
			}
			Rectangle box = new Rectangle(foot.getX() - take.boxW / 2, foot.getY() - take.boxH * 9 / 10, take.boxW, take.boxH);
			BufferedImage cut = cutout(image, hull, box, scaleOf(image));
			if (cut == null)
			{
				return;
			}
			long time = System.currentTimeMillis();
			execute(worker, () ->
			{
				try
				{
					take.frames.add(new ClipFile.Frame(time, png(cut)));
				}
				catch (IOException e)
				{
					log.debug("Unable to compress an emote frame", e);
				}
			});
		});
	}

	private void finishEmote(EmoteTake take)
	{
		// Queued behind the last frames' compression.
		execute(worker, () ->
		{
			List<ClipFile.Frame> got = new ArrayList<>(take.frames);
			if (got.size() < 3 || Emote.of(got) == null)
			{
				listener.message("Couldn't see your character for the emote. Face the camera and try again.");
				return;
			}
			execute(writer, () ->
			{
				try
				{
					library.writeEmote(take.account, got);
					listener.message("Emote captured (" + got.size() + " frames). It will dance in your next video.");
				}
				catch (IOException e)
				{
					log.warn("Unable to save the emote", e);
					listener.message("Unable to save the emote: " + e.getMessage());
				}
			});
		});
	}

	/**
	 * Client thread, each tick: cuts out a monster the player is fighting or being attacked by, to use as a
	 * sticker in recaps. Each one is tried again every {@link #NPC_RETRY_MS} so a closer view can replace a
	 * small first picture.
	 */
	private void npcCutout(long account)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		NPC npc = null;
		String name = null;
		Actor target = me.getInteracting();
		if (target instanceof NPC)
		{
			name = cutoutName((NPC) target, now);
			npc = name == null ? null : (NPC) target;
		}
		if (npc == null)
		{
			for (NPC other : client.getTopLevelWorldView().npcs())
			{
				if (other != null && other.getInteracting() == me)
				{
					name = cutoutName(other, now);
					if (name != null)
					{
						npc = other;
						break;
					}
				}
			}
		}
		if (npc == null)
		{
			return;
		}
		cutNpc(account, npc, name, now);
	}

	/** The safe name of a monster due a cutout, or null when it isn't one or was cut out recently. */
	private String cutoutName(NPC npc, long now)
	{
		if (npc.getName() == null || npc.getCombatLevel() <= 0)
		{
			return null;
		}
		String name = ClipLibrary.safeName(net.runelite.client.util.Text.removeTags(npc.getName()));
		return name.isEmpty() || npcsCut.getOrDefault(name, 0L) > now ? null : name;
	}

	private void cutNpc(long account, NPC npc, String name, long now)
	{
		npcsCut.put(name, now + NPC_RETRY_MS);
		onNextFrame(image ->
		{
			Shape hull = npc.getConvexHull();
			if (hull == null)
			{
				npcsCut.remove(name, now + NPC_RETRY_MS);
				return;
			}
			Rectangle b = hull.getBounds();
			if (b.width < 24 || b.height < 24 || !unobstructed(b))
			{
				// Too far away, or partly off screen or behind the interface; try again later.
				npcsCut.remove(name, now + NPC_RETRY_MS);
				return;
			}
			BufferedImage cut = cutout(image, hull, b, scaleOf(image));
			if (cut == null)
			{
				npcsCut.remove(name, now + NPC_RETRY_MS);
				return;
			}
			long area = (long) cut.getWidth() * cut.getHeight();
			execute(worker, () ->
			{
				try
				{
					byte[] png = png(cut);
					execute(writer, () ->
					{
						try
						{
							// Keep the first picture unless this one is clearly bigger, so a far-away cutout gets replaced.
							if (area * 2 > library.npcArea(account, name) * 3)
							{
								library.writeNpc(account, name, png);
							}
						}
						catch (IOException e)
						{
							log.debug("Unable to save NPC cutout", e);
						}
					});
				}
				catch (IOException e)
				{
					log.debug("Unable to compress NPC cutout", e);
				}
			});
		});
	}

	/**
	 * True when {@code box}, in canvas pixels, lies inside the game view and clear of the side panel, minimap
	 * and chatbox, which draw over the game in resizable mode. Client thread.
	 */
	private boolean unobstructed(Rectangle box)
	{
		Rectangle view = new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(), client.getViewportWidth(), client.getViewportHeight());
		if (!view.contains(box))
		{
			return false;
		}
		List<Rectangle> panels = new ArrayList<>();
		for (int id : INTERFACE_PANELS)
		{
			addBounds(client.getWidget(id), panels);
		}
		return clearOf(box, panels, view);
	}

	/**
	 * True when {@code box} touches none of {@code panels}. A panel covering more than half the view is a
	 * layer spanning the screen rather than something drawn over the game, so it is ignored.
	 */
	static boolean clearOf(Rectangle box, List<Rectangle> panels, Rectangle view)
	{
		for (Rectangle p : panels)
		{
			if ((double) p.width * p.height <= 0.5 * view.width * view.height && p.intersects(box))
			{
				return false;
			}
		}
		return true;
	}

	/** Frame pixels per canvas pixel. Client thread. */
	private double[] scaleOf(Image image)
	{
		if (client.isStretchedEnabled() && client.getRealDimensions() != null)
		{
			return new double[]{image.getWidth(null) / (double) client.getRealDimensions().width, image.getHeight(null) / (double) client.getRealDimensions().height};
		}
		return new double[]{1, 1};
	}

	/**
	 * The part of {@code frame} inside {@code shape}, on transparency, cropped to {@code box}; shape and box are
	 * in canvas pixels. Null when the box is off screen.
	 */
	static BufferedImage cutout(Image frame, Shape shape, Rectangle box, double[] scale)
	{
		int fw = frame.getWidth(null);
		int fh = frame.getHeight(null);
		Rectangle fb = new Rectangle((int) (box.x * scale[0]), (int) (box.y * scale[1]), (int) Math.ceil(box.width * scale[0]), (int) Math.ceil(box.height * scale[1]));
		if (fb.width < 8 || fb.height < 8 || !fb.intersects(new Rectangle(0, 0, fw, fh)))
		{
			return null;
		}
		// Cutouts are small in a recap; keep them under 320 px.
		double down = Math.min(1, 320.0 / Math.max(fb.width, fb.height));
		int w = Math.max(1, (int) (fb.width * down));
		int h = Math.max(1, (int) (fb.height * down));
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.scale(down, down);
		g.translate(-fb.x, -fb.y);
		AffineTransform toFrame = AffineTransform.getScaleInstance(scale[0], scale[1]);
		g.clip(toFrame.createTransformedShape(shape));
		g.drawImage(frame, 0, 0, null);
		g.dispose();
		return out;
	}

	private static byte[] png(BufferedImage img) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream(32 * 1024);
		ImageIO.write(img, "png", out);
		return out.toByteArray();
	}

	private void onFrame()
	{
		long now = System.currentTimeMillis();
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		Footage rec = footage;
		if (rec != null && (!loggedIn || now >= rec.stopAt))
		{
			stopFootage();
			rec = null;
		}
		if (loggedIn)
		{
			emoteFrame(now);
		}
		boolean clips = config.recordClips();
		if ((!clips && rec == null) || !loggedIn)
		{
			if (!frames.isEmpty())
			{
				clear();
			}
			return;
		}
		int fps = rec == null ? config.clipFps() : Math.max(config.footageFps(), clips ? config.clipFps() : 0);
		long interval = 1000L / Math.max(1, fps);
		// If a requested frame never arrived (e.g. the window was minimised), ask again.
		if (now - lastRequest < interval || (requestPending && now - lastRequest < 1000))
		{
			return;
		}
		lastRequest = now;
		requestPending = true;
		onNextFrame(image ->
		{
			requestPending = false;
			ScheduledExecutorService w = worker;
			BufferedImage buffer = w == null ? null : buffer(image.getWidth(null), image.getHeight(null));
			if (buffer == null)
			{
				return;
			}
			try
			{
				copy(image, buffer);
			}
			catch (OutOfMemoryError e)
			{
				spare.offer(buffer);
				throw e;
			}
			List<Rectangle> hidden = hiddenAreas(image);
			long time = System.currentTimeMillis();
			// Keep enough for a new moment's lead-in, plus everything a clip still being recorded needs.
			long keepFrom = time - config.clipBefore() * 1000L - KEEP_SLACK_MS;
			Pending p = pending;
			if (p != null && time <= p.to + KEEP_SLACK_MS * 5)
			{
				keepFrom = Math.min(keepFrom, p.from);
			}
			long cutoff = keepFrom;
			try
			{
				w.execute(() ->
				{
					try
					{
						ClipFile.Frame frame = new ClipFile.Frame(time, ClipFile.encode(prepare(buffer, hidden), CLIP_QUALITY));
						synchronized (frames)
						{
							frames.addLast(frame);
							while (!frames.isEmpty() && frames.peekFirst().time < cutoff)
							{
								frames.pollFirst();
							}
						}
					}
					catch (Exception | OutOfMemoryError e)
					{
						log.debug("Unable to compress clip frame", e);
					}
					finally
					{
						spare.offer(buffer);
					}
				});
			}
			catch (RejectedExecutionException e)
			{
				spare.offer(buffer);
			}
		});
	}

	/**
	 * Grabs the next frame at full size for a recap shot, cropped to the game view if asked, with chat hidden
	 * per the settings. {@code done} runs on {@code executor}. Client thread.
	 */
	void shot(boolean gameView, ExecutorService executor, Consumer<BufferedImage> done)
	{
		onNextFrame(image ->
		{
			BufferedImage copy = copy(image, null);
			List<Rectangle> hidden = hiddenAreas(image);
			Rectangle crop = gameView ? viewport(image) : null;
			execute(executor, () -> done.accept(shotImage(copy, crop, hidden)));
		});
	}

	/** The 3D game view in frame pixels, or null when it isn't known. Client thread only. */
	private Rectangle viewport(Image image)
	{
		int vw = client.getViewportWidth();
		int vh = client.getViewportHeight();
		if (vw <= 0 || vh <= 0)
		{
			return null;
		}
		double sx = 1;
		double sy = 1;
		if (client.isStretchedEnabled() && client.getRealDimensions() != null)
		{
			sx = image.getWidth(null) / (double) client.getRealDimensions().width;
			sy = image.getHeight(null) / (double) client.getRealDimensions().height;
		}
		return new Rectangle((int) (client.getViewportXOffset() * sx), (int) (client.getViewportYOffset() * sy), (int) (vw * sx), (int) (vh * sy));
	}

	/** Pixelates the hidden areas of a full-size frame, then crops it. */
	static BufferedImage shotImage(BufferedImage full, Rectangle crop, List<Rectangle> hidden)
	{
		// Blocks as coarse as in a clip of the usual width, so chat stays unreadable at full size.
		int block = Math.max(BLUR_BLOCK, BLUR_BLOCK * full.getWidth() / 640);
		for (Rectangle r : hidden)
		{
			pixelate(full, r, block);
		}
		Rectangle c = crop == null ? null : crop.intersection(new Rectangle(0, 0, full.getWidth(), full.getHeight()));
		if (c == null || c.width < 16 || c.height < 16 || c.getSize().equals(new java.awt.Dimension(full.getWidth(), full.getHeight())))
		{
			return full;
		}
		BufferedImage out = new BufferedImage(c.width, c.height, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.drawImage(full, -c.x, -c.y, null);
		g.dispose();
		return out;
	}

	/** Chat areas to blur, in frame pixels. Client thread only. */
	private List<Rectangle> hiddenAreas(Image image)
	{
		List<Rectangle> areas = new ArrayList<>();
		if (!config.hideChat())
		{
			return areas;
		}
		double sx = 1;
		double sy = 1;
		if (client.isStretchedEnabled() && client.getRealDimensions() != null)
		{
			sx = image.getWidth(null) / (double) client.getRealDimensions().width;
			sy = image.getHeight(null) / (double) client.getRealDimensions().height;
		}
		// Only the widgets holding chat text: the chatbox root and the PM container span far
		// more of the screen than the text, up to the whole viewport in resizable mode.
		for (int id : new int[]{InterfaceID.Chatbox.SCROLLAREA, InterfaceID.Chatbox.INPUT})
		{
			addBounds(client.getWidget(id), areas);
		}
		Widget pm = client.getWidget(InterfaceID.PmChat.CONTAINER);
		if (pm != null && !pm.isHidden())
		{
			addTextLines(pm, areas, 0);
		}
		return fitAreas(areas, image.getWidth(null), image.getHeight(null), sx, sy);
	}

	private static void addBounds(Widget w, List<Rectangle> areas)
	{
		if (w != null && !w.isHidden())
		{
			Rectangle b = w.getBounds();
			if (b != null && b.width > 0 && b.height > 0)
			{
				areas.add(b);
			}
		}
	}

	/** Adds every visible descendant of {@code parent} that shows text, such as the private message lines. */
	private static void addTextLines(Widget parent, List<Rectangle> areas, int depth)
	{
		if (depth > 4)
		{
			return;
		}
		for (Widget[] children : new Widget[][]{parent.getStaticChildren(), parent.getDynamicChildren(), parent.getNestedChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget c : children)
			{
				if (c == null || c.isHidden())
				{
					continue;
				}
				String text = c.getText();
				if (text != null && !text.isEmpty())
				{
					addBounds(c, areas);
				}
				addTextLines(c, areas, depth + 1);
			}
		}
	}

	/**
	 * Scales widget bounds to frame pixels and clips them to the frame. An area covering more than
	 * {@link #MAX_HIDDEN_SHARE} of the frame can't be chat text, so it is dropped rather than blurring the game.
	 */
	static List<Rectangle> fitAreas(List<Rectangle> bounds, int width, int height, double sx, double sy)
	{
		Rectangle frame = new Rectangle(0, 0, width, height);
		List<Rectangle> out = new ArrayList<>();
		for (Rectangle b : bounds)
		{
			Rectangle r = new Rectangle((int) (b.x * sx), (int) (b.y * sy), (int) Math.ceil(b.width * sx), (int) Math.ceil(b.height * sy))
				.intersection(frame);
			if (!r.isEmpty() && (double) r.width * r.height <= MAX_HIDDEN_SHARE * width * height)
			{
				out.add(r);
			}
		}
		return out;
	}

	/**
	 * Scales the frame to the clip width and pixelates hidden areas. Frame thread; the result is only good until the
	 * next call.
	 */
	private BufferedImage prepare(BufferedImage full, List<Rectangle> hidden)
	{
		int width = Math.min(full.getWidth(), config.clipWidth());
		double scale = width / (double) full.getWidth();
		int height = width == full.getWidth() ? full.getHeight() : Math.max(2, (int) Math.round(full.getHeight() * scale));
		// Byte BGR rather than int RGB: the JPEG encoder takes it about a third faster.
		if (scaled == null || scaled.getWidth() != width || scaled.getHeight() != height)
		{
			scaled = new BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR);
		}
		BufferedImage out = scaled;
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.drawImage(full, 0, 0, width, height, null);
		g.dispose();
		for (Rectangle r : hidden)
		{
			pixelate(out, new Rectangle((int) (r.x * scale), (int) (r.y * scale), (int) Math.ceil(r.width * scale), (int) Math.ceil(r.height * scale)));
		}
		return out;
	}

	/** Replaces each block in the area with its average colour, so text can't be read back. */
	static void pixelate(BufferedImage image, Rectangle area)
	{
		pixelate(image, area, BLUR_BLOCK);
	}

	static void pixelate(BufferedImage image, Rectangle area, int block)
	{
		Rectangle r = area.intersection(new Rectangle(0, 0, image.getWidth(), image.getHeight()));
		if (r.isEmpty())
		{
			return;
		}
		int[] px = image.getRGB(r.x, r.y, r.width, r.height, null, 0, r.width);
		for (int by = 0; by < r.height; by += block)
		{
			for (int bx = 0; bx < r.width; bx += block)
			{
				int ex = Math.min(bx + block, r.width);
				int ey = Math.min(by + block, r.height);
				long red = 0;
				long green = 0;
				long blue = 0;
				for (int y = by; y < ey; y++)
				{
					for (int x = bx; x < ex; x++)
					{
						int c = px[y * r.width + x];
						red += (c >> 16) & 0xFF;
						green += (c >> 8) & 0xFF;
						blue += c & 0xFF;
					}
				}
				int n = (ex - bx) * (ey - by);
				int avg = (int) (red / n) << 16 | (int) (green / n) << 8 | (int) (blue / n);
				for (int y = by; y < ey; y++)
				{
					for (int x = bx; x < ex; x++)
					{
						px[y * r.width + x] = avg;
					}
				}
			}
		}
		image.setRGB(r.x, r.y, r.width, r.height, px, 0, r.width);
	}

	/**
	 * Runs {@code listener} on the next frame. Copying a full frame runs on the client thread, so running out
	 * of memory there would stop the client; skip that frame instead.
	 */
	private void onNextFrame(Consumer<Image> listener)
	{
		drawManager.requestNextFrameListener(image ->
		{
			try
			{
				listener.accept(image);
			}
			catch (OutOfMemoryError e)
			{
				log.warn("Not enough memory to copy a frame; skipped it");
			}
		});
	}

	private BufferedImage buffer(int width, int height)
	{
		BufferedImage b;
		while ((b = spare.poll()) != null)
		{
			if (b.getWidth() == width && b.getHeight() == height)
			{
				return b;
			}
			buffers.decrementAndGet();
		}
		if (buffers.incrementAndGet() > BUFFERS)
		{
			buffers.decrementAndGet();
			return null;
		}
		try
		{
			return new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		}
		catch (OutOfMemoryError e)
		{
			buffers.decrementAndGet();
			throw e;
		}
	}

	private static BufferedImage copy(Image image, BufferedImage into)
	{
		BufferedImage out = into != null ? into : new BufferedImage(image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.drawImage(image, 0, 0, null);
		g.dispose();
		return out;
	}

	private static void execute(ExecutorService executor, Runnable task)
	{
		if (executor == null)
		{
			return;
		}
		try
		{
			executor.execute(task);
		}
		catch (RejectedExecutionException e)
		{
			// Shutting down.
		}
	}
}

package com.gielinorwrapped;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Recognises the game messages Wrapped counts. Input is a game message with colour tags already removed. */
final class ChatParser
{
	enum Kind
	{
		KILL_COUNT,
		CLUE,
		PET,
		COLLECTION_LOG,
		QUEST,
		COMBAT_TASK,
		DIARY,
		PERSONAL_BEST,
		/** A kill time that isn't a personal best. */
		DURATION,
		SLAYER_TASK
	}

	static final class Result
	{
		final Kind kind;
		/** Boss, clue tier, item, quest, task, area or Slayer monster name. */
		final String name;
		/** Kill count, clue count, kill time in seconds or Slayer task size; 0 when the message has none. */
		final long number;
		/** Extra detail: the task tier for combat tasks and diaries, the duration text for personal bests. */
		final String detail;

		Result(Kind kind, String name, long number, String detail)
		{
			this.kind = kind;
			this.name = name;
			this.number = number;
			this.detail = detail;
		}
	}

	private static final Pattern KILL_COUNT = Pattern.compile("Your (?:completed |subdued )?(.+?) (?:kill |success |completion |lap )?count is: ?([\\d,]+)\\.?");
	private static final Pattern CLUE = Pattern.compile("You have completed ([\\d,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?");
	private static final Pattern PET = Pattern.compile("You (?:have a funny feeling like you(?:'re being| would have been) followed|feel something weird sneaking into your backpack).*");
	private static final Pattern COLLECTION_LOG = Pattern.compile("New item added to your collection log: (.+)");
	private static final Pattern QUEST = Pattern.compile("Congratulations, you've completed a quest: (.+?)\\.?");
	private static final Pattern COMBAT_TASK = Pattern.compile("Congratulations, you've completed an? (easy|medium|hard|elite|master|grandmaster) combat task: (.+?)(?: \\(\\d+ points?\\))?\\.?");
	private static final Pattern DIARY = Pattern.compile("Well done! You have completed an? (easy|medium|hard|elite) task in the (.+?) area\\..*");
	private static final Pattern PERSONAL_BEST = Pattern.compile(".*?[Dd]uration: ([\\d:.]+) \\(new personal best\\).*");
	private static final Pattern DURATION = Pattern.compile(".*?[Dd]uration: (\\d+(?::\\d+)+(?:\\.\\d+)?).*");
	private static final Pattern SLAYER_TASK = Pattern.compile("You(?:'ve| have) completed your (?:boss )?task! You killed ([\\d,]+) (.+?)\\..*|You(?:'ve| have) completed your (?:boss )?task!.*");

	private ChatParser()
	{
	}

	static Result parse(String message)
	{
		if (message == null || message.isEmpty())
		{
			return null;
		}
		Matcher m = KILL_COUNT.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.KILL_COUNT, m.group(1), number(m.group(2)), null);
		}
		m = CLUE.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.CLUE, m.group(2), number(m.group(1)), null);
		}
		if (PET.matcher(message).matches())
		{
			return new Result(Kind.PET, "Pet", 0, null);
		}
		m = COLLECTION_LOG.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.COLLECTION_LOG, m.group(1).trim(), 0, null);
		}
		m = QUEST.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.QUEST, m.group(1).trim(), 0, null);
		}
		m = COMBAT_TASK.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.COMBAT_TASK, m.group(2).trim(), 0, m.group(1));
		}
		m = DIARY.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.DIARY, m.group(2).trim(), 0, m.group(1));
		}
		m = PERSONAL_BEST.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.PERSONAL_BEST, null, seconds(m.group(1)), m.group(1));
		}
		m = DURATION.matcher(message);
		if (m.matches())
		{
			return new Result(Kind.DURATION, null, seconds(m.group(1)), m.group(1));
		}
		m = SLAYER_TASK.matcher(message);
		if (m.matches())
		{
			return m.group(2) != null
				? new Result(Kind.SLAYER_TASK, m.group(2).trim(), number(m.group(1)), null)
				: new Result(Kind.SLAYER_TASK, null, 0, null);
		}
		return null;
	}

	private static long number(String s)
	{
		try
		{
			return Long.parseLong(s.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** "1:23.40" or "1:02:03" to whole seconds. */
	static long seconds(String s)
	{
		long total = 0;
		for (String part : s.split(":"))
		{
			int dot = part.indexOf('.');
			total = total * 60 + number(dot >= 0 ? part.substring(0, dot) : part);
		}
		return total;
	}
}

package com.gielinorwrapped;

import java.awt.Color;
import java.awt.image.BufferedImage;

/**
 * Green screen keying: makes pixels near the key colour transparent. Distance is measured on chroma
 * (colour without brightness), so shadows on the screen still key out.
 */
final class Chroma
{
	final int key;
	/** Chroma distance, 0 to 1, under which a pixel is fully cut. */
	final double tolerance;
	/** Extra distance over which a pixel fades back in. */
	final double softness;
	final boolean spill;
	private final double keyCb;
	private final double keyCr;

	Chroma(Color key, int tolerancePercent, int softnessPercent, boolean spill)
	{
		this.key = key.getRGB() & 0xFFFFFF;
		this.tolerance = tolerancePercent / 100.0 * 0.5;
		this.softness = Math.max(0.005, softnessPercent / 100.0 * 0.3);
		this.spill = spill;
		double[] c = chroma(key.getRed(), key.getGreen(), key.getBlue());
		keyCb = c[0];
		keyCr = c[1];
	}

	static Chroma of(GielinorWrappedConfig config)
	{
		return config.chromaKey() ? new Chroma(config.chromaColor(), config.chromaTolerance(), config.chromaSoftness(), config.chromaSpill()) : null;
	}

	private static double[] chroma(int r, int g, int b)
	{
		double cb = (-0.168736 * r - 0.331264 * g + 0.5 * b) / 255.0;
		double cr = (0.5 * r - 0.418688 * g - 0.081312 * b) / 255.0;
		return new double[]{cb, cr};
	}

	/** The share of {@code img} that keys out, sampled sparsely; a green-screen recording is mostly key colour. */
	double coverage(BufferedImage img)
	{
		int w = img.getWidth();
		int h = img.getHeight();
		int step = Math.max(1, Math.min(w, h) / 60);
		int hits = 0;
		int total = 0;
		for (int y = step / 2; y < h; y += step)
		{
			for (int x = step / 2; x < w; x += step)
			{
				int p = img.getRGB(x, y);
				double[] c = chroma(p >> 16 & 0xFF, p >> 8 & 0xFF, p & 0xFF);
				if (Math.hypot(c[0] - keyCb, c[1] - keyCr) < tolerance + softness * 0.5)
				{
					hits++;
				}
				total++;
			}
		}
		return total == 0 ? 0 : hits / (double) total;
	}

	/** A keyed ARGB copy of {@code src}. */
	BufferedImage key(BufferedImage src)
	{
		int w = src.getWidth();
		int h = src.getHeight();
		int[] px = src.getRGB(0, 0, w, h, null, 0, w);
		int kr = key >> 16 & 0xFF;
		int kg = key >> 8 & 0xFF;
		int kb = key & 0xFF;
		// The key's strongest channel is the one spill shows up in.
		int dominant = kg >= kr && kg >= kb ? 1 : kb >= kr ? 2 : 0;
		for (int i = 0; i < px.length; i++)
		{
			int p = px[i];
			int r = p >> 16 & 0xFF;
			int g = p >> 8 & 0xFF;
			int b = p & 0xFF;
			double cb = (-0.168736 * r - 0.331264 * g + 0.5 * b) / 255.0;
			double cr = (0.5 * r - 0.418688 * g - 0.081312 * b) / 255.0;
			double d = Math.hypot(cb - keyCb, cr - keyCr);
			double a = Captions.clamp((d - tolerance) / softness);
			a = a * a * (3 - 2 * a);
			int alpha = (int) Math.round(a * (p >>> 24));
			if (alpha == 0)
			{
				px[i] = 0;
				continue;
			}
			if (spill && d < tolerance + softness * 3)
			{
				// Near the key only, so green things in the scene stay green: clamp the key channel to the brighter of the other two.
				switch (dominant)
				{
					case 1:
						g = Math.min(g, Math.max(r, b));
						break;
					case 2:
						b = Math.min(b, Math.max(r, g));
						break;
					default:
						r = Math.min(r, Math.max(g, b));
				}
			}
			px[i] = alpha << 24 | r << 16 | g << 8 | b;
		}
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		out.setRGB(0, 0, w, h, px, 0, w);
		return out;
	}
}

package com.gielinorwrapped;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntPredicate;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.ImageOutputStream;
import javax.imageio.stream.MemoryCacheImageOutputStream;
import org.w3c.dom.NodeList;

/**
 * A recorded clip: JPEG frames, each with its capture time. The file is the magic {@code GWC1} followed
 * by records of (long time ms, int length, JPEG bytes) up to the end of the file, so timelapses can be
 * appended to frame by frame. A truncated last record (a crash mid-write) is ignored.
 */
final class ClipFile
{
	private static final int MAGIC = 0x47574331;
	private static final int MAX_FRAME = 16 * 1024 * 1024;
	private static final String JPEG_FORMAT = "javax_imageio_jpeg_image_1.0";

	static final class Frame
	{
		final long time;
		final byte[] jpeg;

		Frame(long time, byte[] jpeg)
		{
			this.time = time;
			this.jpeg = jpeg;
		}

		BufferedImage image() throws IOException
		{
			return decode(jpeg);
		}
	}

	private ClipFile()
	{
	}

	static void writeHeader(OutputStream out) throws IOException
	{
		new DataOutputStream(out).writeInt(MAGIC);
	}

	static void writeFrame(OutputStream out, Frame frame) throws IOException
	{
		DataOutputStream data = new DataOutputStream(out);
		data.writeLong(frame.time);
		data.writeInt(frame.jpeg.length);
		data.write(frame.jpeg);
		data.flush();
	}

	static void write(OutputStream out, List<Frame> frames) throws IOException
	{
		writeHeader(out);
		for (Frame f : frames)
		{
			writeFrame(out, f);
		}
	}

	static List<Frame> read(InputStream in) throws IOException
	{
		List<Frame> frames = new ArrayList<>();
		read(in, 0, i -> true, frames);
		return frames;
	}

	/**
	 * Reads the frames {@code keep} accepts, skipping the image data of the rest.
	 *
	 * @param index index of the file's first frame, so selections can span several files
	 * @return the index after the file's last frame
	 */
	static int read(InputStream in, int index, IntPredicate keep, List<Frame> out) throws IOException
	{
		DataInputStream data = new DataInputStream(in);
		if (data.readInt() != MAGIC)
		{
			throw new IOException("Not a Gielinor Wrapped clip");
		}
		while (true)
		{
			long time;
			try
			{
				time = data.readLong();
			}
			catch (EOFException e)
			{
				break;
			}
			try
			{
				int length = data.readInt();
				if (length <= 0 || length > MAX_FRAME)
				{
					throw new IOException("Corrupt clip frame");
				}
				if (keep.test(index))
				{
					byte[] jpeg = new byte[length];
					data.readFully(jpeg);
					out.add(new Frame(time, jpeg));
				}
				else
				{
					skipFully(data, length);
				}
				index++;
			}
			catch (EOFException e)
			{
				break;
			}
		}
		return index;
	}

	/** Reads the frames captured between {@code from} and {@code to} inclusive, plus the one before {@code from} so playback can start on it. */
	static List<Frame> readRange(InputStream in, long from, long to) throws IOException
	{
		DataInputStream data = new DataInputStream(in);
		if (data.readInt() != MAGIC)
		{
			throw new IOException("Not a Gielinor Wrapped clip");
		}
		List<Frame> out = new ArrayList<>();
		Frame before = null;
		while (true)
		{
			try
			{
				long time = data.readLong();
				int length = data.readInt();
				if (length <= 0 || length > MAX_FRAME)
				{
					throw new IOException("Corrupt clip frame");
				}
				if (time > to)
				{
					break;
				}
				byte[] jpeg = new byte[length];
				data.readFully(jpeg);
				if (time < from)
				{
					before = new Frame(time, jpeg);
				}
				else
				{
					if (before != null && out.isEmpty())
					{
						out.add(before);
					}
					out.add(new Frame(time, jpeg));
				}
			}
			catch (EOFException e)
			{
				break;
			}
		}
		if (out.isEmpty() && before != null)
		{
			out.add(before);
		}
		return out;
	}

	/** The first and last capture times without decoding anything, or null when there are no whole frames. */
	static long[] span(InputStream in) throws IOException
	{
		DataInputStream data = new DataInputStream(in);
		if (data.readInt() != MAGIC)
		{
			throw new IOException("Not a Gielinor Wrapped clip");
		}
		long first = -1;
		long last = -1;
		while (true)
		{
			try
			{
				long time = data.readLong();
				int length = data.readInt();
				if (length <= 0 || length > MAX_FRAME)
				{
					break;
				}
				skipFully(data, length);
				if (first < 0)
				{
					first = time;
				}
				last = time;
			}
			catch (EOFException e)
			{
				break;
			}
		}
		return first < 0 ? null : new long[]{first, last};
	}

	private static void skipFully(DataInputStream in, int n) throws IOException
	{
		while (n > 0)
		{
			int skipped = in.skipBytes(n);
			if (skipped <= 0)
			{
				// skipBytes gives up at the end of the stream; read() tells EOF apart from a slow source
				if (in.read() < 0)
				{
					throw new EOFException();
				}
				skipped = 1;
			}
			n -= skipped;
		}
	}

	/** JPEG without chroma subsampling, so coloured game text stays readable. */
	static byte[] encode(BufferedImage image, float quality) throws IOException
	{
		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpeg").next();
		ByteArrayOutputStream bytes = new ByteArrayOutputStream(128 * 1024);
		// In memory: ImageIO would otherwise buffer every frame through a temporary file.
		try (ImageOutputStream out = new MemoryCacheImageOutputStream(bytes))
		{
			writer.setOutput(out);
			ImageWriteParam param = writer.getDefaultWriteParam();
			param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			param.setCompressionQuality(quality);

			IIOMetadata meta = writer.getDefaultImageMetadata(new ImageTypeSpecifier(image), param);
			IIOMetadataNode root = (IIOMetadataNode) meta.getAsTree(JPEG_FORMAT);
			NodeList components = root.getElementsByTagName("componentSpec");
			for (int i = 0; i < components.getLength(); i++)
			{
				IIOMetadataNode c = (IIOMetadataNode) components.item(i);
				c.setAttribute("HsamplingFactor", "1");
				c.setAttribute("VsamplingFactor", "1");
			}
			meta.setFromTree(JPEG_FORMAT, root);
			writer.write(null, new IIOImage(image, null, meta), param);
		}
		finally
		{
			writer.dispose();
		}
		return bytes.toByteArray();
	}

	static BufferedImage decode(byte[] jpeg) throws IOException
	{
		BufferedImage image = ImageIO.read(new ByteArrayInputStream(jpeg));
		if (image == null)
		{
			throw new IOException("Unreadable clip frame");
		}
		return image;
	}
}

package com.gielinorwrapped;

import java.io.BufferedInputStream;
import java.io.IOException;
