	/** A year (or any long recap) in review: each month's best clip, a few seconds each, with the month's name. */
	static final class Montage extends Scenes.Scene
	{
		static final int MIN_MONTHS = 3;
		static final double MIN_SEGMENT = 1.2;
		final List<Recap.Month> months;
		private final Function<String, List<ClipFile.Frame>> loader;
		private int loadedIndex = -1;
		private List<ClipFile.Frame> frames;
		private int decodedIndex = -1;
		private BufferedImage decoded;

		Montage(Scenes.Look look, double duration, List<Recap.Month> months, Function<String, List<ClipFile.Frame>> loader)
		{
			super("montage", look, duration);
			this.months = months;
			this.loader = loader;
		}

		@Override
		double minDuration()
		{
			return Math.min(duration, months.size() * MIN_SEGMENT);
		}

		@Override
		void open()
		{
			loadedIndex = -1;
		}

		@Override
		void close()
		{
			frames = null;
			decoded = null;
			loadedIndex = -1;
		}

		private double segment()
		{
			return duration / Math.max(1, months.size());
		}

		private BufferedImage frame(int index, double local)
		{
			if (index != loadedIndex)
			{
				loadedIndex = index;
				decodedIndex = -1;
				decoded = null;
				Moment m = months.get(index).best;
				frames = m == null || m.clip == null ? null : loader.apply(m.clip);
			}
			if (frames == null || frames.isEmpty())
			{
				return null;
			}
			long first = frames.get(0).time;
			long length = frames.get(frames.size() - 1).time - first;
			long seg = Math.round(segment() * 1000);
			// Play the part of the clip just before its end, where the moment usually is.
			long start = Math.max(0, (length - seg) * 2 / 3);
			long target = first + start + Math.round(local * 1000);
			int lo = 0;
			int hi = frames.size() - 1;
			while (lo < hi)
			{
				int mid = (lo + hi + 1) >>> 1;
				if (frames.get(mid).time <= target)
				{
					lo = mid;
				}
				else
				{
					hi = mid - 1;
				}
			}
			if (lo != decodedIndex)
			{
				try
				{
					BufferedImage next = frames.get(lo).image();
					if (next != null)
					{
						decoded = next;
					}
				}
				catch (IOException e)
				{
					// keep the previous frame
				}
				decodedIndex = lo;
			}
			return decoded;
		}

		@Override
		void render(Graphics2D g, int w, int h, double t)
		{
			Theme th = look.theme;
			int u = Math.min(w, h);
			double seg = segment();
			int index = Math.max(0, Math.min(months.size() - 1, (int) (t / seg)));
			double local = t - index * seg;
			Recap.Month m = months.get(index);
			BufferedImage img = frame(index, local);
			if (img != null)
			{
				Scenes.drawCover(g, img, 0, 0, w, h, 1.02 + 0.04 * local / seg);
				g.setColor(Theme.alpha(Color.BLACK, 0.25));
				g.fillRect(0, (int) (h * 0.62), w, h - (int) (h * 0.62));
			}
			else
			{
				background(g, w, h, t);
				List<String> lines = new ArrayList<>();
				if (m.xp > 0)
				{
					lines.add(Recap.number(m.xp) + " XP");
				}
				if (m.loot > 0)
				{
					lines.add(Recap.gp(m.loot) + " loot");
				}
				if (m.seconds > 0)
				{
					lines.add(Recap.duration(m.seconds) + " played");
				}
				for (int i = 0; i < lines.size(); i++)
				{
					double a = Captions.clamp((local - 0.15 - i * 0.12) / 0.3);
					Captions.centered(g, lines.get(i), w / 2, (int) (h * 0.42 + i * u * 0.08), th.bold(u * (i == 0 ? 0.075f : 0.05f)), i == 0 ? Theme.alpha(th.accent, a) : ink(th, a), (int) (w * 0.9));
				}
			}

			// Month name slams in at the start of each segment.
			double p = Splash.backOut(Captions.clamp(local / 0.3));
			Font big = th.bold((float) (u * 0.13 * Math.max(0.01, p)));
			Sprites.outlined(g, m.name().toUpperCase(Locale.ROOT), w / 2.0, h * 0.24, big, th.accent, -0.04, (int) (w * 0.9));
			if (img != null && m.best != null && m.best.title != null)
			{
				Captions.centered(g, m.best.title, w / 2, (int) (h * 0.8), th.bold(u * 0.045f), Theme.alpha(Color.WHITE, Captions.clamp((local - 0.2) / 0.3)), (int) (w * 0.9));
			}

			// Twelve ticks along the bottom, the current month lit.
			int n = months.size();
			int tick = (int) (u * 0.022);
			int gap = tick;
			int rowW = n * tick + (n - 1) * gap;
			int x = (w - rowW) / 2;
			int y = (int) (h * 0.9);
			for (int i = 0; i < n; i++)
			{
				g.setColor(i == index ? th.accent : i < index ? Theme.alpha(th.accent, 0.5) : Theme.alpha(Color.WHITE, 0.3));
				g.fillOval(x + i * (tick + gap), y, tick, tick);
			}
		}
	}
}

package com.gielinorwrapped;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;
import java.time.temporal.TemporalAdjusters;
import java.util.Locale;

/** A span of whole days a recap covers. */
final class Period
{
	enum Kind
	{
		DAY("Daily", "day"),
		WEEK("Weekly", "week"),
		MONTH("Monthly", "month"),
		YEAR("Yearly", "year"),
		CUSTOM("", "time");

		final String label;
		final String noun;

		Kind(String label, String noun)
		{
			this.label = label;
			this.noun = noun;
		}
	}

	private static final DateTimeFormatter DAY_FORMAT = DateTimeFormatter.ofPattern("d MMM yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter SHORT_FORMAT = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter MONTH_FORMAT = DateTimeFormatter.ofPattern("MMMM yyyy", Locale.ENGLISH);

	final Kind kind;
	final LocalDate from;
	final LocalDate to;

	Period(Kind kind, LocalDate from, LocalDate to)
	{
		if (to.isBefore(from))
		{
			throw new IllegalArgumentException("Period ends before it starts");
		}
		this.kind = kind;
		this.from = from;
		this.to = to;
	}

	/** The period of this kind containing {@code day}. */
	static Period containing(Kind kind, LocalDate day, DayOfWeek weekStart)
	{
		switch (kind)
		{
			case WEEK:
			{
				LocalDate start = day.with(TemporalAdjusters.previousOrSame(weekStart));
				return new Period(kind, start, start.plusDays(6));
			}
			case MONTH:
				return new Period(kind, day.withDayOfMonth(1), day.with(TemporalAdjusters.lastDayOfMonth()));
			case YEAR:
				return new Period(kind, day.withDayOfYear(1), day.with(TemporalAdjusters.lastDayOfYear()));
			default:
				return new Period(Kind.DAY, day, day);
		}
	}

	/** The last complete period of this kind before {@code today}. */
	static Period previous(Kind kind, LocalDate today, DayOfWeek weekStart)
	{
		Period current = containing(kind, today, weekStart);
		return containing(kind, current.from.minusDays(1), weekStart);
	}

	/** The period of the same length just before this one, for comparisons. */
	Period before()
	{
		if (kind == Kind.CUSTOM)
		{
			long len = days();
			return new Period(kind, from.minusDays(len), from.minusDays(1));
		}
		return containing(kind, from.minusDays(1), DayOfWeek.from(from));
	}

	long days()
	{
		return ChronoUnit.DAYS.between(from, to) + 1;
	}

	/** "Weekly", or "" for custom ranges. */
	String label()
	{
		return kind.label;
	}

	String noun()
	{
		return kind.noun;
	}

	/** "26 Oct 2026", "19 Oct – 25 Oct 2026", "October 2026", "2026". */
	String describe()
	{
		switch (kind)
		{
			case DAY:
				return from.format(DAY_FORMAT);
			case MONTH:
				return from.format(MONTH_FORMAT);
			case YEAR:
				return Integer.toString(from.getYear());
			default:
				if (from.equals(to))
				{
					return from.format(DAY_FORMAT);
				}
				return (from.getYear() == to.getYear() ? from.format(SHORT_FORMAT) : from.format(DAY_FORMAT)) + " – " + to.format(DAY_FORMAT);
		}
	}

	/** A file-name-safe id such as {@code week-2026-10-19}. */
	String id()
	{
		return kind.name().toLowerCase(Locale.ROOT) + "-" + from + (kind == Kind.CUSTOM ? "-" + to : "");
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Period))
		{
			return false;
		}
		Period p = (Period) o;
		return kind == p.kind && from.equals(p.from) && to.equals(p.to);
	}

	@Override
	public int hashCode()
	{
		return (kind.hashCode() * 31 + from.hashCode()) * 31 + to.hashCode();
	}

	@Override
	public String toString()
	{
		return id();
	}
}

package com.gielinorwrapped;

import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeFormatter;
import java.time.format.TextStyle;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import net.runelite.api.Experience;

/** A period's stats summed up, ranked and turned into caption tokens. Built off the client thread. */
final class Recap
{
	static final class Entry
	{
		final String name;
		final long value;

		Entry(String name, long value)
		{
			this.name = name;
			this.value = value;
		}
	}

	static final class Persona
	{
		final String title;
		final String blurb;

		Persona(String title, String blurb)
		{
			this.title = title;
			this.blurb = blurb;
		}
	}

	/** One "this time vs last time" line. */
	static final class Comparison
	{
		enum Unit
		{
			NUMBER, GP, TIME, DAYS
		}

		final String label;
		final long now;
		final long before;
		final Unit unit;

		Comparison(String label, long now, long before, Unit unit)
		{
			this.label = label;
			this.now = now;
			this.before = before;
			this.unit = unit;
		}

		String show(long v)
		{
			switch (unit)
			{
				case GP:
					return gp(v);
				case TIME:
					return duration(v);
				case DAYS:
					return v == 1 ? "1 day" : v + " days";
				default:
					return number(v);
			}
		}

		/** "+23%", "-8%", "new" or "same". */
		String change()
		{
			if (before == 0)
			{
				return now == 0 ? "same" : "new";
			}
			long pct = Math.round((now - before) * 100.0 / Math.abs(before));
			return pct == 0 ? "same" : (pct > 0 ? "+" : "") + pct + "%";
		}

		boolean up()
		{
			return now >= before;
		}
	}

	/** How long until a skill goal at this period's rate. */
	static final class Pace
	{
		final String skill;
		/** "99 Mining" or "200M Mining XP". */
		final String goal;
		final long days;
		final long xpLeft;
		final long xpPerDay;

		Pace(String skill, String goal, long days, long xpLeft, long xpPerDay)
		{
			this.skill = skill;
			this.goal = goal;
			this.days = days;
			this.xpLeft = xpLeft;
			this.xpPerDay = xpPerDay;
		}

		String when()
		{
			if (days <= 1)
			{
				return "tomorrow";
			}
			return days < 60 ? "in " + days + " days" : days < 730 ? "in " + Math.round(days / 30.4) + " months" : "in " + Math.round(days / 365.0) + " years";
		}

		/** "99 Mining in 41 days". */
		String line()
		{
			return goal + " " + when();
		}
	}

	/** One month of a long recap: its best moment and totals. */
	static final class Month
	{
		final YearMonth month;
		/** The most important moment, preferring ones with a clip; may be null. */
		final Moment best;
		final long xp;
		final long loot;
		final long seconds;

		Month(YearMonth month, Moment best, long xp, long loot, long seconds)
		{
			this.month = month;
			this.best = best;
			this.xp = xp;
			this.loot = loot;
			this.seconds = seconds;
		}

		String name()
		{
			return month.getMonth().getDisplayName(TextStyle.SHORT, Locale.ENGLISH);
		}
	}

	/** One bar on the graphs: a day, a week or a month. */
	static final class Bucket
	{
		final LocalDate start;
		final long xp;
		final long seconds;
		final long loot;

		Bucket(LocalDate start, long xp, long seconds, long loot)
		{
			this.start = start;
			this.xp = xp;
			this.seconds = seconds;
			this.loot = loot;
		}
	}

	/** How long one bar on the graphs spans. */
	enum Step
	{
		DAY, WEEK, MONTH
	}

	static final int MAX_PACES = 3;
	static final int MAX_MONTHS = 12;
	/** Recaps up to this many days get a bar per day, up to {@link #WEEKLY_DAYS} a bar per week, longer a bar per month. */
	static final int DAILY_DAYS = 31;
	static final int WEEKLY_DAYS = 183;
	/** Paces further off than this aren't worth showing. */
	static final long PACE_HORIZON_DAYS = 365;
	static final long MAX_XP = 200_000_000L;

	private static final DateTimeFormatter DAY_NAME = DateTimeFormatter.ofPattern("EEEE d MMM", Locale.ENGLISH);
	private static final Set<String> GATHERING = new HashSet<>(Arrays.asList("Mining", "Fishing", "Woodcutting", "Hunter", "Farming"));
	private static final Set<String> ARTISAN = new HashSet<>(Arrays.asList("Smithing", "Crafting", "Fletching", "Herblore", "Cooking", "Firemaking", "Construction", "Runecraft"));
	private static final Set<String> COMBAT = new HashSet<>(Arrays.asList("Attack", "Strength", "Defence", "Ranged", "Magic", "Hitpoints", "Prayer", "Slayer"));
	private static final Set<String> ROGUE = new HashSet<>(Arrays.asList("Agility", "Thieving"));

	final Period period;
	final String player;
	final DayRecord total;
	final int daysPlayed;
	final List<Entry> skills;
	final List<Entry> levels;
	final List<Entry> lootSources;
	final List<Entry> kills;
	final List<Entry> areas;
	final List<DayRecord.Drop> drops;
	/** Highlight moments, most important first. */
	final List<Moment> highlights;
	final int longestStreak;
	final LocalDate busiestDay;
	final long busiestDaySeconds;
	final LocalDate bestXpDay;
	final long bestXpDayXp;
	final int peakHour;
	final int totalClues;
	final int totalKills;
	/** Percent change in XP against the period before, or null when there's nothing to compare. */
	final Integer xpChange;
	final Persona persona;
	/** The period before, summed; empty when nothing was tracked then. */
	final DayRecord previousTotal;
	final int previousDaysPlayed;
	final int previousStreak;
	final List<Comparison> comparisons;
	final List<Pace> paces;
	final List<Entry> bosses;
	/** Fastest kill per boss in seconds, quickest first. */
	final List<Entry> fastest;
	final List<Entry> regions;
	/** Collection log slots and pets, oldest first. */
	final List<Moment> collection;
	final int combatTasks;
	final int diaryTasks;
	final List<DayRecord.Trade> trades;
	/** Months with anything in them, for recaps longer than two months; otherwise empty. */
	final List<Month> months;
	/** The account type on the latest day it was seen. */
	final AccountType accountType;
	final Step step;
	/** XP, time and loot per {@link #step} from the start of the period to the last tracked day; empty for one-day recaps. */
	final List<Bucket> series;

	private Recap(Period period, String player, List<DayRecord> days, List<DayRecord> previous)
	{
		this.period = period;
		this.player = player == null ? "Adventurer" : player;
		accountType = accountType(days);
		total = new DayRecord(period.from.toString());
		int played = 0;
		LocalDate busiest = null;
		long busiestSecs = 0;
		LocalDate bestXp = null;
		long bestXpValue = 0;
		Set<LocalDate> playedDays = new HashSet<>();
		for (DayRecord d : days)
		{
			total.merge(d);
			LocalDate date = LocalDate.parse(d.date);
			if (d.playSeconds > 0 || d.totalXp() > 0)
			{
				played++;
				playedDays.add(date);
			}
			if (d.playSeconds > busiestSecs)
			{
				busiestSecs = d.playSeconds;
				busiest = date;
			}
			long xp = d.totalXp();
			if (xp > bestXpValue)
			{
				bestXpValue = xp;
				bestXp = date;
			}
		}
		daysPlayed = played;
		busiestDay = busiest;
		busiestDaySeconds = busiestSecs;
		bestXpDay = bestXp;
		bestXpDayXp = bestXpValue;
		longestStreak = streak(playedDays, period);

		skills = rank(total.xp);
		levels = rank(total.levels);
		lootSources = rank(total.lootBySource);
		kills = rank(total.kills);
		areas = rank(total.areas);
		drops = new ArrayList<>(total.drops);
		highlights = new ArrayList<>(total.moments);
		highlights.sort((a, b) -> a.importance != b.importance ? Integer.compare(b.importance, a.importance) : Long.compare(a.time, b.time));

		int peak = 0;
		for (int h = 1; h < 24; h++)
		{
			if (total.hours[h] > total.hours[peak])
			{
				peak = h;
			}
		}
		peakHour = peak;
		int clues = 0;
		for (int c : total.clues.values())
		{
			clues += c;
		}
		totalClues = clues;
		int k = 0;
		for (int c : total.kills.values())
		{
			k += c;
		}
		totalKills = k;

		long prevXp = 0;
		for (DayRecord d : previous)
		{
			prevXp += d.totalXp();
		}
		xpChange = prevXp > 0 ? (int) Math.round((total.totalXp() - prevXp) * 100.0 / prevXp) : null;
		persona = persona();

		previousTotal = new DayRecord(period.before().from.toString());
		Set<LocalDate> prevPlayed = new HashSet<>();
		for (DayRecord d : previous)
		{
			previousTotal.merge(d);
			if (d.playSeconds > 0 || d.totalXp() > 0)
			{
				prevPlayed.add(LocalDate.parse(d.date));
			}
		}
		previousDaysPlayed = prevPlayed.size();
		previousStreak = streak(prevPlayed, period.before());
		comparisons = compare();

		bosses = rank(total.bossKills);
		fastest = rank(total.fastest);
		Collections.reverse(fastest);
		regions = rank(total.regions);
		List<Moment> slots = new ArrayList<>();
		int tasks = 0;
		int diaries = 0;
		for (Moment m : total.moments)
		{
			if (m.type == Moment.Type.COLLECTION_LOG || m.type == Moment.Type.PET)
			{
				slots.add(m);
			}
			else if (m.type == Moment.Type.COMBAT_TASK)
			{
				tasks++;
			}
			else if (m.type == Moment.Type.DIARY)
			{
				diaries++;
			}
		}
		slots.sort((a, b) -> Long.compare(a.time, b.time));
		collection = slots;
		combatTasks = tasks;
		diaryTasks = diaries;
		trades = new ArrayList<>(total.trades);
		paces = paces(days);
		months = months(days);
		step = period.days() <= DAILY_DAYS ? Step.DAY : period.days() <= WEEKLY_DAYS ? Step.WEEK : Step.MONTH;
		series = series(days, period, step);
	}

	/** The first day of the bar {@code date} falls in. */
	static LocalDate bucketStart(LocalDate date, LocalDate from, Step step)
	{
		switch (step)
		{
			case WEEK:
				return from.plusWeeks(ChronoUnit.WEEKS.between(from, date));
			case MONTH:
				LocalDate first = date.withDayOfMonth(1);
				return first.isBefore(from) ? from : first;
			default:
				return date;
		}
	}

	static List<Bucket> series(List<DayRecord> days, Period period, Step step)
	{
		List<Bucket> out = new ArrayList<>();
		if (period.days() <= 1)
		{
			return out;
		}
		LocalDate last = null;
		Map<LocalDate, DayRecord> sums = new TreeMap<>();
		for (DayRecord d : days)
		{
			LocalDate date = LocalDate.parse(d.date);
			if (date.isBefore(period.from) || date.isAfter(period.to))
			{
				continue;
			}
			last = last == null || date.isAfter(last) ? date : last;
			sums.computeIfAbsent(bucketStart(date, period.from, step), k -> new DayRecord(k.toString())).merge(d);
		}
		if (last == null)
		{
			return out;
		}
		// Every bar from the start to the last tracked day, quiet ones included, so gaps show.
		for (LocalDate b = period.from; !b.isAfter(last); )
		{
			DayRecord d = sums.get(b);
			out.add(d == null ? new Bucket(b, 0, 0, 0) : new Bucket(b, d.totalXp(), d.playSeconds, d.lootValue));
			b = step == Step.DAY ? b.plusDays(1) : step == Step.WEEK ? b.plusWeeks(1) : b.withDayOfMonth(1).plusMonths(1);
		}
		return out;
	}

	private List<Comparison> compare()
	{
		List<Comparison> out = new ArrayList<>();
		if (previousDaysPlayed == 0 && previousTotal.totalXp() == 0 && previousTotal.lootValue == 0)
		{
			return out;
		}
		add(out, "XP gained", total.totalXp(), previousTotal.totalXp(), Comparison.Unit.NUMBER);
		add(out, "Time played", total.playSeconds, previousTotal.playSeconds, Comparison.Unit.TIME);
		add(out, "Loot", total.lootValue, previousTotal.lootValue, Comparison.Unit.GP);
		add(out, "Levels", total.totalLevels(), previousTotal.totalLevels(), Comparison.Unit.NUMBER);
		long prevKills = 0;
		for (int c : previousTotal.kills.values())
		{
			prevKills += c;
		}
		add(out, "Kills", totalKills, prevKills, Comparison.Unit.NUMBER);
		add(out, "Days played", daysPlayed, previousDaysPlayed, Comparison.Unit.DAYS);
		add(out, "Longest streak", longestStreak, previousStreak, Comparison.Unit.DAYS);
		add(out, "Deaths", total.deaths, previousTotal.deaths, Comparison.Unit.NUMBER);
		return out;
	}

	private static void add(List<Comparison> out, String label, long now, long before, Comparison.Unit unit)
	{
		if (now > 0 || before > 0)
		{
			out.add(new Comparison(label, now, before, unit));
		}
	}

	/** Goals for the most-trained skills, at the rate this period was played. */
	private List<Pace> paces(List<DayRecord> days)
	{
		List<Pace> out = new ArrayList<>();
		LocalDate last = null;
		for (DayRecord d : days)
		{
			LocalDate date = LocalDate.parse(d.date);
			if ((d.playSeconds > 0 || d.totalXp() > 0) && (last == null || date.isAfter(last)))
			{
				last = date;
			}
		}
		if (last == null)
		{
			return out;
		}
		long span = Math.max(1, ChronoUnit.DAYS.between(period.from, last) + 1);
		for (Entry e : skills)
		{
			Long now = total.skillXp.get(e.name);
			if (now == null || now <= 0)
			{
				continue;
			}
			Pace p = pace(e.name, now, Math.max(1, e.value / span));
			if (p != null)
			{
				out.add(p);
				if (out.size() >= MAX_PACES)
				{
					break;
				}
			}
		}
		return out;
	}

	/** The biggest goal within a year at {@code perDay}, or null if even the next level is further off. */
	static Pace pace(String skill, long xp, long perDay)
	{
		if (xp >= MAX_XP || perDay <= 0)
		{
			return null;
		}
		int level = Experience.getLevelForXp((int) Math.min(Integer.MAX_VALUE, xp));
		if (level >= Experience.MAX_REAL_LEVEL)
		{
			long left = MAX_XP - xp;
			long days = (left + perDay - 1) / perDay;
			return days <= PACE_HORIZON_DAYS ? new Pace(skill, "200M " + skill + " XP", days, left, perDay) : null;
		}
		int[] targets = {Experience.MAX_REAL_LEVEL, Math.min(Experience.MAX_REAL_LEVEL, (level / 10 + 1) * 10), level + 1};
		for (int target : targets)
		{
			long left = Experience.getXpForLevel(target) - xp;
			long days = (left + perDay - 1) / perDay;
			if (left > 0 && days <= PACE_HORIZON_DAYS)
			{
				return new Pace(skill, target + " " + skill, days, left, perDay);
			}
		}
		return null;
	}

	private List<Month> months(List<DayRecord> days)
	{
		List<Month> out = new ArrayList<>();
		if (period.days() <= 62)
		{
			return out;
		}
		Map<YearMonth, DayRecord> byMonth = new TreeMap<>();
		for (DayRecord d : days)
		{
			YearMonth ym = YearMonth.from(LocalDate.parse(d.date));
			byMonth.computeIfAbsent(ym, k -> new DayRecord(k.atDay(1).toString())).merge(d);
		}
		for (Map.Entry<YearMonth, DayRecord> e : byMonth.entrySet())
		{
			DayRecord m = e.getValue();
			if (m.playSeconds == 0 && m.totalXp() == 0 && m.moments.isEmpty())
			{
				continue;
			}
			Moment best = null;
			for (Moment mo : m.moments)
			{
				if (mo.type == Moment.Type.DEATH)
				{
					continue;
				}
				boolean better;
				if (best == null)
				{
					better = true;
				}
				else if ((mo.clip != null) != (best.clip != null))
				{
					better = mo.clip != null;
				}
				else
				{
					better = mo.importance > best.importance;
				}
				if (better)
				{
					best = mo;
				}
			}
			out.add(new Month(e.getKey(), best, m.totalXp(), m.lootValue, m.playSeconds));
		}
		while (out.size() > MAX_MONTHS)
		{
			out.remove(0);
		}
		return out;
	}

	boolean hasGe()
	{
		return total.geBought > 0 || total.geSold > 0;
	}

	int totalBossKills()
	{
		int t = 0;
		for (Entry e : bosses)
		{
			t += (int) e.value;
		}
		return t;
	}

	/**
	 * @param days stored records within the period, with today's live record in place of its stored copy
	 * @param previous records of the period before, for comparisons; may be empty
	 */
	static Recap build(Period period, String player, List<DayRecord> days, List<DayRecord> previous)
	{
		return new Recap(period, player, days, previous);
	}

	static <N extends Number> List<Entry> rank(Map<String, N> map)
	{
		List<Entry> out = new ArrayList<>();
		map.forEach((k, v) ->
		{
			if (k != null && v.longValue() > 0)
			{
				out.add(new Entry(k, v.longValue()));
			}
		});
		out.sort((a, b) -> Long.compare(b.value, a.value));
		return out;
	}

	static int streak(Set<LocalDate> played, Period period)
	{
		int best = 0;
		int run = 0;
		for (LocalDate d = period.from; !d.isAfter(period.to); d = d.plusDays(1))
		{
			run = played.contains(d) ? run + 1 : 0;
			best = Math.max(best, run);
		}
		return best;
	}

	boolean isEmpty()
	{
		return daysPlayed == 0 && total.lootValue == 0 && total.moments.isEmpty();
	}

	/** Picks the archetype the period's play fits best. */
	private Persona persona()
	{
		long xp = Math.max(1, total.totalXp());
		Map<String, Double> scores = new LinkedHashMap<>();
		scores.put("gather", share(GATHERING) / (double) xp);
		scores.put("artisan", share(ARTISAN) / (double) xp);
		scores.put("combat", share(COMBAT) / (double) xp);
		scores.put("rogue", share(ROGUE) / (double) xp);
		scores.put("boss", Math.min(1.0, totalKills / 300.0) + (total.killCounts.isEmpty() ? 0 : 0.2));
		scores.put("clues", Math.min(1.2, totalClues / 15.0));
		scores.put("death", Math.min(1.0, total.deaths / 15.0));
		boolean pet = total.moments.stream().anyMatch(m -> m.type == Moment.Type.PET);
		long quests = total.moments.stream().filter(m -> m.type == Moment.Type.QUEST).count();
		scores.put("quest", Math.min(1.1, quests / 4.0));
		long night = 0;
		for (int h = 0; h < 5; h++)
		{
			night += total.hours[h];
		}
		boolean owl = total.playSeconds > 3600 && night * 100 / total.playSeconds >= 40;

		if (pet)
		{
			return new Persona("The Lucky One", "A pet came home with you. RNG smiled, and everyone else is jealous.");
		}
		String best = null;
		double score = 0.35;
		for (Map.Entry<String, Double> e : scores.entrySet())
		{
			if (e.getValue() > score)
			{
				score = e.getValue();
				best = e.getKey();
			}
		}
		Persona p;
		if (best == null)
		{
			p = new Persona("The Explorer", "A bit of everything, everywhere. Gielinor is your playground.");
		}
		else
		{
			switch (best)
			{
				case "gather":
					p = new Persona("The Gatherer", "Rocks, logs and fish fear you. The bank is overflowing.");
					break;
				case "artisan":
					p = new Persona("The Artisan", "If it can be crafted, cooked or smithed, you made a thousand of them.");
					break;
				case "combat":
					p = new Persona("The Warrior", "Every problem looks like a monster, and you have the answer.");
					break;
				case "rogue":
					p = new Persona("The Rogue", "Rooftops and pockets. Light on your feet and light-fingered.");
					break;
				case "boss":
					p = new Persona("The Boss Hunter", "Bosses had a rough " + period.noun() + ". You kept coming back.");
					break;
				case "clues":
					p = new Persona("The Treasure Hunter", "Caskets, emotes and riddles. X marks your spot.");
					break;
				case "death":
					p = new Persona("The Daredevil", "Death knows you by name. You keep the gravestone business alive.");
					break;
				default:
					p = new Persona("The Adventurer", "Quest log ticking green, one story at a time.");
					break;
			}
		}
		if (owl)
		{
			p = new Persona(p.title + " (Night Owl)", p.blurb + " Mostly after midnight.");
		}
		return p;
	}

	private long share(Set<String> skillNames)
	{
		long t = 0;
		for (Map.Entry<String, Long> e : total.xp.entrySet())
		{
			if (skillNames.contains(e.getKey()))
			{
				t += e.getValue();
			}
		}
		return t;
	}

	private static AccountType accountType(List<DayRecord> days)
	{
		String latest = null;
		int value = 0;
		for (DayRecord d : days)
		{
			if (d.accountType >= 0 && (latest == null || d.date.compareTo(latest) >= 0))
			{
				latest = d.date;
				value = d.accountType;
			}
		}
		return AccountType.of(value);
	}

	/** Values for the caption tokens, e.g. {@code {xp}}. */
	Map<String, String> tokens(boolean hideName)
	{
		Map<String, String> t = new HashMap<>();
		String name = hideName ? "Adventurer" : player;
		t.put("player", name);
		t.put("accountType", accountType.title);
		t.put("period", period.label().isEmpty() ? period.describe() : period.label());
		t.put("periodNoun", period.noun());
		t.put("dates", period.describe());
		t.put("range", period.describe());
		t.put("xp", number(total.totalXp()));
		t.put("topSkill", skills.isEmpty() ? "nothing yet" : skills.get(0).name);
		t.put("topSkillXp", skills.isEmpty() ? "0" : number(skills.get(0).value) + " XP");
		t.put("levels", Long.toString(total.totalLevels()));
		t.put("loot", gp(total.lootValue));
		t.put("topDrop", drops.isEmpty() ? "none yet" : drops.get(0).name);
		t.put("topDropValue", drops.isEmpty() ? "0 gp" : gp(drops.get(0).value));
		t.put("topSource", lootSources.isEmpty() ? "nobody" : lootSources.get(0).name);
		t.put("kills", number(totalKills));
		t.put("topKill", kills.isEmpty() ? "nobody" : kills.get(0).name);
		t.put("topKillCount", kills.isEmpty() ? "0" : number(kills.get(0).value));
		t.put("hours", duration(total.playSeconds));
		t.put("active", duration(total.activeSeconds));
		t.put("days", daysPlayed == 1 ? "1 day" : daysPlayed + " days");
		t.put("topArea", areas.isEmpty() ? "everywhere" : areas.get(0).name);
		t.put("deaths", Integer.toString(total.deaths));
		t.put("clues", Integer.toString(totalClues));
		t.put("streak", longestStreak == 1 ? "1 day" : longestStreak + " days");
		t.put("peakHour", hour(peakHour));
		t.put("busiestDay", busiestDay == null ? "-" : busiestDay.format(DAY_NAME));
		t.put("xpChange", xpChange == null ? "" : (xpChange >= 0 ? "+" : "") + xpChange + "%");
		t.put("persona", persona.title);
		t.put("personaBlurb", persona.blurb);
		t.put("highlights", Integer.toString(highlights.size()));
		t.put("bossKills", number(totalBossKills()));
		t.put("topBoss", bosses.isEmpty() ? "nobody" : bosses.get(0).name);
		t.put("slayerTasks", Integer.toString(total.slayerTasks));
		t.put("geBought", gp(total.geBought));
		t.put("geSold", gp(total.geSold));
		t.put("geNet", (total.geNet() > 0 ? "+" : "") + gp(total.geNet()));
		t.put("topTrade", trades.isEmpty() ? "none yet" : trades.get(0).name);
		t.put("collectionSlots", Integer.toString(collection.size()));
		t.put("combatTasks", Integer.toString(combatTasks));
		t.put("diaryTasks", Integer.toString(diaryTasks));
		t.put("pace", paces.isEmpty() ? "" : paces.get(0).line());
		t.put("lastXp", number(previousTotal.totalXp()));
		t.put("lastLoot", gp(previousTotal.lootValue));
		t.put("lastHours", duration(previousTotal.playSeconds));
		return t;
	}

	/** Fills {@code {token}}s; unknown tokens are left as typed. */
	static String fill(String template, Map<String, String> tokens)
	{
		if (template == null)
		{
			return "";
		}
		StringBuilder out = new StringBuilder();
		int i = 0;
		while (i < template.length())
		{
			int open = template.indexOf('{', i);
			int close = open < 0 ? -1 : template.indexOf('}', open);
			if (open < 0 || close < 0)
			{
				out.append(template, i, template.length());
				break;
			}
			out.append(template, i, open);
			String value = tokens.get(template.substring(open + 1, close));
			out.append(value != null ? value : template.substring(open, close + 1));
			i = close + 1;
		}
		return out.toString();
	}

	/** 1234 → "1,234", 1234567 → "1.23M". */
	static String number(long n)
	{
		long a = Math.abs(n);
		if (a >= 1_000_000_000L)
		{
			return trim(n / 1e9) + "B";
		}
		if (a >= 10_000_000L)
		{
			return trim(n / 1e6) + "M";
		}
		if (a >= 1_000_000L)
		{
			return String.format(Locale.ENGLISH, "%.2fM", n / 1e6);
		}
		return String.format(Locale.ENGLISH, "%,d", n);
	}

	private static String trim(double v)
	{
		return v >= 100 ? String.format(Locale.ENGLISH, "%.0f", Math.floor(v)) : String.format(Locale.ENGLISH, "%.1f", Math.floor(v * 10) / 10);
	}

	static String gp(long n)
	{
		long a = Math.abs(n);
		if (a < 100_000)
		{
			return String.format(Locale.ENGLISH, "%,d gp", n);
		}
		String sign = n < 0 ? "-" : "";
		if (a < 1_000_000)
		{
			return sign + a / 1000 + "K gp";
		}
		if (a < 1_000_000_000L)
		{
			return sign + trim(a / 1e6) + "M gp";
		}
		return sign + trim(a / 1e9) + "B gp";
	}

	static String duration(long seconds)
	{
		long h = seconds / 3600;
		long m = seconds % 3600 / 60;
		if (h == 0)
		{
			return m + "m";
		}
		return m == 0 ? h + "h" : h + "h " + m + "m";
	}

	static String hour(int h)
	{
		int twelve = h % 12 == 0 ? 12 : h % 12;
		return twelve + (h < 12 ? "am" : "pm");
	}

	static List<Entry> top(List<Entry> list, int n)
	{
		return list.size() <= n ? list : Collections.unmodifiableList(list.subList(0, n));
	}
}

package com.gielinorwrapped;

import com.google.gson.JsonParseException;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.InterruptedIOException;
import java.io.OutputStream;
import java.io.Reader;
import java.nio.file.StandardCopyOption;
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Builds recaps on a background thread: the share card first (quick), then the video (minutes). Finished
 * recaps live in {@code accounts/<hash>/recaps/<period id>/}. Also runs the daily/weekly/... schedule.
 */
@Slf4j
final class Recaps
{
	static final String CARD = "card.png";
	private static final String META = "recap.json";
	private static final String STATE = "schedule.json";

	enum Status
	{
		QUEUED("Waiting"),
		CARD("Drawing card"),
		VIDEO("Rendering video"),
		DONE("Ready"),
		FAILED("Failed"),
		CANCELLED("Cancelled");

		final String label;

		Status(String label)
		{
			this.label = label;
		}

		boolean finished()
		{
			return this == DONE || this == FAILED || this == CANCELLED;
		}
	}

	/** A recap being made. Fields are written by the render thread and read by the panel. */
	static final class Job
	{
		final long account;
		final Period period;
		final boolean video;
		volatile Status status = Status.QUEUED;
		volatile double progress;
		volatile String message;
		volatile boolean cancelled;
		/** The friend file to put side by side with this recap, or null. */
		final String friend;

		Job(long account, Period period, boolean video, String friend)
		{
			this.account = account;
			this.period = period;
			this.video = video;
			this.friend = friend;
		}

		void cancel()
		{
			cancelled = true;
		}
	}

	/** What is stored next to a finished recap. */
	static final class Meta
	{
		String kind;
		String from;
		String to;
		String player;
		long created;
		String video;
		/** The friend file it was made with, for rendering its video later; null for none. */
		String friend;

		Period period()
		{
			return new Period(Period.Kind.valueOf(kind), LocalDate.parse(from), LocalDate.parse(to));
		}
	}

	/** A finished recap on disk. */
	static final class Saved
	{
		final Meta meta;
		final Filepath dir;

		Saved(Meta meta, Filepath dir)
		{
			this.meta = meta;
			this.dir = dir;
		}

		Filepath card()
		{
			return dir.join(CARD);
		}

		Filepath video()
		{
			return meta.video == null ? null : dir.join(meta.video);
		}
	}

	private static final class State
	{
		Set<String> done = new HashSet<>();
	}

	private final StatsStore store;
	private final ClipLibrary library;
	private final GielinorWrappedConfig config;
	private final ExecutorService render;
	private final List<Job> jobs = new CopyOnWriteArrayList<>();
	/** Set by {@link #close()}; queued tasks then skip their work. */
	private volatile boolean closed;
	private final Consumer<Job> listener;
	private final Art art;
	private final Shots shots;
	private final DeathLog deathLog;

	/** Game sprites for cards and videos. Called on the render thread; may block briefly while a sprite loads. */
	interface Art
	{
		BufferedImage item(int id);

		BufferedImage skill(String name);

		/** The chat badge of an account type, or null. */
		default BufferedImage badge(AccountType type)
		{
			return null;
		}

		/** A music track as MIDI file bytes: a name from the music player, "Random" or "Current area"; null if unavailable. */
		default byte[] song(String track)
		{
			return null;
		}
	}

	/**
	 * @param art game sprites, or null for none
	 * @param listener told about every job change, on the render thread
	 */
	Recaps(StatsStore store, ClipLibrary library, Shots shots, DeathLog deathLog, Art art, GielinorWrappedConfig config, Consumer<Job> listener)
	{
		this.store = store;
		this.library = library;
		this.shots = shots;
		this.deathLog = deathLog;
		this.art = art;
		this.config = config;
		this.listener = listener;
		render = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "gielinor-wrapped-render");
			t.setDaemon(true);
			t.setPriority(Thread.MIN_PRIORITY);
			return t;
		});
	}

	/** Current and recent jobs, oldest first. */
	List<Job> jobs()
	{
		return new ArrayList<>(jobs);
	}

	/** Queues a recap; an identical job that is still waiting or running is reused. */
	Job request(long account, String player, Period period, boolean video)
	{
		return request(account, player, period, video, null);
	}

	/** Queues a recap with a friend's file for the "you vs them" scene; {@code friend} may be null. */
	Job request(long account, String player, Period period, boolean video, String friend)
	{
		for (Job j : jobs)
		{
			if (j.account == account && j.period.equals(period) && (j.video || !video) && !j.status.finished()
				&& java.util.Objects.equals(j.friend, friend))
			{
				return j;
			}
		}
		jobs.removeIf(j -> j.status.finished() && j.period.equals(period) && j.account == account);
		Job job = new Job(account, period, video, friend);
		jobs.add(job);
		listener.accept(job);
		render.execute(() -> run(job, player));
		return job;
	}

	/**
	 * Queues the scheduled recaps that are due: the last full day/week/month/year, once each, if anything
	 * was tracked in it. I/O thread.
	 *
	 * @param ready called with a short message when a scheduled recap finishes
	 */
	void checkSchedule(long account, String player, LocalDate today, Consumer<String> ready)
	{
		State state = readState(account);
		DayOfWeek weekStart = config.weekStart();
		List<Period> due = new ArrayList<>();
		if (config.autoDaily())
		{
			due.add(Period.previous(Period.Kind.DAY, today, weekStart));
		}
		if (config.autoWeekly())
		{
			due.add(Period.previous(Period.Kind.WEEK, today, weekStart));
		}
		if (config.autoMonthly())
		{
			due.add(Period.previous(Period.Kind.MONTH, today, weekStart));
		}
		if (config.autoYearly())
		{
			due.add(Period.previous(Period.Kind.YEAR, today, weekStart));
		}
		boolean changed = false;
		for (Period p : due)
		{
			if (state.done.contains(p.id()))
			{
				continue;
			}
			state.done.add(p.id());
			changed = true;
			if (!hasData(account, p))
			{
				continue;
			}
			Job job = request(account, player, p, config.autoVideo());
			if (config.notifyReady())
			{
				render.execute(() ->
				{
					if (!closed && job.status == Status.DONE)
					{
						ready.accept("Your " + p.label().toLowerCase() + " Gielinor Wrapped is ready: " + p.describe());
					}
				});
			}
		}
		if (changed)
		{
			writeState(account, state);
		}
	}

	private boolean hasData(long account, Period p)
	{
		for (LocalDate d : store.listDays(account))
		{
			if (!d.isBefore(p.from) && !d.isAfter(p.to))
			{
				return true;
			}
		}
		return false;
	}

	/** Finished recaps for the account, newest period first. I/O thread. */
	List<Saved> saved(long account)
	{
		Filepath dir = recapsDir(account);
		List<Saved> out = new ArrayList<>();
		if (!dir.exists())
		{
			return out;
		}
		List<Filepath> subdirs;
		try (Stream<Filepath> s = dir.walk(1))
		{
			subdirs = s.filter(f -> !f.equals(dir) && f.isDirectory()).collect(Collectors.toList());
		}
		catch (IOException e)
		{
			log.warn("Unable to list {}", dir, e);
			return out;
		}
		for (Filepath d : subdirs)
		{
			Filepath meta = d.join(META);
			if (!meta.exists() || !d.join(CARD).exists())
			{
				continue;
			}
			try (Reader r = meta.openReader())
			{
				Meta m = store.gson().fromJson(r, Meta.class);
				if (m != null && m.kind != null)
				{
					m.period();
					out.add(new Saved(m, d));
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Skipping recap {}", d, e);
			}
		}
		out.sort((a, b) -> b.meta.to.compareTo(a.meta.to) != 0 ? b.meta.to.compareTo(a.meta.to) : a.meta.kind.compareTo(b.meta.kind));
		return out;
	}

	/** I/O thread. */
	void delete(Saved saved) throws IOException
	{
		saved.dir.deleteRecursively();
	}

	private void run(Job job, String player)
	{
		if (closed)
		{
			return;
		}
		if (job.cancelled)
		{
			update(job, Status.CANCELLED, null);
			return;
		}
		Filepath dir = recapsDir(job.account).join(job.period.id());
		Filepath partial = null;
		try
		{
			update(job, Status.CARD, null);
			List<DayRecord> days = store.readRange(job.account, job.period.from, job.period.to);
			if (days.isEmpty())
			{
				update(job, Status.FAILED, "Nothing was tracked in that period yet. Try This week or Today.");
				return;
			}
			Period before = job.period.before();
			Recap recap = Recap.build(job.period, player, days, store.readRange(job.account, before.from, before.to));
			FriendFile friend = job.friend == null ? null : readFriend(job.account, job.friend);
			Composer.Media media = media(job.account, job.period, friend);

			dir.createDirectories();
			BufferedImage card = ShareCard.render(recap, config, media);
			Filepath cardTmp = dir.join(CARD + ".tmp");
			try (OutputStream out = cardTmp.openOutputStream())
			{
				ImageIO.write(card, "png", out);
			}
			cardTmp.moveTo(dir.join(CARD), StandardCopyOption.REPLACE_EXISTING);

			Meta meta = new Meta();
			meta.kind = job.period.kind.name();
			meta.from = job.period.from.toString();
			meta.to = job.period.to.toString();
			meta.player = player;
			meta.friend = job.friend;
			meta.created = System.currentTimeMillis();
			Saved old = readMeta(dir);
			meta.video = old != null && old.video() != null && old.video().exists() ? old.meta.video : null;
			writeMeta(dir, meta);
			writeUpload(dir, UploadText.text(recap, config.hideName(), null, 1));

			if (job.video)
			{
				update(job, Status.VIDEO, null);
				Composer composer = new Composer(recap, media, config);
				String name = composer.format == GielinorWrappedConfig.VideoFormat.GIF ? "recap.gif" : "recap.mp4";
				Filepath result = dir.join(name + ".part");
				Filepath scratch = dir.join("frames.part");
				partial = result;
				try
				{
					composer.render(new Composer.Output()
					{
						@Override
						public OutputStream result() throws IOException
						{
							return result.openOutputStream();
						}

						@Override
						public OutputStream scratch() throws IOException
						{
							return scratch.openOutputStream();
						}

						@Override
						public InputStream readScratch() throws IOException
						{
							return scratch.openInputStream();
						}
					}, p ->
					{
						job.progress = p;
						listener.accept(job);
					}, () -> job.cancelled);
				}
				finally
				{
					scratch.deleteIfExists();
				}
				if (meta.video != null && !meta.video.equals(name))
				{
					dir.join(meta.video).deleteIfExists();
				}
				result.moveTo(dir.join(name), StandardCopyOption.REPLACE_EXISTING);
				partial = null;
				meta.video = name;
				writeMeta(dir, meta);
				writeUpload(dir, UploadText.text(recap, config.hideName(), composer.scenes, composer.fps));
			}
			job.progress = 1;
			update(job, Status.DONE, null);
		}
		catch (InterruptedIOException e)
		{
			update(job, Status.CANCELLED, null);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to make the {} recap", job.period.id(), e);
			update(job, Status.FAILED, e.getMessage() == null ? e.getClass().getSimpleName() : e.getMessage());
		}
		finally
		{
			if (partial != null)
			{
				try
				{
					partial.deleteIfExists();
				}
				catch (IOException e)
				{
					log.debug("Unable to delete {}", partial, e);
				}
			}
		}
	}

	private void writeUpload(Filepath dir, String text) throws IOException
	{
		Filepath tmp = dir.join(UploadText.FILE + ".tmp");
		tmp.write(text);
		tmp.moveTo(dir.join(UploadText.FILE), StandardCopyOption.REPLACE_EXISTING);
	}

	/** The upload title, description and chapters saved with a recap, or null. I/O thread. */
	String upload(Saved saved)
	{
		Filepath f = saved.dir.join(UploadText.FILE);
		try
		{
			return f.exists() ? readText(f) : null;
		}
		catch (IOException e)
		{
			log.debug("Unable to read {}", f, e);
			return null;
		}
	}

	static String readText(Filepath f) throws IOException
	{
		try (InputStream in = f.openInputStream())
		{
			return new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
		}
	}

	private Filepath friendsDir(long account)
	{
		return store.accountDir(account).join("friends");
	}

	/** A friend file for the saved recap, as JSON. I/O thread. */
	String exportFriend(long account, String player, Period period)
	{
		List<DayRecord> days = store.readRange(account, period.from, period.to);
		if (days.isEmpty())
		{
			return null;
		}
		Period before = period.before();
		Recap recap = Recap.build(period, player, days, store.readRange(account, before.from, before.to));
		return FriendFile.of(recap, config.hideName()).toJson(store.gson());
	}

	/**
	 * Checks a friend file and keeps a copy for the friend dropdown. I/O thread.
	 *
	 * @return the friend, or null if the text isn't a friend file
	 */
	FriendFile importFriend(long account, String json) throws IOException
	{
		FriendFile f = FriendFile.parse(store.gson(), json);
		if (f == null)
		{
			return null;
		}
		Filepath dir = friendsDir(account);
		dir.createDirectories();
		String name = friendName(f);
		Filepath tmp = dir.join(name + ".tmp");
		tmp.write(f.toJson(store.gson()));
		tmp.moveTo(dir.join(name), StandardCopyOption.REPLACE_EXISTING);
		return f;
	}

	/** The file name an imported friend file is kept under. */
	static String friendName(FriendFile f)
	{
		return ClipLibrary.safeName(f.player) + "-" + ClipLibrary.safeName(f.from == null ? "recap" : f.from) + "." + FriendFile.EXTENSION;
	}

	/** Imported friend files by file name, newest name order. I/O thread. */
	List<String> friends(long account)
	{
		Filepath dir = friendsDir(account);
		List<String> out = new ArrayList<>();
		if (!dir.exists())
		{
			return out;
		}
		try (Stream<Filepath> s = dir.walk(1))
		{
			s.filter(f -> !f.equals(dir) && f.getFileName().endsWith("." + FriendFile.EXTENSION))
				.forEach(f -> out.add(f.getFileName()));
		}
		catch (IOException e)
		{
			log.debug("Unable to list {}", dir, e);
		}
		out.sort(null);
		return out;
	}

	/** Reads an imported friend file, or null. I/O or render thread. */
	FriendFile readFriend(long account, String name)
	{
		if (!safeFriendName(name))
		{
			return null;
		}
		Filepath f = friendsDir(account).join(name);
		try
		{
			return f.exists() && f.size() <= FriendFile.MAX_BYTES ? FriendFile.parse(store.gson(), readText(f)) : null;
		}
		catch (IOException e)
		{
			log.debug("Unable to read {}", f, e);
			return null;
		}
	}

	private static boolean safeFriendName(String name)
	{
		return name != null && !name.contains("/") && !name.contains("\\") && !name.startsWith(".") && name.endsWith("." + FriendFile.EXTENSION);
	}

	/** Removes an imported friend file. I/O thread. */
	void deleteFriend(long account, String name) throws IOException
	{
		if (safeFriendName(name))
		{
			friendsDir(account).join(name).deleteIfExists();
		}
	}

	private Composer.Media media(long account, Period period, FriendFile friend)
	{
		boolean icons = art != null && config.icons();
		Map<Integer, Optional<BufferedImage>> items = new HashMap<>();
		Map<String, Optional<BufferedImage>> skills = new HashMap<>();
		boolean badges = art != null && config.accountBadge();
		Map<AccountType, Optional<BufferedImage>> badgeImages = new HashMap<>();
		Shots.Pick pick;
		try
		{
			// Shots from the start of the period up to now, so a cover set up after the period still counts.
			long from = period.from.atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();
			pick = Shots.pick(shots.list(account), from, System.currentTimeMillis());
		}
		catch (IOException e)
		{
			log.debug("Unable to list shots", e);
			pick = new Shots.Pick();
		}
		Shots.Pick picked = pick;
		long periodStart = period.from.atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();
		long periodEnd = period.to.plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli() - 1;
		List<DeathLog.Entry> deaths = deathLog == null ? new java.util.ArrayList<>() : deathLog.range(account, periodStart, periodEnd);
		return new Composer.Media()
		{
			@Override
			public FriendFile friend()
			{
				return friend;
			}

			@Override
			public List<DeathLog.Entry> deaths()
			{
				return new java.util.ArrayList<>(deaths);
			}

			@Override
			public BufferedImage deathImage(String name)
			{
				byte[] data = deathLog == null ? null : deathLog.read(account, name);
				if (data == null)
				{
					return null;
				}
				try
				{
					return ImageIO.read(new java.io.ByteArrayInputStream(data));
				}
				catch (IOException e)
				{
					log.debug("Unable to read death picture {}", name, e);
					return null;
				}
			}

			@Override
			public List<ClipFile.Frame> deathReplay(long time)
			{
				DeathLog.Entry best = null;
				for (DeathLog.Entry e : deaths)
				{
					if (e.replay != null && e.replayTimes != null && Math.abs(e.time - time) <= DeathLog.MERGE_MS
						&& (best == null || Math.abs(e.time - time) < Math.abs(best.time - time)))
					{
						best = e;
					}
				}
				if (best == null)
				{
					return new java.util.ArrayList<>();
				}
				byte[] gif = deathLog.read(account, best.replay);
				return ReplayGif.frames(gif, best.recapTime, best.replayTimes, config.clipWidth());
			}

			@Override
			public BufferedImage item(int id)
			{
				return icons && id > 0 ? items.computeIfAbsent(id, k -> Optional.ofNullable(art.item(k))).orElse(null) : null;
			}

			@Override
			public BufferedImage skill(String name)
			{
				return icons && name != null ? skills.computeIfAbsent(name, k -> Optional.ofNullable(art.skill(k))).orElse(null) : null;
			}

			@Override
			public BufferedImage badge(AccountType type)
			{
				return badges && type != null && type.hasBadge() ? badgeImages.computeIfAbsent(type, k -> Optional.ofNullable(art.badge(k))).orElse(null) : null;
			}

			@Override
			public Shots.Pick shots()
			{
				return picked;
			}

			@Override
			public List<ClipFile.Frame> clip(String name)
			{
				return library.readClip(account, name);
			}

			@Override
			public List<ClipFile.Frame> timelapse(int max)
			{
				return library.readTimelapse(account, period.from, period.to, max);
			}

			@Override
			public Emote emote()
			{
				return config.emoteScene() ? Emote.of(library.readEmote(account)) : null;
			}

			@Override
			public List<ClipLibrary.Recording> recordings()
			{
				// Recorded during the period, or since: like shots, footage taken to make this recap counts.
				long from = period.from.atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();
				List<ClipLibrary.Recording> out = new java.util.ArrayList<>();
				for (ClipLibrary.Recording r : library.listRecordings(account))
				{
					if (r.end() >= from)
					{
						out.add(r);
					}
				}
				return out;
			}

			@Override
			public List<ClipFile.Frame> recording(String name, long from, long to)
			{
				return library.readRecording(account, name, from, to);
			}

			@Override
			public List<Sticker> stickers()
			{
				return library.stickers(account, true, true);
			}

			@Override
			public StickerBoard stickerBoard()
			{
				return library.readBoard(account);
			}

			@Override
			public byte[] song()
			{
				return art != null && config.musicEnabled() ? art.song(config.musicTrack()) : null;
			}
		};
	}

	private void update(Job job, Status status, String message)
	{
		job.status = status;
		job.message = message;
		listener.accept(job);
	}

	private Filepath recapsDir(long account)
	{
		return store.accountDir(account).join("recaps");
	}

	private Saved readMeta(Filepath dir)
	{
		Filepath f = dir.join(META);
		if (!f.exists())
		{
			return null;
		}
		try (Reader r = f.openReader())
		{
			Meta m = store.gson().fromJson(r, Meta.class);
			return m == null ? null : new Saved(m, dir);
		}
		catch (IOException | JsonParseException e)
		{
			return null;
		}
	}

	private void writeMeta(Filepath dir, Meta meta) throws IOException
	{
		Filepath tmp = dir.join(META + ".tmp");
		tmp.write(store.gson().toJson(meta));
		tmp.moveTo(dir.join(META), StandardCopyOption.REPLACE_EXISTING);
	}

	private State readState(long account)
	{
		Filepath f = recapsDir(account).join(STATE);
		if (f.exists())
		{
			try (Reader r = f.openReader())
			{
				State s = store.gson().fromJson(r, State.class);
				if (s != null && s.done != null)
				{
					return s;
				}
			}
			catch (IOException | JsonParseException e)
			{
				log.warn("Unable to read {}", f, e);
			}
		}
		return new State();
	}

	private void writeState(long account, State state)
	{
		Filepath dir = recapsDir(account);
		try
		{
			dir.createDirectories();
			Filepath tmp = dir.join(STATE + ".tmp");
			tmp.write(store.gson().toJson(state));
			tmp.moveTo(dir.join(STATE), StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			log.warn("Unable to save the recap schedule", e);
		}
	}

	/** Stops rendering; a video in progress is abandoned and its partial file removed. */
	void close() throws InterruptedException
	{
		closed = true;
		for (Job j : jobs)
		{
			j.cancel();
		}
		render.shutdown();
		if (!render.awaitTermination(10, TimeUnit.SECONDS))
		{
			log.warn("Gielinor Wrapped rendering did not stop in time");
		}
	}
}

package com.gielinorwrapped;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.ImageInputStream;
import org.w3c.dom.Node;

/**
 * Turns a Death Recap replay GIF into clip frames. Its frames only hold what changed since the one before, so
 * each is drawn onto a full canvas first.
 */
final class ReplayGif
{
	private static final String GIF_FORMAT = "javax_imageio_gif_image_1.0";
	private static final int MAX_FRAMES = 400;
	static final float QUALITY = 0.85f;

	private ReplayGif()
	{
	}

	/**
	 * The replay as clip frames timed {@code start + times[i]}. Frames without a time are dropped, and frames are
	 * scaled down to at most {@code maxWidth}. Returns an empty list if the GIF can't be read.
	 */
	static List<ClipFile.Frame> frames(byte[] gif, long start, int[] times, int maxWidth)
	{
		List<ClipFile.Frame> out = new ArrayList<>();
		if (gif == null || times == null || times.length == 0)
		{
			return out;
		}
		try (ImageInputStream in = ImageIO.createImageInputStream(new ByteArrayInputStream(gif)))
		{
			Iterator<ImageReader> readers = in == null ? null : ImageIO.getImageReaders(in);
			if (readers == null || !readers.hasNext())
			{
				return out;
			}
			ImageReader reader = readers.next();
			try
			{
				reader.setInput(in, false);
				int width = -1;
				int height = -1;
				IIOMetadata stream = reader.getStreamMetadata();
				if (stream != null)
				{
					Node screen = child(stream.getAsTree("javax_imageio_gif_stream_1.0"), "LogicalScreenDescriptor");
					if (screen != null)
					{
						width = attr(screen, "logicalScreenWidth", -1);
						height = attr(screen, "logicalScreenHeight", -1);
					}
				}
				BufferedImage canvas = null;
				long last = Long.MIN_VALUE;
				for (int i = 0; i < Math.min(times.length, MAX_FRAMES); i++)
				{
					BufferedImage part;
					try
					{
						part = reader.read(i);
					}
					catch (IndexOutOfBoundsException e)
					{
						break;
					}
					IIOMetadataNode meta = (IIOMetadataNode) reader.getImageMetadata(i).getAsTree(GIF_FORMAT);
					Node desc = child(meta, "ImageDescriptor");
					Node control = child(meta, "GraphicControlExtension");
					int x = desc == null ? 0 : attr(desc, "imageLeftPosition", 0);
					int y = desc == null ? 0 : attr(desc, "imageTopPosition", 0);
					String disposal = control == null ? "none" : ((IIOMetadataNode) control).getAttribute("disposalMethod");
					if (canvas == null)
					{
						canvas = new BufferedImage(width > 0 ? width : part.getWidth() + x, height > 0 ? height : part.getHeight() + y, BufferedImage.TYPE_INT_RGB);
					}
					BufferedImage before = "restoreToPrevious".equals(disposal) ? copy(canvas, canvas.getWidth()) : null;
					Graphics2D g = canvas.createGraphics();
					g.drawImage(part, x, y, null);
					g.dispose();
					long time = start + times[i];
					if (time > last)
					{
						out.add(new ClipFile.Frame(time, ClipFile.encode(copy(canvas, maxWidth), QUALITY)));
						last = time;
					}
					if ("restoreToBackgroundColor".equals(disposal))
					{
						Graphics2D c = canvas.createGraphics();
						c.setColor(java.awt.Color.BLACK);
						c.fillRect(x, y, part.getWidth(), part.getHeight());
						c.dispose();
					}
					else if (before != null)
					{
						canvas = before;
					}
				}
			}
			finally
			{
				reader.dispose();
			}
		}
		catch (IOException | RuntimeException e)
		{
			// A damaged replay just means no replay clip.
			out.clear();
		}
		return out;
	}

	/** An RGB copy, scaled down to at most {@code maxWidth}. */
	private static BufferedImage copy(BufferedImage img, int maxWidth)
	{
		double scale = Math.min(1, maxWidth / (double) img.getWidth());
		int w = Math.max(1, (int) Math.round(img.getWidth() * scale));
		int h = Math.max(1, (int) Math.round(img.getHeight() * scale));
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(img, 0, 0, w, h, null);
		g.dispose();
		return out;
	}

	private static Node child(Node parent, String name)
	{
		for (Node n = parent.getFirstChild(); n != null; n = n.getNextSibling())
		{
			if (name.equals(n.getNodeName()))
			{
				return n;
			}
		}
		return null;
	}

	private static int attr(Node node, String name, int fallback)
	{
		Node a = node.getAttributes().getNamedItem(name);
		if (a == null)
		{
			return fallback;
		}
		try
		{
			return Integer.parseInt(a.getNodeValue());
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}
}

package com.gielinorwrapped;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Locale;
import java.util.function.LongFunction;
import java.util.function.Supplier;

/** The scenes a recap video is made of. Each draws itself at a time {@code t} seconds into the scene. */
final class Scenes
{
	private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("EEE d MMM HH:mm", Locale.ENGLISH);

	private Scenes()
	{
	}

	/** How text is drawn, shared by every scene. */
	static final class Look
	{
		final Theme theme;
		final GielinorWrappedConfig.CaptionStyle style;
		final GielinorWrappedConfig.CaptionPosition position;
		final float captionScale;
		final boolean captions;

		Look(Theme theme, GielinorWrappedConfig.CaptionStyle style, GielinorWrappedConfig.CaptionPosition position, float captionScale, boolean captions)
		{
			this.theme = theme;
			this.style = style;
			this.position = position;
			this.captionScale = captionScale;
			this.captions = captions;
		}

		static Look of(GielinorWrappedConfig config)
		{
			return new Look(Theme.of(config), config.captionStyle(), config.captionPosition(), config.captionSize() / 100f, config.captionsEnabled());
		}

		float captionSize(int w, int h)
		{
			return Math.min(w, h) * 0.06f * captionScale;
		}
	}

	abstract static class Scene
	{
		final String name;
		final Look look;
		double duration;

		Scene(String name, Look look, double duration)
		{
			this.name = name;
			this.look = look;
			this.duration = duration;
		}

		/** Loads what the scene needs just before it plays. */
		void open() throws IOException
		{
		}

		/** Frees what {@link #open} loaded. */
		void close()
		{
		}

		abstract void render(Graphics2D g, int w, int h, double t);

		/** Scenes that can't be shortened report their own length here. */
		double minDuration()
		{
			return duration;
		}

		/** Footage drawn darkened behind the scene, or null for the theme background. */
		Reel under;
		/** Green-screened footage drawn over the scene, or null. */
		Reel over;
		/** Stickers slapped on the scene. */
		final List<Placement> stickers = new ArrayList<>();

		/** Opens the scene and its reels. */
		final void openAll() throws IOException
		{
			open();
			if (under != null)
			{
				under.open();
			}
			if (over != null)
			{
				over.open();
			}
		}

		final void closeAll()
		{
			close();
			if (under != null)
			{
				under.close();
			}
			if (over != null)
			{
				over.close();
			}
		}

		/** The theme background, or footage behind it when the scene has some. */
		void background(Graphics2D g, int w, int h, double t)
		{
			Theme th = look.theme;
			BufferedImage img = under == null ? null : under.at(t);
			if (img == null)
			{
				th.background(g, w, h, t);
				return;
			}
			if (under.keyed())
			{
				th.background(g, w, h, t);
				drawCover(g, img, 0, 0, w, h, 1.0);
				return;
			}
			drawCover(g, img, 0, 0, w, h, 1.04 + 0.03 * Captions.clamp(t / Math.max(0.1, duration)));
			// Darken and tint so the text on top stays readable.
			g.setColor(Theme.alpha(th.top, th.light() ? 0.72 : 0.62));
			g.fillRect(0, 0, w, h);
		}

		/** Keyed footage and stickers, drawn over whatever {@link #render} drew. */
		void foreground(Graphics2D g, int w, int h, double t, boolean wobble)
		{
			BufferedImage img = over == null ? null : over.at(t);
			if (img != null)
			{
				// The player stands in the lower part of the frame, under the heading.
				int bh = (int) (h * 0.62);
				int bw = (int) (bh * img.getWidth() / (double) img.getHeight());
				drawCover(g, img, w - bw, h - bh, bw, bh, 1.0);
			}
			int u = Math.min(w, h);
			for (Placement p : stickers)
			{
				p.draw(g, w, h, u, t, duration, wobble);
			}
		}

		/** Draws a caption that appears {@code start} seconds into the scene and stays to its end. */
		void caption(Graphics2D g, String text, Rectangle area, GielinorWrappedConfig.CaptionPosition position, double t, double start, int w, int h)
		{
			if (look.captions)
			{
				Captions.draw(g, text, area, position, look.style, look.theme, look.captionSize(w, h), t - start, duration - start);
			}
		}
	}

	/** Opening card: the period label, the title and the dates. */
	static final class Title extends Scene
	{
		private final String label;
		private final String title;
		private final String dates;
		/** The player's emote, standing under the text, or null. */
		Emote player;

		Title(Look look, double duration, String label, String title, String dates)
		{
			super("title", look, duration);
			this.label = label;
			this.title = title;
			this.dates = dates;
		}

		@Override
		void render(Graphics2D g, int w, int h, double t)
		{
			Theme th = look.theme;
			background(g, w, h, t);
			int u = Math.min(w, h);
			double p = Captions.ease(Captions.clamp(t / 0.6));
			// Accent rule growing out from the centre.
			int lineW = (int) (u * 0.5 * p);
			// Text sits in the upper third, leaving the middle for the player.
			int cy = (int) (h * 0.3);
			g.setColor(th.accent);
			g.fillRect(w / 2 - lineW / 2, cy - (int) (u * 0.1), lineW, Math.max(3, u / 160));
			Captions.centered(g, label.toUpperCase(Locale.ROOT), w / 2, cy - (int) (u * 0.125), th.bold(u * 0.034f), Theme.alpha(th.muted, p), (int) (w * 0.9));
			Captions.draw(g, title, new Rectangle(0, cy - (int) (u * 0.09), w, (int) (u * 0.18)), GielinorWrappedConfig.CaptionPosition.CENTER,
				GielinorWrappedConfig.CaptionStyle.SHADOW, th, u * 0.065f * look.captionScale, t - 0.2, duration);
			double q = Captions.clamp((t - 0.7) / 0.5);
			Captions.centered(g, dates, w / 2, cy + (int) (u * 0.14), th.regular(u * 0.036f), Theme.alpha(th.muted, q), (int) (w * 0.9));
			if (player != null)
			{
				player.draw(g, w / 2.0, h * 0.95, Math.min(h * 0.5, u * 0.55), t - 0.3);
			}
		}
	}

	/** A big number counting up, a caption and a top-five bar chart or an hours-of-day histogram. */
	static final class Stat extends Scene
	{
		private final String heading;
		private final String caption;
		private final long value;
		private final LongFunction<String> format;
		private final List<Recap.Entry> entries;
		private final LongFunction<String> entryFormat;
		private final long[] hours;
		private List<BufferedImage> rowIcons = new ArrayList<>();
		private List<BufferedImage> strip = new ArrayList<>();
		private int iconsFor = -1;
		private List<BufferedImage> bigRowIcons;
		private List<BufferedImage> bigStrip;

		Stat(String name, Look look, double duration, String heading, String caption, long value, LongFunction<String> format,
			List<Recap.Entry> entries, LongFunction<String> entryFormat, long[] hours)
		{
			super(name, look, duration);
			this.heading = heading;
			this.caption = caption;
			this.value = value;
			this.format = format;
			this.entries = entries;
			this.entryFormat = entryFormat;
			this.hours = hours;
		}

		/** Icons for the top-five rows, in order; null entries are skipped. */
		Stat icons(List<BufferedImage> icons)
		{
			rowIcons = icons;
			return this;
		}

		/** A row of sprites shown under the chart, e.g. the best drops. */
		Stat strip(List<BufferedImage> sprites)
		{
			strip = sprites;
			return this;
		}

		private void prepare(int rowSize, int stripSize)
		{
			if (iconsFor == rowSize + stripSize * 10_000)
			{
				return;
			}
			iconsFor = rowSize + stripSize * 10_000;
			bigRowIcons = new ArrayList<>();
			for (BufferedImage img : rowIcons)
			{
				bigRowIcons.add(img == null ? null : Sprites.splash(img, rowSize, new Color(0x111111)));
			}
			bigStrip = new ArrayList<>();
			for (BufferedImage img : strip)
			{
				BufferedImage big = Sprites.splash(img, stripSize, look.theme.accent);
				if (big != null)
				{
					bigStrip.add(big);
				}
			}
		}

		@Override
		void render(Graphics2D g, int w, int h, double t)
		{
			Theme th = look.theme;
			background(g, w, h, t);
			int u = Math.min(w, h);
			boolean tall = h > w * 1.2;
			Captions.centered(g, heading.toUpperCase(Locale.ROOT), w / 2, (int) (h * (tall ? 0.16 : 0.12)), th.bold(u * 0.045f),
				Theme.alpha(th.muted, Captions.clamp(t / 0.3)), (int) (w * 0.9));
			long shown = Math.round(value * Captions.ease(Captions.clamp(t / 1.4)));
			float pop = (float) (1 + 0.08 * Math.max(0, 1 - Math.abs(t - 1.5) / 0.2));
			Captions.centered(g, format.apply(shown), w / 2, (int) (h * (tall ? 0.28 : 0.30)), th.bold(u * 0.15f * pop), th.accent, (int) (w * 0.92));
			caption(g, caption, new Rectangle(0, (int) (h * (tall ? 0.31 : 0.33)), w, (int) (h * 0.2)), GielinorWrappedConfig.CaptionPosition.TOP, t, 0.6, w, h);

			Rectangle chart = new Rectangle((int) (w * (tall ? 0.08 : 0.15)), (int) (h * (tall ? 0.52 : 0.56)), (int) (w * (tall ? 0.84 : 0.7)), (int) (h * (tall ? 0.38 : 0.36)));
			if (hours != null)
			{
				histogram(g, chart, t - 0.8, u);
			}
			else if (entries != null && !entries.isEmpty())
			{
				int stripH = strip.isEmpty() ? 0 : (int) (chart.height * 0.3);
				chart.height -= stripH;
				prepare((int) (chart.height / 5 * 0.62 * 1.3), Math.min(stripH, (int) (chart.width / Math.max(1, strip.size()) * 0.9)));
				bars(g, chart, t - 0.8, u);
				if (stripH > 0)
				{
					drawStrip(g, new Rectangle(chart.x, chart.y + chart.height, chart.width, stripH), t - 1.2);
				}
			}
		}

		private void drawStrip(Graphics2D g, Rectangle r, double t)
		{
			int n = bigStrip.size();
			for (int i = 0; i < n; i++)
			{
				double p = Captions.clamp((t - i * 0.1) / 0.4);
				if (p <= 0)
				{
					continue;
				}
				double cx = r.x + r.width * (i + 0.5) / n;
				double bob = Math.sin(t * 2.2 + i) * r.height * 0.03;
				Sprites.drawCentered(g, bigStrip.get(i), cx, r.y + r.height * 0.55 + bob, Splash.backOut(p), 0);
			}
		}

		private void bars(Graphics2D g, Rectangle r, double t, int u)
		{
			Theme th = look.theme;
			List<Recap.Entry> top = Recap.top(entries, 5);
			int rowH = r.height / 5;
			int barH = (int) (rowH * 0.62);
			long max = top.get(0).value;
			Font labelFont = th.bold(Math.max(12f, barH * 0.55f));
			for (int i = 0; i < top.size(); i++)
			{
				double p = Captions.ease(Captions.clamp((t - i * 0.12) / 0.6));
				if (p <= 0)
				{
					continue;
				}
				Recap.Entry e = top.get(i);
				int y = r.y + i * rowH;
				int full = max <= 0 ? 0 : (int) (r.width * Math.max(0.04, e.value / (double) max));
				int bw = (int) (full * p);
				g.setColor(Theme.alpha(th.panel, p));
				g.fillRoundRect(r.x, y, r.width, barH, barH / 2, barH / 2);
				g.setColor(Theme.alpha(i == 0 ? th.accent : th.accent2, p * (i == 0 ? 1 : 0.75)));
				g.fillRoundRect(r.x, y, bw, barH, barH / 2, barH / 2);
				g.setFont(labelFont);
				FontMetrics fm = g.getFontMetrics();
				int base = y + (barH + fm.getAscent() - fm.getDescent()) / 2;
				String v = entryFormat.apply(e.value);
				int textX = r.x + barH / 3;
				BufferedImage icon = bigRowIcons != null && i < bigRowIcons.size() ? bigRowIcons.get(i) : null;
				if (icon != null)
				{
					Sprites.drawCentered(g, icon, r.x + barH * 0.62, y + barH / 2.0, p, 0);
					textX = r.x + (int) (barH * 1.25);
				}
				g.setColor(Theme.alpha(th.light() ? th.text : Color.WHITE, p));
				drawShadowed(g, (i + 1) + ". " + e.name, textX, base, th, p);
				drawShadowed(g, v, r.x + r.width - barH / 3 - fm.stringWidth(v), base, th, p);
			}
		}

		private static void drawShadowed(Graphics2D g, String s, int x, int y, Theme th, double a)
		{
			Color c = g.getColor();
			if (!th.light())
			{
				g.setColor(new Color(0, 0, 0, (int) (150 * a)));
				g.drawString(s, x + 2, y + 2);
			}
			g.setColor(c);
			g.drawString(s, x, y);
		}

		private void histogram(Graphics2D g, Rectangle r, double t, int u)
		{
			Theme th = look.theme;
			long max = 1;
			int peak = 0;
			for (int i = 0; i < 24; i++)
			{
				if (hours[i] > max)
				{
					max = hours[i];
					peak = i;
				}
			}
			int labelH = (int) (u * 0.04);
			int barArea = r.height - labelH * 2;
			double slot = r.width / 24.0;
			for (int i = 0; i < 24; i++)
			{
				double p = Captions.ease(Captions.clamp((t - i * 0.03) / 0.5));
				int bh = (int) (Math.max(u / 200.0, barArea * hours[i] / (double) max) * p);
				int x = (int) (r.x + i * slot + slot * 0.15);
				g.setColor(hours[i] > 0 && i == peak ? th.accent : Theme.alpha(th.accent2, 0.7));
				g.fillRect(x, r.y + barArea - bh, (int) Math.max(1, slot * 0.7), bh);
			}
			g.setColor(th.muted);
			Font f = th.regular(labelH);
			for (int i = 0; i < 24; i += 6)
			{
				Captions.centered(g, Recap.hour(i), (int) (r.x + i * slot + slot / 2), r.y + barArea + labelH + labelH / 2, f, th.muted, (int) (slot * 4));
			}
		}
	}

	/** A recorded highlight playing in real time, with a badge and caption. */
	static final class Clip extends Scene
	{
		private final Supplier<List<ClipFile.Frame>> loader;
		private final String badge;
		private final String caption;
		/** Offset into the clip, in milliseconds, where the scene starts. */
		long start;
		final long length;
		final long momentOffset;
		final int importance;
		/** When the moment happened, for ordering clips in the video. */
		long momentOrder;
		/** The highlight the clip shows, for picking a matching sticker. */
		Moment moment;
		/** Item or skill sprite shown beside the badge, or null. */
		BufferedImage icon;
		private int iconFor = -1;
		private BufferedImage bigIcon;
		private List<ClipFile.Frame> frames;
		private int decodedIndex = -1;
		private BufferedImage decoded;

		/**
		 * @param length milliseconds of footage in the clip
		 * @param momentOffset milliseconds from the first frame to the moment itself
		 */
		Clip(Look look, Supplier<List<ClipFile.Frame>> loader, long length, long momentOffset, int importance, String badge, String caption)
		{
			super("clip", look, length / 1000.0);
			this.loader = loader;
			this.length = length;
			this.momentOffset = momentOffset;
			this.importance = importance;
			this.badge = badge;
			this.caption = caption;
		}

		/** Shortens the scene, keeping footage around the moment: two thirds before, one third after. */
		void trim(double seconds)
		{
			long keep = Math.min(length, Math.round(seconds * 1000));
			long s = momentOffset - keep * 2 / 3;
			start = Math.max(0, Math.min(length - keep, s));
			duration = keep / 1000.0;
		}

		@Override
		double minDuration()
		{
			return Math.min(duration, 2.5);
		}

		@Override
		void open()
		{
			frames = loader.get();
			decodedIndex = -1;
		}

		@Override
		void close()
		{
			frames = null;
			decoded = null;
		}

		@Override
		void render(Graphics2D g, int w, int h, double t)
		{
			Theme th = look.theme;
			BufferedImage img = frameAt(t);
			int u = Math.min(w, h);
			if (img == null)
			{
				th.background(g, w, h, t);
			}
			else
			{
				double zoom = 1 + 0.04 * (t / Math.max(0.1, duration));
				double imgAspect = img.getWidth() / (double) img.getHeight();
				double outAspect = w / (double) h;
				if (Math.abs(Math.log(imgAspect / outAspect)) < 0.25)
				{
					drawCover(g, img, 0, 0, w, h, zoom);
				}
				else
				{
					// Very different shapes: game footage in a band over the theme background.
					th.background(g, w, h, t);
					int bw = w;
					int bh = (int) (w / imgAspect);
					if (bh > h)
					{
						bh = h;
						bw = (int) (h * imgAspect);
					}
					drawCover(g, img, (w - bw) / 2, (h - bh) / 2, bw, bh, zoom);
				}
			}

			if (badge != null)
			{
				double p = Captions.ease(Captions.clamp(t / 0.4));
				Font f = th.bold(u * 0.04f);
				g.setFont(f);
				FontMetrics fm = g.getFontMetrics();
				int pad = u / 60;
				int bw = fm.stringWidth(badge) + pad * 2;
				int bh = fm.getHeight() + pad;
				int x = (int) (u * 0.04 - (1 - p) * (bw + u * 0.04));
				int y = (int) (u * 0.04);
				g.setColor(th.accent);
				g.fillRoundRect(x, y, bw, bh, bh / 2, bh / 2);
				g.setColor(isBright(th.accent) ? new Color(0x111111) : Color.WHITE);
				g.drawString(badge, x + pad, y + pad / 2 + fm.getAscent());
				if (icon != null)
				{
					int size = (int) (u * 0.16);
					if (iconFor != size)
					{
						bigIcon = Sprites.splash(icon, size, th.accent);
						iconFor = size;
					}
					double q = Captions.clamp((t - 0.25) / 0.4);
					Sprites.drawCentered(g, bigIcon, x + size / 2.0, y + bh + size * 0.6 + Math.sin(t * 2.5) * size * 0.04, Splash.backOut(q), -0.08);
				}
			}
			double captionStart = Math.max(0.2, Math.min(duration - 2.5, (momentOffset - start) / 1000.0 - 0.3));
			caption(g, caption, new Rectangle(0, 0, w, h), look.position, t, captionStart, w, h);
		}

		private BufferedImage frameAt(double t)
		{
			if (frames == null || frames.isEmpty())
			{
				return null;
			}
			long target = frames.get(0).time + start + Math.round(t * 1000);
			int lo = 0;
			int hi = frames.size() - 1;
			while (lo < hi)
			{
				int mid = (lo + hi + 1) >>> 1;
				if (frames.get(mid).time <= target)
				{
					lo = mid;
				}
				else
				{
					hi = mid - 1;
				}
			}
			if (lo != decodedIndex)
			{
				try
				{
					BufferedImage next = frames.get(lo).image();
					if (next != null)
					{
						decoded = next;
					}
				}
				catch (IOException e)
				{
					// keep showing the previous frame
				}
				decodedIndex = lo;
			}
			return decoded;
		}
	}

	/** Timelapse stills played back quickly with a date stamp. */
	static final class Timelapse extends Scene
	{
		private final Supplier<List<ClipFile.Frame>> loader;
		private final String caption;
		private final int count;
		private List<ClipFile.Frame> frames;
		private int decodedIndex = -1;
		private BufferedImage decoded;

		Timelapse(Look look, Supplier<List<ClipFile.Frame>> loader, int count, double duration, String caption)
		{
			super("timelapse", look, duration);
			this.loader = loader;
			this.count = count;
			this.caption = caption;
		}

		@Override
		double minDuration()
		{
			return Math.min(duration, 2.5);
		}

		@Override
		void open()
		{
			frames = loader.get();
		}

		@Override
		void close()
		{
			frames = null;
			decoded = null;
			decodedIndex = -1;
		}

		@Override
		void render(Graphics2D g, int w, int h, double t)
		{
			Theme th = look.theme;
			int n = frames == null ? 0 : frames.size();
			if (n == 0)
			{
				th.background(g, w, h, t);
				return;
			}
			int i = Math.min(n - 1, (int) (t / duration * n));
			if (i != decodedIndex)
			{
				try
				{
					BufferedImage next = frames.get(i).image();
					if (next != null)
					{
						decoded = next;
					}
				}
				catch (IOException e)
				{
					// keep the previous still
				}
				decodedIndex = i;
			}
			if (decoded == null)
			{
				th.background(g, w, h, t);
			}
			else
			{
				drawCover(g, decoded, 0, 0, w, h, 1);
			}
			int u = Math.min(w, h);
			String stamp = STAMP.format(Instant.ofEpochMilli(frames.get(i).time).atZone(ZoneId.systemDefault()));
			Font f = th.bold(u * 0.035f);
			g.setFont(f);
			FontMetrics fm = g.getFontMetrics();
			int pad = u / 70;
			int sw = fm.stringWidth(stamp);
			int x = w - sw - pad * 3;
			int y = h - fm.getHeight() - pad * 3;
			g.setColor(new Color(0, 0, 0, 150));
			g.fillRoundRect(x - pad, y - pad / 2, sw + pad * 2, fm.getHeight() + pad, pad * 2, pad * 2);
			g.setColor(Color.WHITE);
			g.drawString(stamp, x, y + fm.getAscent());
			caption(g, caption, new Rectangle(0, 0, w, h), GielinorWrappedConfig.CaptionPosition.TOP, t, 0.2, w, h);
		}

		int count()
		{
			return count;
		}
	}

	/** A centred caption on the theme background, used for the persona and the outro. */
	static final class Card extends Scene
	{
		private final String label;
		private final String text;
		private final String footer;
		/** Loads a screenshot to show darkened behind the text, or null for the theme background. */
		Supplier<BufferedImage> backdrop;
		/** The player's emote, standing under the text, or null. */
		Emote player;
		private BufferedImage image;

		Card(String name, Look look, double duration, String label, String text, String footer)
		{
			super(name, look, duration);
			this.label = label;
			this.text = text;
			this.footer = footer;
		}

		@Override
		void open()
		{
			image = backdrop == null ? null : backdrop.get();
		}

		@Override
		void close()
		{
			image = null;
		}

		@Override
		void render(Graphics2D g, int w, int h, double t)
		{
			Theme th = look.theme;
			if (image != null)
			{
				drawCover(g, image, 0, 0, w, h, 1.08 - 0.06 * Captions.clamp(t / Math.max(0.1, duration)));
				g.setColor(new Color(0, 0, 0, th.light() ? 120 : 150));
				g.fillRect(0, 0, w, h);
			}
			else
			{
				background(g, w, h, t);
			}
			int u = Math.min(w, h);
			if (player != null)
			{
				// Text moves up to leave room for the player.
				g.translate(0, -(int) (h * 0.14));
			}
			if (label != null)
			{
				Captions.centered(g, label.toUpperCase(Locale.ROOT), w / 2, (int) (h * 0.3), th.bold(u * 0.04f),
					Theme.alpha(th.muted, Captions.clamp(t / 0.3)), (int) (w * 0.9));
			}
			Captions.draw(g, text, new Rectangle((int) (w * 0.05), (int) (h * 0.32), (int) (w * 0.9), (int) (h * 0.36)), GielinorWrappedConfig.CaptionPosition.CENTER,
				look.style == GielinorWrappedConfig.CaptionStyle.BOXED ? GielinorWrappedConfig.CaptionStyle.SHADOW : look.style, th,
				u * 0.075f * look.captionScale, t - 0.25, duration);
			if (footer != null)
			{
				Captions.centered(g, footer, w / 2, (int) (h * (player != null ? 0.7 : 0.8)), th.regular(u * 0.04f), Theme.alpha(th.muted, Captions.clamp((t - 0.8) / 0.4)), (int) (w * 0.9));
			}
			if (player != null)
			{
				g.translate(0, (int) (h * 0.14));
				player.draw(g, w / 2.0, h * 0.96, Math.min(h * 0.36, u * 0.4), t - 0.4);
			}
		}
	}

