	/** The poster background: the cover shot, else the top moment's frame, else a timelapse still. */
	static BufferedImage backdrop(Composer.Media media, Recap r)
	{
		if (media == null)
		{
			return null;
		}
		Shots.Shot shot = media.shots().backdrop();
		if (shot != null)
		{
			try
			{
				BufferedImage img = shot.read();
				if (img != null)
				{
					return img;
				}
			}
			catch (IOException e)
			{
				log.debug("Unreadable shot {}", shot.file, e);
			}
		}
		Moment top = topMoment(r);
		BufferedImage still = top == null ? null : still(media, top);
		if (still != null)
		{
			return still;
		}
		List<ClipFile.Frame> frames = media.timelapse(1);
		if (!frames.isEmpty())
		{
			try
			{
				return frames.get(0).image();
			}
			catch (IOException e)
			{
				log.debug("Unreadable timelapse frame", e);
			}
		}
		return null;
	}

	/** A film poster: the game view full bleed, the title big, and the numbers set like credits. */
	private static void poster(Graphics2D g, Theme theme, Recap r, GielinorWrappedConfig config, Map<String, String> tok,
		BufferedImage backdrop, String share, int w, int h, int u, int m)
	{
		if (backdrop != null)
		{
			Scenes.drawCover(g, backdrop, 0, 0, w, h, 1.04);
		}
		Color dark = Theme.mix(theme.bottom, Color.BLACK, 0.55);
		g.setPaint(new java.awt.GradientPaint(0, h * 0.3f, Theme.alpha(dark, 0), 0, h * 0.78f, Theme.alpha(dark, 0.94)));
		g.fillRect(0, 0, w, h);
		g.setColor(Theme.alpha(dark, 0.94));
		g.fillRect(0, (int) (h * 0.78f), w, h);
		g.setPaint(new java.awt.GradientPaint(0, 0, Theme.alpha(dark, 0.7), 0, h * 0.16f, Theme.alpha(dark, 0)));
		g.fillRect(0, 0, w, (int) (h * 0.16f));

		Captions.centered(g, (tok.get("player") + " presents").toUpperCase(), w / 2, m + u / 40, theme.regular(u * 0.03f), new Color(255, 255, 255, 210), w - 2 * m);

		int credits = h - m - u / 30;
		String stats = String.join("   ·   ", nonEmpty(tok.get("xp") + " XP", tok.get("hours"),
			r.total.totalLevels() > 0 ? tok.get("levels") + " levels" : "",
			r.total.lootValue > 0 ? tok.get("loot") : "",
			r.totalKills > 0 ? tok.get("kills") + " kills" : ""));
		Captions.centered(g, r.period.describe().toUpperCase(), w / 2, credits, theme.bold(u * 0.028f), theme.accent, w - 2 * m);
		Captions.centered(g, stats, w / 2, credits - u / 18, theme.regular(u * 0.034f), new Color(255, 255, 255, 220), w - 2 * m);
		g.setColor(Theme.alpha(theme.accent, 0.8));
		g.fillRect(w / 2 - u / 6, credits - u / 9, u / 3, Math.max(2, u / 300));

		int y = credits - u / 7;
		if (share != null)
		{
			Captions.centered(g, "“" + share + "”", w / 2, y, theme.regular(u * 0.036f), new Color(255, 255, 255, 230), w - 2 * m);
			y -= u / 12;
		}
		else if (r.persona != null && !tok.get("persona").isEmpty())
		{
			Captions.centered(g, tok.get("persona"), w / 2, y, theme.bold(u * 0.04f), theme.accent, w - 2 * m);
			y -= u / 12;
		}
		List<String> title = Splash.lines(Recap.fill(config.titleText(), tok));
		Font tf = theme.bold(u * (title.size() > 1 ? 0.085f : 0.1f));
		for (int i = title.size() - 1; i >= 0; i--)
		{
			Sprites.outlined(g, title.get(i).toUpperCase(), w / 2.0, y, tf, Color.WHITE, 0, w - 2 * m);
			y -= g.getFontMetrics(tf).getAscent() * 1.05;
		}
	}

	/** The in-game hiscores page: one row per skill with the levels and XP gained, and the total underneath. */
	private static void hiscores(Graphics2D g, Theme theme, Recap r, Map<String, String> tok, Composer.Media art, int w, int h, int u, int m)
	{
		Captions.centered(g, ("Hiscores · " + tok.get("player")).toUpperCase(), w / 2, m + u / 25, theme.bold(u * 0.05f), theme.text, w - 2 * m);
		Captions.centered(g, r.period.describe(), w / 2, m + u / 25 + u / 20, theme.regular(u * 0.03f), theme.muted, w - 2 * m);

		Rectangle box = new Rectangle(m, m + u * 16 / 100, w - 2 * m, h - 2 * m - u * 16 / 100 - u / 25);
		Map<String, Long> levels = new java.util.HashMap<>();
		for (Recap.Entry e : r.levels)
		{
			levels.put(e.name, e.value);
		}
		int pad = u / 36;
		int maxRows = Math.max(3, Math.min(10, (box.height - pad * 2) / (u / 14) - 2));
		List<Recap.Entry> rows = Recap.top(r.skills, maxRows);
		int rowH = Math.min(u / 11, (box.height - pad * 2) / (Math.max(rows.size(), 1) + 3));
		int used = pad * 2 + rowH * (Math.max(rows.size(), 1) + 3);
		box.y += (box.height - used) / 2;
		box.height = used;
		int arc = u / 30;
		g.setColor(theme.panel);
		g.fillRoundRect(box.x, box.y, box.width, box.height, arc, arc);
		int colSkill = box.x + pad;
		int colXp = box.x + box.width - pad;
		int colLevels = box.x + box.width * 58 / 100;
		float textSize = Math.min(rowH * 0.5f, u * 0.042f);
		Font head = theme.bold(textSize * 0.9f);
		Font cell = theme.regular(textSize);
		Font cellBold = theme.bold(textSize);

		int y = box.y + pad;
		drawRow(g, head, theme.accent, "SKILL", "LEVELS", "XP", colSkill, colLevels, colXp, y, rowH);
		g.setColor(Theme.alpha(theme.muted, 0.4));
		g.fillRect(box.x + pad, y + rowH - Math.max(1, u / 400), box.width - pad * 2, Math.max(1, u / 400));
		y += rowH;
		if (rows.isEmpty())
		{
			Captions.centered(g, "No XP tracked yet", box.x + box.width / 2, y + rowH, cell, theme.muted, box.width);
		}
		for (int i = 0; i < rows.size(); i++)
		{
			Recap.Entry e = rows.get(i);
			if (i % 2 == 1)
			{
				g.setColor(Theme.alpha(theme.text, 0.05));
				g.fillRect(box.x + pad, y, box.width - pad * 2, rowH);
			}
			int textX = colSkill;
			BufferedImage icon = art == null ? null : art.skill(e.name);
			if (icon != null)
			{
				int size = rowH * 3 / 4;
				Sprites.drawCentered(g, Sprites.upscale(icon, size), textX + size / 2.0, y + rowH / 2.0, 1, 0);
				textX += size + u / 80;
			}
			Long lv = levels.get(e.name);
			drawRow(g, i == 0 ? cellBold : cell, i == 0 ? theme.accent : theme.text, e.name,
				lv == null || lv == 0 ? "–" : "+" + lv, Recap.number(e.value), textX, colLevels, colXp, y, rowH);
			y += rowH;
		}
		y = box.y + box.height - pad - rowH;
		g.setColor(Theme.alpha(theme.accent, 0.18));
		g.fillRoundRect(box.x + pad, y, box.width - pad * 2, rowH, arc / 2, arc / 2);
		drawRow(g, cellBold, theme.text, "Overall", r.total.totalLevels() > 0 ? "+" + tok.get("levels") : "–", tok.get("xp"), colSkill + u / 80, colLevels, colXp - u / 80, y, rowH);
	}

	/** A table row: the name left aligned, the levels centred on their column and the XP right aligned. */
	private static void drawRow(Graphics2D g, Font font, Color color, String name, String levels, String xp, int x, int levelsX, int xpRight, int y, int rowH)
	{
		g.setFont(font);
		g.setColor(color);
		FontMetrics fm = g.getFontMetrics();
		int baseline = y + rowH / 2 + fm.getAscent() / 2 - fm.getDescent() / 2;
		g.drawString(name, x, baseline);
		g.drawString(levels, levelsX - fm.stringWidth(levels) / 2, baseline);
		g.drawString(xp, xpRight - fm.stringWidth(xp), baseline);
	}

	private static final Color PARCHMENT = new Color(0xE9D8B0);
	private static final Color PARCHMENT_EDGE = new Color(0xB8955A);
	private static final Color INK = new Color(0x3B2A16);
	private static final Color QUEST_RED = new Color(0x8C1C13);

	/** The quest complete scroll: the period as the quest, and what the player earned as the rewards. */
	private static void scroll(Graphics2D g, Theme theme, Recap r, Map<String, String> tok, Composer.Media art, int w, int h, int u)
	{
		int sw = Math.min(w * 88 / 100, (int) (h * 1.25));
		int sh = h * 86 / 100;
		int x = (w - sw) / 2;
		int y = (h - sh) / 2;
		int roll = u / 22;
		g.setColor(new Color(0, 0, 0, 90));
		g.fillRoundRect(x + u / 120, y + u / 80, sw, sh, u / 40, u / 40);
		g.setPaint(new java.awt.GradientPaint(x, 0, Theme.mix(PARCHMENT, PARCHMENT_EDGE, 0.35f), x + sw / 2f, 0, PARCHMENT, true));
		g.fillRect(x, y + roll / 2, sw, sh - roll);
		for (int ry : new int[]{y, y + sh - roll})
		{
			g.setPaint(new java.awt.GradientPaint(0, ry, PARCHMENT_EDGE, 0, ry + roll / 2f, Theme.mix(PARCHMENT, Color.WHITE, 0.2), true));
			g.fillRoundRect(x - roll / 2, ry, sw + roll, roll, roll, roll);
		}
		g.setColor(Theme.alpha(PARCHMENT_EDGE, 0.5));
		g.setStroke(new java.awt.BasicStroke(Math.max(1, u / 300f)));
		g.drawRect(x + u / 30, y + roll + u / 50, sw - u / 15, sh - roll * 2 - u / 25);

		int cx = w / 2;
		int top = y + roll + u / 50;
		Captions.centered(g, "Congratulations!", cx, top + u / 12, theme.bold(u * 0.07f), QUEST_RED, sw - u / 10);
		Captions.centered(g, "You have completed your " + tok.get("periodNoun") + "!", cx, top + u / 12 + u / 16, theme.regular(u * 0.038f), INK, sw - u / 10);

		BufferedImage icon = art == null || r.skills.isEmpty() ? null : art.skill(r.skills.get(0).name);
		int iconY = top + u / 12 + u / 16 + u / 14;
		if (icon != null)
		{
			int size = u / 8;
			Sprites.drawCentered(g, Sprites.splash(icon, size, PARCHMENT_EDGE), cx, iconY + size / 2.0, 1, 0);
			iconY += size + u / 40;
		}
		Captions.centered(g, "You are awarded:", cx, iconY + u / 30, theme.bold(u * 0.042f), QUEST_RED, sw - u / 10);

		List<String> rewards = new ArrayList<>();
		for (Recap.Entry e : Recap.top(r.skills, 3))
		{
			rewards.add(Recap.number(e.value) + " " + e.name + " XP");
		}
		if (r.total.totalLevels() > 0)
		{
			rewards.add(tok.get("levels") + (r.total.totalLevels() == 1 ? " level" : " levels"));
		}
		if (r.total.lootValue > 0)
		{
			rewards.add(tok.get("loot") + " of loot");
		}
		if (r.totalKills > 0)
		{
			rewards.add(tok.get("kills") + " kills");
		}
		if (r.totalClues > 0)
		{
			rewards.add(tok.get("clues") + " clue scrolls");
		}
		rewards.add(tok.get("hours") + " of adventure");
		int bottom = y + sh - roll - u / 12;
		int lineH = u / 19;
		int first = iconY + u / 30 + lineH;
		int fit = Math.max(1, (bottom - first) / lineH);
		Font rf = theme.regular(u * 0.036f);
		for (int i = 0; i < Math.min(fit, rewards.size()); i++)
		{
			Captions.centered(g, rewards.get(i), cx, first + i * lineH, rf, INK, sw - u / 8);
		}
		Captions.centered(g, "Quest points: " + Math.max(1, r.daysPlayed), cx, y + sh - roll - u / 25, theme.bold(u * 0.03f), Theme.mix(INK, PARCHMENT, 0.3), sw - u / 10);
	}

	private static final Color PAPER = new Color(0xF7F4EC);
	private static final Color THERMAL = new Color(0x2A2A2A);

	/** A Grand Exchange till receipt: real trades when the GE was tracked, otherwise the best drops, with the totals at the bottom. */
	private static void receipt(Graphics2D g, Recap r, Map<String, String> tok, Composer.Media art, String share, int w, int h, int u)
	{
		Font big = new Font(Font.MONOSPACED, Font.BOLD, Math.round(u * 0.045f));
		Font mono = new Font(Font.MONOSPACED, Font.PLAIN, Math.round(u * 0.028f));
		Font monoBold = mono.deriveFont(Font.BOLD);
		int pad = u / 25;
		int line = g.getFontMetrics(mono).getHeight();
		int rowStep = line + u / 200;
		int tooth = Math.max(6, u / 60);
		// With Grand Exchange data the receipt lists real trades; otherwise the period's best drops.
		boolean ge = r.hasGe();
		List<ReceiptLine> drops = new ArrayList<>();
		if (ge)
		{
			for (DayRecord.Trade t : r.trades)
			{
				drops.add(new ReceiptLine(t.itemId, (t.buy ? "BUY " : "SELL ") + (t.quantity > 1 ? t.quantity + " x " : "") + t.name,
					(t.buy ? "-" : "+") + Recap.gp(t.value), t.value));
			}
		}
		else
		{
			for (DayRecord.Drop d : r.drops)
			{
				drops.add(new ReceiptLine(d.itemId, (d.quantity > 1 ? d.quantity + " x " : "") + d.name, Recap.gp(d.value), d.value));
			}
		}
		drops.sort((a, b) -> Long.compare(b.value, a.value));
		long volume = ge ? r.total.geBought + r.total.geSold : r.total.lootValue;
		long listed = 0;
		for (ReceiptLine d : drops)
		{
			listed += d.value;
		}
		int head = pad + g.getFontMetrics(big).getAscent() + line * 4 + line / 2;
		int foot = line * 4 + (share != null ? line : 0) + pad + tooth;
		int maxH = h * 92 / 100;
		int rows = Math.max(1, Math.min(drops.size(), (maxH - head - foot - line) / rowStep));
		boolean other = drops.size() > rows || volume > listed;
		int natural = head + rows * rowStep + (other ? line : 0) + foot;
		int rh = Math.min(maxH, Math.max(u * 6 / 10, natural));
		int rw = Math.min(w * 3 / 4, (int) (u * 0.78));
		int x = (w - rw) / 2;
		int y = (h - rh) / 2;
		g.setColor(new Color(0, 0, 0, 80));
		g.fillRect(x + u / 100, y + u / 80, rw, rh);
		java.awt.geom.Path2D paper = new java.awt.geom.Path2D.Double();
		paper.moveTo(x, y);
		paper.lineTo(x + rw, y);
		paper.lineTo(x + rw, y + rh - tooth);
		for (int tx = x + rw; tx > x; tx -= tooth * 2)
		{
			paper.lineTo(Math.max(x, tx - tooth), y + rh);
			paper.lineTo(Math.max(x, tx - tooth * 2), y + rh - tooth);
		}
		paper.closePath();
		g.setColor(PAPER);
		g.fill(paper);

		int cx = w / 2;
		// A short receipt keeps its minimum size; its text sits in the middle of the paper.
		int ty = y + pad + g.getFontMetrics(big).getAscent() + Math.max(0, (rh - natural) / 2);
		Captions.centered(g, "GRAND EXCHANGE", cx, ty, big, THERMAL, rw - pad * 2);
		ty += line;
		Captions.centered(g, "Varrock · Est. 2007", cx, ty, mono, THERMAL, rw - pad * 2);
		ty += line;
		Captions.centered(g, r.period.describe(), cx, ty, mono, THERMAL, rw - pad * 2);
		ty += line;
		Captions.centered(g, "Customer: " + tok.get("player"), cx, ty, mono, THERMAL, rw - pad * 2);
		ty += line / 2;
		dashes(g, mono, x + pad, ty, rw - pad * 2);
		ty += line;

		int iconSize = line;
		int shown = Math.min(rows, drops.size());
		long shownValue = 0;
		for (int i = 0; i < shown; i++)
		{
			ReceiptLine d = drops.get(i);
			shownValue += d.value;
			int tx = x + pad;
			BufferedImage icon = art == null || d.itemId <= 0 ? null : art.item(d.itemId);
			if (icon != null)
			{
				Sprites.drawCentered(g, Sprites.upscale(Sprites.trim(icon), iconSize), tx + iconSize / 2.0, ty - line / 3.0, 1, 0);
			}
			tx += iconSize + u / 100;
			leader(g, mono, d.name, d.amount, tx, x + rw - pad, ty);
			ty += rowStep;
		}
		if (drops.isEmpty())
		{
			Captions.centered(g, "** NO ITEMS **", cx, ty, mono, THERMAL, rw - pad * 2);
			ty += line;
		}
		else if (other && volume > shownValue)
		{
			String more = drops.size() > shown ? (drops.size() - shown) + (ge ? " more trades" : " more items") : ge ? "Other trades" : "Other loot";
			leader(g, mono, more, Recap.gp(Math.max(0, volume - shownValue)), x + pad + iconSize + u / 100, x + rw - pad, ty);
			ty += line;
		}
		ty -= line / 2;
		dashes(g, mono, x + pad, ty, rw - pad * 2);
		ty += line;
		if (ge)
		{
			long net = r.total.geNet();
			leader(g, monoBold, net >= 0 ? "NET PROFIT" : "NET SPENT", (net >= 0 ? "+" : "-") + Recap.gp(Math.abs(net)), x + pad, x + rw - pad, ty);
			ty += line;
			leader(g, mono, "Bought", Recap.gp(r.total.geBought), x + pad, x + rw - pad, ty);
			ty += line;
			leader(g, mono, "Sold", Recap.gp(r.total.geSold), x + pad, x + rw - pad, ty);
		}
		else
		{
			leader(g, monoBold, "TOTAL", tok.get("loot"), x + pad, x + rw - pad, ty);
			ty += line;
			leader(g, mono, "Kills", tok.get("kills"), x + pad, x + rw - pad, ty);
			ty += line;
			leader(g, mono, "Time on shift", tok.get("hours"), x + pad, x + rw - pad, ty);
		}
		ty += line * 3 / 2;
		Captions.centered(g, share != null ? share : "Thank you for trading!", cx, ty, monoBold, THERMAL, rw - pad * 2);
	}

	private static final class ReceiptLine
	{
		final int itemId;
		final String name;
		final String amount;
		final long value;

		ReceiptLine(int itemId, String name, String amount, long value)
		{
			this.itemId = itemId;
			this.name = name;
			this.amount = amount;
			this.value = value;
		}
	}

	private static void dashes(Graphics2D g, Font font, int x, int y, int width)
	{
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		StringBuilder sb = new StringBuilder();
		while (fm.stringWidth(sb.toString() + "-") <= width)
		{
			sb.append('-');
		}
		g.setColor(THERMAL);
		g.drawString(sb.toString(), x, y);
	}

	/** {@code name ...... value} across the receipt, cutting the name short when there is no room. */
	private static void leader(Graphics2D g, Font font, String name, String value, int x, int right, int y)
	{
		g.setFont(font);
		g.setColor(THERMAL);
		FontMetrics fm = g.getFontMetrics();
		int vw = fm.stringWidth(value);
		int room = right - x - vw - fm.stringWidth(" ..");
		String n = name;
		for (int cut = name.length() - 1; cut > 1 && fm.stringWidth(n) > room; cut--)
		{
			n = name.substring(0, cut).trim() + "…";
		}
		StringBuilder dots = new StringBuilder(" ");
		while (fm.stringWidth(n + dots + ". " + value) <= right - x)
		{
			dots.append('.');
		}
		g.drawString(n + dots + " ", x, y);
		g.drawString(value, right - vw, y);
	}

	/** The most important highlight that has footage. */
	static Moment topMoment(Recap r)
	{
		Moment best = null;
		for (Moment m : r.highlights)
		{
			if (m.clip != null && (best == null || m.importance > best.importance))
			{
				best = m;
			}
		}
		return best;
	}

	/** The clip frame nearest the moment, or null if the footage is gone. */
	static BufferedImage still(Composer.Media media, Moment moment)
	{
		List<ClipFile.Frame> frames = media.clip(moment.clip);
		ClipFile.Frame best = null;
		for (ClipFile.Frame f : frames)
		{
			if (best == null || Math.abs(f.time - moment.time) < Math.abs(best.time - moment.time))
			{
				best = f;
			}
		}
		if (best == null)
		{
			return null;
		}
		try
		{
			return best.image();
		}
		catch (IOException e)
		{
			log.debug("Unreadable clip frame in {}", moment.clip, e);
			return null;
		}
	}
}

package com.gielinorwrapped;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.imageio.ImageIO;
import net.runelite.client.util.Filepath;

/**
 * Screenshots the player sets up in game for their recaps. Stored as {@code shots/shot-<time>-<role>.jpg};
 * the role lives in the name, so changing it is a rename. All methods do file I/O; keep them off the client thread.
 */
final class Shots
{
	static final int MAX_GALLERY = 8;
	private static final String PREFIX = "shot-";
	private static final String EXT = ".jpg";
	private static final float QUALITY = 0.92f;

	enum Role
	{
		COVER("Cover"),
		OUTRO("Outro"),
		GALLERY("Gallery");

		final String label;

		Role(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	static final class Shot
	{
		final long account;
		final Filepath file;
		final long time;
		final Role role;

		Shot(long account, Filepath file, long time, Role role)
		{
			this.account = account;
			this.file = file;
			this.time = time;
			this.role = role;
		}

		BufferedImage read() throws IOException
		{
			try (InputStream in = file.openInputStream())
			{
				return ImageIO.read(in);
			}
		}
	}

	/** The shots a recap uses. */
	static final class Pick
	{
		Shot cover;
		Shot outro;
		final List<Shot> gallery = new ArrayList<>();

		/** The cover, else the newest gallery shot. */
		Shot backdrop()
		{
			return cover != null ? cover : gallery.isEmpty() ? null : gallery.get(gallery.size() - 1);
		}
	}

	private final StatsStore store;

	Shots(StatsStore store)
	{
		this.store = store;
	}

	private Filepath dir(long account)
	{
		return store.accountDir(account).join("shots");
	}

	Shot save(long account, long time, Role role, BufferedImage image) throws IOException
	{
		Filepath dir = dir(account);
		dir.createDirectories();
		Filepath file = dir.join(name(time, role));
		Filepath tmp = dir.join(file.getFileName() + ".tmp");
		try (OutputStream out = tmp.openOutputStream())
		{
			out.write(ClipFile.encode(image, QUALITY));
		}
		tmp.moveTo(file, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
		return new Shot(account, file, time, role);
	}

	/** Every shot, newest first. */
	List<Shot> list(long account) throws IOException
	{
		Filepath dir = dir(account);
		if (!dir.isDirectory())
		{
			return new ArrayList<>();
		}
		try (Stream<Filepath> files = dir.walk(1))
		{
			List<Shot> out = new ArrayList<>();
			for (Filepath f : files.collect(Collectors.toList()))
			{
				Shot s = parse(account, f);
				if (s != null)
				{
					out.add(s);
				}
			}
			out.sort(Comparator.comparingLong((Shot s) -> s.time).reversed());
			return out;
		}
	}

	Shot setRole(Shot shot, Role role) throws IOException
	{
		if (shot.role == role)
		{
			return shot;
		}
		Filepath target = dir(shot.account).join(name(shot.time, role));
		shot.file.moveTo(target);
		return new Shot(shot.account, target, shot.time, role);
	}

	void delete(Shot shot) throws IOException
	{
		shot.file.deleteIfExists();
	}

	/**
	 * Shots taken from {@code from} up to {@code until} (epoch ms): the newest cover and outro,
	 * and up to {@link #MAX_GALLERY} gallery shots, oldest first.
	 */
	static Pick pick(List<Shot> shots, long from, long until)
	{
		Pick p = new Pick();
		List<Shot> sorted = new ArrayList<>(shots);
		sorted.sort(Comparator.comparingLong(s -> s.time));
		for (Shot s : sorted)
		{
			if (s.time < from || s.time > until)
			{
				continue;
			}
			switch (s.role)
			{
				case COVER:
					p.cover = s;
					break;
				case OUTRO:
					p.outro = s;
					break;
				default:
					p.gallery.add(s);
			}
		}
		int n = p.gallery.size();
		if (n > MAX_GALLERY)
		{
			// Spread over the whole period rather than keeping only one end of it.
			List<Shot> kept = new ArrayList<>();
			for (int i = 0; i < MAX_GALLERY; i++)
			{
				kept.add(p.gallery.get((int) Math.round(i * (n - 1) / (double) (MAX_GALLERY - 1))));
			}
			p.gallery.clear();
			p.gallery.addAll(kept);
		}
		return p;
	}

	static String name(long time, Role role)
	{
		return PREFIX + time + "-" + role.name().toLowerCase(Locale.ROOT) + EXT;
	}

	static Shot parse(long account, Filepath f)
	{
		String n = f.getFileName();
		if (n == null || !n.startsWith(PREFIX) || !n.endsWith(EXT))
		{
			return null;
		}
		String[] parts = n.substring(PREFIX.length(), n.length() - EXT.length()).split("-");
		if (parts.length != 2)
		{
			return null;
		}
		try
		{
			return new Shot(account, f, Long.parseLong(parts[0]), Role.valueOf(parts[1].toUpperCase(Locale.ROOT)));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}
}

package com.gielinorwrapped;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RadialGradientPaint;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * A YouTube-thumbnail style splash: a screenshot backdrop, a fan of big glowing item sprites and a loud outlined
 * headline. Drawn as the splash share card and, animated, as the video's opening scene.
 */
final class Splash
{
	static final int MAX_ITEMS = 5;

	private final String label;
	private final List<String> headline;
	private final String player;
	private final String footer;
	private final BufferedImage backdrop;
	private final List<BufferedImage> items;
	private final BufferedImage skill;
	private final String skillText;

	private int preparedFor = -1;
	private List<BufferedImage> bigItems;
	private BufferedImage bigSkill;

	Splash(String label, String headline, String player, String footer, BufferedImage backdrop, List<BufferedImage> items, BufferedImage skill, String skillText)
	{
		this.label = label;
		this.headline = lines(headline == null ? "" : headline.toUpperCase(Locale.ROOT));
		this.player = player;
		this.footer = footer;
		this.backdrop = backdrop;
		this.items = items;
		this.skill = skill;
		this.skillText = skillText;
	}

	/** Builds the splash for a recap; sprites and the backdrop come from {@code media}, which may be null. */
	static Splash of(Recap r, Composer.Media media, Map<String, String> tok, GielinorWrappedConfig config)
	{
		return of(r, media, tok, config, null);
	}

	/** As above with the player's own headline, or the configured one when {@code headline} is null. */
	static Splash of(Recap r, Composer.Media media, Map<String, String> tok, GielinorWrappedConfig config, String headline)
	{
		List<BufferedImage> sprites = new ArrayList<>();
		BufferedImage skill = null;
		BufferedImage backdrop = null;
		if (media != null)
		{
			for (int id : featuredItems(r, MAX_ITEMS))
			{
				BufferedImage img = media.item(id);
				if (img != null)
				{
					sprites.add(img);
				}
			}
			if (!r.skills.isEmpty())
			{
				skill = media.skill(r.skills.get(0).name);
			}
			if (config.shotsAsBackdrop())
			{
				backdrop = Composer.read(media.shots().backdrop());
			}
			if (backdrop == null)
			{
				Moment top = ShareCard.topMoment(r);
				backdrop = top == null ? null : ShareCard.still(media, top);
			}
		}
		String skillText = r.skills.isEmpty() ? null : "+" + tok.get("topSkillXp") + " " + tok.get("topSkill");
		List<String> foot = new ArrayList<>();
		foot.add(tok.get("hours") + " played");
		if (r.total.lootValue > 0)
		{
			foot.add(tok.get("loot") + " loot");
		}
		if (r.total.totalLevels() > 0)
		{
			foot.add(tok.get("levels") + (r.total.totalLevels() == 1 ? " level" : " levels"));
		}
		return new Splash(r.period.describe(), headline != null ? headline : Recap.fill(config.splashText(), tok), tok.get("player"), String.join(" · ", foot),
			backdrop, sprites, skill, skillText);
	}

	/** Items worth showing off, best first: pets, new log slots, big drops, then the most valuable loot. */
	static List<Integer> featuredItems(Recap r, int max)
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (Moment.Type type : new Moment.Type[]{Moment.Type.PET, Moment.Type.COLLECTION_LOG, Moment.Type.DROP})
		{
			List<Moment> ms = new ArrayList<>();
			for (Moment m : r.highlights)
			{
				if (m.type == type && m.itemId > 0)
				{
					ms.add(m);
				}
			}
			ms.sort((a, b) -> type == Moment.Type.DROP ? Long.compare(b.value, a.value) : Integer.compare(b.importance, a.importance));
			for (Moment m : ms)
			{
				ids.add(m.itemId);
			}
		}
		for (DayRecord.Drop d : r.drops)
		{
			if (d.itemId > 0)
			{
				ids.add(d.itemId);
			}
		}
		List<Integer> out = new ArrayList<>(ids);
		return out.size() > max ? out.subList(0, max) : out;
	}

	boolean hasArt()
	{
		return backdrop != null || !items.isEmpty();
	}

	/** Draws the splash {@code t} seconds in; anything past two seconds is the settled still. */
	void draw(Graphics2D g, Theme th, int w, int h, double t)
	{
		int u = Math.min(w, h);
		boolean wide = w > h * 1.25;
		prepare(u, th);

		// Backdrop: the player's shot with a slow push-in, darkened so the text pops.
		if (backdrop != null)
		{
			Scenes.drawCover(g, backdrop, 0, 0, w, h, 1.04 + 0.04 * Captions.clamp(t / 4));
			g.setColor(new Color(0, 0, 0, 70));
			g.fillRect(0, 0, w, h);
		}
		else
		{
			th.background(g, w, h, t);
		}
		float fx = wide ? w * 0.70f : w * 0.5f;
		float fy = wide ? h * 0.50f : h * 0.53f;
		rays(g, th, fx, fy, Math.max(w, h), t, backdrop != null ? 0.10 : 0.16);
		g.setPaint(new RadialGradientPaint(w / 2f, h / 2f, Math.max(w, h) * 0.75f, new float[]{0.45f, 1f},
			new Color[]{new Color(0, 0, 0, 0), new Color(0, 0, 0, 170)}));
		g.fillRect(0, 0, w, h);
		g.setPaint(new GradientPaint(0, h * 0.72f, new Color(0, 0, 0, 0), 0, h, new Color(0, 0, 0, 190)));
		g.fillRect(0, (int) (h * 0.72f), w, h - (int) (h * 0.72f));

		fan(g, fx, fy, wide ? w * 0.40f : w * 0.78f, u, t);

		// Period pill, top left.
		double lp = Captions.ease(Captions.clamp(t / 0.35));
		java.awt.Font lf = th.bold(u * 0.034f);
		g.setFont(lf);
		java.awt.FontMetrics lm = g.getFontMetrics();
		String pill = label.toUpperCase(Locale.ROOT);
		int pad = u / 50;
		int pw = lm.stringWidth(pill) + pad * 2;
		int ph = lm.getHeight() + pad / 2;
		int px = (int) (u * 0.045 - (1 - lp) * (pw + u * 0.05));
		int py = (int) (u * 0.045);
		g.setColor(th.accent);
		g.fillRoundRect(px, py, pw, ph, ph, ph);
		g.setColor(Scenes.isBright(th.accent) ? new Color(0x111111) : Color.WHITE);
		g.drawString(pill, px + pad, py + pad / 4 + lm.getAscent());

		// Headline slams in: big, outlined, tilted.
		double hp = Captions.clamp((t - 0.15) / 0.35);
		if (hp > 0)
		{
			// Kept small and high, in the upper left, so it doesn't cover the player in the middle of the shot.
			float cx = wide ? w * 0.25f : w * 0.5f;
			float size = u * (headline.size() > 1 ? 0.09f : 0.105f);
			float top = wide ? h * 0.25f : h * 0.13f;
			double scale = 1 + 0.6 * Math.pow(1 - hp, 3);
			Composite old = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) Captions.clamp(hp * 2)));
			for (int i = 0; i < headline.size(); i++)
			{
				Color fill = i == headline.size() - 1 ? th.accent : Color.WHITE;
				Sprites.outlined(g, headline.get(i), cx, top + i * size * 1.0, th.bold((float) (size * scale)), fill, -0.05, (int) (wide ? w * 0.44 : w * 0.85));
			}
			if (player != null && !player.isEmpty())
			{
				Sprites.outlined(g, player, cx, top + headline.size() * size * 1.0 - size * 0.25 + u * 0.035, th.bold(u * 0.038f), Color.WHITE, -0.05, (int) (wide ? w * 0.42 : w * 0.75));
			}
			g.setComposite(old);
		}

		// Top skill badge and the stats line along the bottom.
		double sp = Captions.ease(Captions.clamp((t - 0.9) / 0.4));
		if (sp > 0)
		{
			Composite old = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) sp));
			int base = (int) (h - u * 0.07);
			if (skillText != null)
			{
				float sx = wide ? w * 0.25f : w * 0.5f;
				int sy = wide ? (int) (h * 0.68) : (int) (h * 0.80);
				int iconW = 0;
				if (bigSkill != null)
				{
					iconW = bigSkill.getWidth();
					java.awt.FontMetrics fm = g.getFontMetrics(th.bold(u * 0.055f));
					int total = iconW + u / 60 + Math.min(fm.stringWidth(skillText), (int) (wide ? w * 0.46 : w * 0.8));
					float left = sx - total / 2f;
					Sprites.drawCentered(g, bigSkill, left + iconW / 2.0, sy - fm.getAscent() * 0.35, 1, 0);
					Sprites.outlined(g, skillText, left + iconW + u / 60f + (total - iconW - u / 60f) / 2, sy, th.bold(u * 0.055f), Color.WHITE, 0, (int) (wide ? w * 0.46 : w * 0.8));
				}
				else
				{
					Sprites.outlined(g, skillText, sx, sy, th.bold(u * 0.055f), Color.WHITE, 0, (int) (wide ? w * 0.5 : w * 0.85));
				}
			}
			Sprites.outlined(g, footer, w / 2.0, base, th.bold(u * 0.042f), th.accent, 0, (int) (w * 0.9));
			g.setComposite(old);
		}
	}

	private void prepare(int u, Theme th)
	{
		if (preparedFor == u)
		{
			return;
		}
		preparedFor = u;
		bigItems = new ArrayList<>();
		int size = (int) (u * 0.34);
		for (BufferedImage img : items)
		{
			BufferedImage big = Sprites.splash(img, size, th.accent);
			if (big != null)
			{
				bigItems.add(big);
			}
		}
		bigSkill = skill == null ? null : Sprites.splash(skill, (int) (u * 0.085), new Color(0, 0, 0, 200));
	}

	/** The best item in the middle, the rest alternating out to the sides, each popping in. */
	private void fan(Graphics2D g, float cx, float cy, float spread, int u, double t)
	{
		int n = bigItems.size();
		if (n == 0)
		{
			return;
		}
		double step = n == 1 ? 0 : Math.min(spread / (n - 1), u * 0.26);
		// Slot k holds item order[k]; slot offsets run -2..2 around the middle.
		int[] slotOf = new int[n];
		for (int i = 0; i < n; i++)
		{
			int k = (i + 1) / 2;
			slotOf[i] = i == 0 ? 0 : (i % 2 == 1 ? -k : k);
		}
		double shift = n % 2 == 0 ? 0.5 : 0;
		// Outer items first so the best one sits on top.
		for (int pass = n - 1; pass >= 0; pass--)
		{
			int i = pass;
			double off = slotOf[i] + (n % 2 == 0 ? shift : 0);
			double appear = 0.35 + i * 0.12;
			double p = Captions.clamp((t - appear) / 0.45);
			if (p <= 0)
			{
				continue;
			}
			double size = 1 - 0.16 * Math.min(2, Math.abs(off));
			double bob = Math.sin(t * 1.6 + i) * u * 0.006;
			double x = cx + off * step;
			double y = cy + off * off * u * 0.025 + bob;
			Sprites.drawCentered(g, bigItems.get(i), x, y, size * backOut(p), off * 0.16);
		}
	}

	private static void rays(Graphics2D g, Theme th, float cx, float cy, int r, double t, double alpha)
	{
		int n = 18;
		double turn = t * 0.08;
		Color c = Theme.alpha(th.accent, alpha);
		g.setColor(c);
		for (int i = 0; i < n; i += 2)
		{
			double a0 = turn + i * Math.PI * 2 / n;
			double a1 = turn + (i + 1) * Math.PI * 2 / n;
			Polygon p = new Polygon();
			p.addPoint((int) cx, (int) cy);
			p.addPoint((int) (cx + Math.cos(a0) * r * 1.5), (int) (cy + Math.sin(a0) * r * 1.5));
			p.addPoint((int) (cx + Math.cos(a1) * r * 1.5), (int) (cy + Math.sin(a1) * r * 1.5));
			g.fillPolygon(p);
		}
	}

	/** Overshoots a little before settling, like a sticker slapped on. */
	static double backOut(double p)
	{
		double c1 = 1.70158;
		double c3 = c1 + 1;
		double x = p - 1;
		return 1 + c3 * x * x * x + c1 * x * x;
	}

	/** Splits long headlines into two lines at the space nearest the middle. */
	static List<String> lines(String text)
	{
		List<String> out = new ArrayList<>();
		String s = text.trim();
		if (s.length() <= 14 || s.indexOf(' ') < 0)
		{
			out.add(s);
			return out;
		}
		int mid = s.length() / 2;
		int best = -1;
		for (int i = 0; i < s.length(); i++)
		{
			if (s.charAt(i) == ' ' && (best < 0 || Math.abs(i - mid) < Math.abs(best - mid)))
			{
				best = i;
			}
		}
		out.add(s.substring(0, best).trim());
		out.add(s.substring(best + 1).trim());
		return out;
	}
}

package com.gielinorwrapped;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.font.TextLayout;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;

/** Game sprites blown up for video, and the thick outlined text of a YouTube thumbnail. */
final class Sprites
{
	private Sprites()
	{
	}

	/** Crops transparent borders, so icons of different shapes line up. */
	static BufferedImage trim(BufferedImage img)
	{
		int w = img.getWidth();
		int h = img.getHeight();
		int x0 = w;
		int y0 = h;
		int x1 = -1;
		int y1 = -1;
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				if ((img.getRGB(x, y) >>> 24) > 16)
				{
					x0 = Math.min(x0, x);
					y0 = Math.min(y0, y);
					x1 = Math.max(x1, x);
					y1 = Math.max(y1, y);
				}
			}
		}
		if (x1 < 0)
		{
			return null;
		}
		return copy(img, x0, y0, x1 - x0 + 1, y1 - y0 + 1);
	}

	private static BufferedImage copy(BufferedImage img, int x, int y, int w, int h)
	{
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.drawImage(img, -x, -y, null);
		g.dispose();
		return out;
	}

	/** Scales the sprite to fit a {@code size} square with hard pixel edges, by a whole factor where that fits. */
	static BufferedImage upscale(BufferedImage img, int size)
	{
		double fit = size / (double) Math.max(img.getWidth(), img.getHeight());
		double scale = fit >= 1 ? Math.floor(fit) : fit;
		int w = Math.max(1, (int) Math.round(img.getWidth() * scale));
		int h = Math.max(1, (int) Math.round(img.getHeight() * scale));
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, fit >= 1 ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR : RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(img, 0, 0, w, h, null);
		g.dispose();
		return out;
	}

	/**
	 * The sprite with a soft coloured halo around its outline, {@code radius} pixels wide.
	 * The result is larger than the sprite by the radius on each side.
	 */
	static BufferedImage glow(BufferedImage img, Color color, int radius)
	{
		return halo(img, color, radius, false);
	}

	/** Like {@link #glow} but a solid border, like the white edge of a die-cut sticker. */
	static BufferedImage outline(BufferedImage img, Color color, int radius)
	{
		return halo(img, color, radius, true);
	}

	private static BufferedImage halo(BufferedImage img, Color color, int radius, boolean solid)
	{
		int w = img.getWidth();
		int h = img.getHeight();
		int ow = w + radius * 2;
		int oh = h + radius * 2;
		// Distance to the nearest solid pixel, by two passes of a chamfer transform.
		int far = radius * 3 + 3;
		int[] d = new int[ow * oh];
		for (int y = 0; y < oh; y++)
		{
			for (int x = 0; x < ow; x++)
			{
				int sx = x - radius;
				int sy = y - radius;
				boolean inside = sx >= 0 && sy >= 0 && sx < w && sy < h && (img.getRGB(sx, sy) >>> 24) > 96;
				d[y * ow + x] = inside ? 0 : far;
			}
		}
		for (int y = 0; y < oh; y++)
		{
			for (int x = 0; x < ow; x++)
			{
				int i = y * ow + x;
				if (x > 0)
				{
					d[i] = Math.min(d[i], d[i - 1] + 3);
				}
				if (y > 0)
				{
					d[i] = Math.min(d[i], d[i - ow] + 3);
					if (x > 0)
					{
						d[i] = Math.min(d[i], d[i - ow - 1] + 4);
					}
					if (x < ow - 1)
					{
						d[i] = Math.min(d[i], d[i - ow + 1] + 4);
					}
				}
			}
		}
		for (int y = oh - 1; y >= 0; y--)
		{
			for (int x = ow - 1; x >= 0; x--)
			{
				int i = y * ow + x;
				if (x < ow - 1)
				{
					d[i] = Math.min(d[i], d[i + 1] + 3);
				}
				if (y < oh - 1)
				{
					d[i] = Math.min(d[i], d[i + ow] + 3);
					if (x < ow - 1)
					{
						d[i] = Math.min(d[i], d[i + ow + 1] + 4);
					}
					if (x > 0)
					{
						d[i] = Math.min(d[i], d[i + ow - 1] + 4);
					}
				}
			}
		}
		BufferedImage out = new BufferedImage(ow, oh, BufferedImage.TYPE_INT_ARGB);
		int rgb = color.getRGB() & 0xFFFFFF;
		for (int i = 0; i < d.length; i++)
		{
			double dist = d[i] / 3.0;
			if (dist <= radius)
			{
				double a = solid ? Captions.clamp(radius + 0.5 - dist) : 1 - dist / (radius + 1);
				out.setRGB(i % ow, i / ow, (int) (solid ? a * 255 : a * a * 235) << 24 | rgb);
			}
		}
		Graphics2D g = out.createGraphics();
		g.drawImage(img, radius, radius, null);
		g.dispose();
		return out;
	}

	/** A sprite ready for a splash: trimmed, upscaled to {@code size} and glowing. Null if the sprite is empty. */
	static BufferedImage splash(BufferedImage img, int size, Color glow)
	{
		if (img == null)
		{
			return null;
		}
		BufferedImage t = trim(img);
		if (t == null)
		{
			return null;
		}
		int radius = Math.max(2, size / 14);
		return glow(upscale(t, size - radius * 2), glow, radius);
	}

	/** Draws {@code img} centred on (cx, cy), scaled and rotated by {@code angle} radians. */
	static void drawCentered(Graphics2D g, BufferedImage img, double cx, double cy, double scale, double angle)
	{
		if (img == null || scale <= 0)
		{
			return;
		}
		AffineTransform at = new AffineTransform();
		at.translate(cx, cy);
		at.rotate(angle);
		at.scale(scale, scale);
		at.translate(-img.getWidth() / 2.0, -img.getHeight() / 2.0);
		Object old = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(img, at, null);
		if (old != null)
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, old);
		}
	}

	/**
	 * Thumbnail text: filled, with a thick dark outline and a hard drop shadow, centred on {@code cx}.
	 * The font shrinks until the text fits {@code maxWidth}.
	 */
	static void outlined(Graphics2D g, String text, double cx, double baseline, Font font, Color fill, double angle, int maxWidth)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		Font f = font;
		TextLayout layout = new TextLayout(text, f, g.getFontRenderContext());
		while (layout.getAdvance() > maxWidth && f.getSize2D() > 8)
		{
			f = f.deriveFont(f.getSize2D() * 0.92f);
			layout = new TextLayout(text, f, g.getFontRenderContext());
		}
		float stroke = f.getSize2D() * 0.14f;
		AffineTransform at = new AffineTransform();
		at.translate(cx, baseline);
		at.rotate(angle);
		at.translate(-layout.getAdvance() / 2, 0);
		Shape shape = layout.getOutline(at);
		Shape shadow = AffineTransform.getTranslateInstance(stroke * 0.6, stroke * 0.8).createTransformedShape(shape);
		BasicStroke round = new BasicStroke(stroke, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
		g.setStroke(round);
		g.setColor(new Color(0, 0, 0, 140));
		g.draw(shadow);
		g.fill(shadow);
		g.setColor(new Color(0x111111));
		g.draw(shape);
		g.setColor(fill);
		g.fill(shape);
		g.setStroke(new BasicStroke(1));
	}
}

package com.gielinorwrapped;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.StandardCopyOption;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Day records on disk: one JSON file per account per day under {@code accounts/<hash>/days}. All methods
 * do file I/O and must not be called on the client thread.
 */
@Slf4j
class StatsStore
{
	private final Gson gson;
	private final Filepath root;

	StatsStore(Gson gson, Filepath root)
	{
		this.gson = gson;
		this.root = root;
	}

	Filepath root()
	{
		return root;
	}

	Filepath accountDir(long accountHash)
	{
		return root.join("accounts", Long.toUnsignedString(accountHash));
	}

	private Filepath daysDir(long accountHash)
	{
		return accountDir(accountHash).join("days");
	}

	DayRecord readDay(long accountHash, LocalDate date)
	{
		Filepath file = daysDir(accountHash).join(date + ".json");
		if (!file.exists())
		{
			return null;
		}
		try (Reader reader = file.openReader())
		{
			DayRecord day = gson.fromJson(reader, DayRecord.class);
			if (day == null)
			{
				return null;
			}
			day.date = date.toString();
			return day.normalize();
		}
		catch (IOException | JsonParseException e)
		{
			log.warn("Unable to read {}", file, e);
			return null;
		}
	}

	/** Writes the day through a temporary file so a crash mid-write never leaves a broken record. */
	void writeDay(long accountHash, String date, String json) throws IOException
	{
		Filepath dir = daysDir(accountHash);
		dir.createDirectories();
		Filepath tmp = dir.join(date + ".json.tmp");
		tmp.write(json);
		tmp.moveTo(dir.join(date + ".json"), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
	}

	/** Dates with a stored record, oldest first. */
	List<LocalDate> listDays(long accountHash)
	{
		Filepath dir = daysDir(accountHash);
		if (!dir.exists())
		{
			return new ArrayList<>();
		}
		try (Stream<Filepath> files = dir.walk(1))
		{
			List<LocalDate> dates = new ArrayList<>();
			for (String name : files.map(Filepath::getFileName).collect(Collectors.toList()))
			{
				if (name != null && name.endsWith(".json"))
				{
					try
					{
						dates.add(LocalDate.parse(name.substring(0, name.length() - 5)));
					}
					catch (DateTimeParseException e)
					{
						// Not a day file.
					}
				}
			}
			dates.sort(null);
			return dates;
		}
		catch (IOException e)
		{
			log.warn("Unable to list {}", dir, e);
			return new ArrayList<>();
		}
	}

	/** Stored days from {@code from} to {@code to} inclusive, oldest first. */
	List<DayRecord> readRange(long accountHash, LocalDate from, LocalDate to)
	{
		List<DayRecord> days = new ArrayList<>();
		for (LocalDate d : listDays(accountHash))
		{
			if (!d.isBefore(from) && !d.isAfter(to))
			{
				DayRecord day = readDay(accountHash, d);
				if (day != null)
				{
					days.add(day);
				}
			}
		}
		return days;
	}

	Gson gson()
	{
		return gson;
	}
}

package com.gielinorwrapped;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.metadata.IIOMetadata;
