import javax.swing.event.DocumentListener;

/**
 * The sticker board: the player picks stickers from their cutouts and own images and places them on the
 * recap's scenes by hand. Edits a copy of the board; Save hands it back.
 */
final class StickerBoardDialog extends JDialog
{
	private static final int PREVIEW_W = 640;
	private static final int THUMB = 64;

	private final StickerBoard board;
	private final Map<String, Sticker> byKey = new HashMap<>();
	private final List<Sticker> stickers = new ArrayList<>();
	private final Consumer<Sticker> deleteCutout;
	private final Scenes.Look look;
	private final Dimension frame;
	/** Made in the constructor, once {@link #frame} is known. */
	private final Preview preview;
	private final JPanel palette = new JPanel(new GridLayout(0, 4, 4, 4));
	private final JTextField search = new JTextField();
	private final JComboBox<String> scene = new JComboBox<>();
	private String sceneName = StickerBoard.EVERY;

	StickerBoardDialog(Window owner, GielinorWrappedConfig config, List<Sticker> all, StickerBoard saved,
		Consumer<StickerBoard> save, Consumer<Sticker> deleteCutout)
	{
		super(owner, "Sticker board", ModalityType.APPLICATION_MODAL);
		this.board = saved.copy();
		this.deleteCutout = deleteCutout;
		this.look = Scenes.Look.of(config);
		this.frame = Composer.size(config);
		this.preview = new Preview();
		for (Sticker s : all)
		{
			String key = StickerBoard.key(s);
			if (key != null && byKey.putIfAbsent(key, s) == null)
			{
				stickers.add(s);
			}
		}

		for (String[] s : StickerBoard.SCENES)
		{
			scene.addItem(s[1]);
		}
		scene.addActionListener(e ->
		{
			sceneName = StickerBoard.SCENES[Math.max(0, scene.getSelectedIndex())][0];
			preview.selected = null;
			preview.repaint();
		});
		JCheckBox auto = new JCheckBox("Auto stickers on scenes I leave empty", board.autoFill);
		auto.addActionListener(e -> board.autoFill = auto.isSelected());
		JButton clear = new JButton("Clear scene");
		clear.addActionListener(e ->
		{
			board.spots.removeIf(s -> sceneName.equals(s.scene));
			preview.selected = null;
			preview.repaint();
		});
		JPanel top = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
		top.add(new JLabel("Scene"));
		top.add(scene);
		top.add(clear);
		top.add(auto);

		JLabel hint = new JLabel("<html>Click a sticker to add it. Drag to move, scroll to resize, Shift+scroll to turn, "
			+ "right-click or Delete to remove. Placed stickers replace the automatic ones on that scene.</html>");
		hint.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

		JPanel centre = new JPanel(new BorderLayout());
		centre.add(preview, BorderLayout.CENTER);
		centre.add(hint, BorderLayout.SOUTH);

		search.setToolTipText("Search stickers");
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				fillPalette();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				fillPalette();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				fillPalette();
			}
		});
		JPanel paletteWrap = new JPanel(new BorderLayout());
		paletteWrap.add(palette, BorderLayout.NORTH);
		JScrollPane scroll = new JScrollPane(paletteWrap, ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		JPanel side = new JPanel(new BorderLayout(0, 4));
		side.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 6));
		side.add(search, BorderLayout.NORTH);
		side.add(scroll, BorderLayout.CENTER);
		side.setPreferredSize(new Dimension(4 * (THUMB + 12) + 24, 0));
		fillPalette();

		JButton ok = new JButton("Save");
		ok.addActionListener(e ->
		{
			save.accept(board.clean());
			dispose();
		});
		JButton cancel = new JButton("Cancel");
		cancel.addActionListener(e -> dispose());
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 4));
		buttons.add(cancel);
		buttons.add(ok);

		JPanel root = new JPanel(new BorderLayout(6, 0));
		root.add(top, BorderLayout.NORTH);
		root.add(centre, BorderLayout.CENTER);
		root.add(side, BorderLayout.EAST);
		root.add(buttons, BorderLayout.SOUTH);
		setContentPane(root);
		getRootPane().setDefaultButton(ok);
		pack();
		setLocationRelativeTo(owner);
	}

	private void fillPalette()
	{
		palette.removeAll();
		String q = search.getText().trim().toLowerCase(Locale.ROOT);
		for (Sticker s : stickers)
		{
			String name = displayName(s);
			if (!q.isEmpty() && !name.toLowerCase(Locale.ROOT).contains(q))
			{
				continue;
			}
			palette.add(tile(s, name));
		}
		if (palette.getComponentCount() == 0)
		{
			palette.add(new JLabel(stickers.isEmpty() ? "<html>No stickers yet. Fight something, or add your own.</html>" : "No match"));
		}
		palette.revalidate();
		palette.repaint();
	}

	private static String displayName(Sticker s)
	{
		String n = s.kind == Sticker.Kind.MINE && s.name.lastIndexOf('.') > 0 ? s.name.substring(0, s.name.lastIndexOf('.')) : s.name;
		n = n.replace('_', ' ');
		return n.isEmpty() ? n : Character.toUpperCase(n.charAt(0)) + n.substring(1);
	}

	private JComponent tile(Sticker s, String name)
	{
		JButton b = new JButton(name.length() > 12 ? name.substring(0, 11) + "…" : name, new ImageIcon(thumb(s)));
		b.setVerticalTextPosition(SwingConstants.BOTTOM);
		b.setHorizontalTextPosition(SwingConstants.CENTER);
		b.setToolTipText(name);
		b.setMargin(new java.awt.Insets(2, 2, 2, 2));
		b.setFont(b.getFont().deriveFont(10f));
		b.addActionListener(e -> add(s));
		if (s.kind == Sticker.Kind.NPC && deleteCutout != null)
		{
			JPopupMenu menu = new JPopupMenu();
			JMenuItem del = new JMenuItem("Delete cutout");
			del.addActionListener(e ->
			{
				if (JOptionPane.showConfirmDialog(this, "Delete the " + name + " cutout? Fighting it again takes a new one.",
					"Delete cutout", JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
				{
					deleteCutout.accept(s);
					stickers.remove(s);
					String key = StickerBoard.key(s);
					byKey.remove(key);
					board.spots.removeIf(sp -> key.equals(sp.sticker));
					preview.selected = null;
					fillPalette();
					preview.repaint();
				}
			});
			menu.add(del);
			b.setComponentPopupMenu(menu);
		}
		return b;
	}

	private static BufferedImage thumb(Sticker s)
	{
		BufferedImage out = new BufferedImage(THUMB, THUMB, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		s.draw(g, THUMB / 2.0, THUMB / 2.0, THUMB - 4, 0, 0, 1);
		g.dispose();
		return out;
	}

	/** Puts a sticker in the middle of the scene being edited, a little off so repeats don't stack exactly. */
	private void add(Sticker s)
	{
		int n = board.on(sceneName).size();
		double size = Math.max(StickerBoard.MIN_SIZE, Math.min(StickerBoard.MAX_SIZE, 0.25));
		StickerBoard.Spot spot = new StickerBoard.Spot(sceneName, StickerBoard.key(s),
			Captions.clamp(0.5 + 0.04 * (n % 5)), Captions.clamp(0.5 + 0.04 * (n % 5)), size, 0);
		board.spots.add(spot);
		preview.selected = spot;
		preview.repaint();
		preview.requestFocusInWindow();
	}

	/** A scene of the board as the editor shows it, at output size. */
	static BufferedImage render(GielinorWrappedConfig config, List<Sticker> all, StickerBoard board, String sceneName)
	{
		Map<String, Sticker> byKey = new HashMap<>();
		for (Sticker s : all)
		{
			String key = StickerBoard.key(s);
			if (key != null)
			{
				byKey.putIfAbsent(key, s);
			}
		}
		Dimension frame = Composer.size(config);
		BufferedImage img = new BufferedImage(frame.width, frame.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		paintScene(g, frame.width, frame.height, Scenes.Look.of(config), board, byKey, sceneName, null);
		g.dispose();
		return img;
	}

	private static void paintScene(Graphics2D g, int w, int h, Scenes.Look look, StickerBoard board, Map<String, Sticker> byKey,
		String name, StickerBoard.Spot selected)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		look.theme.background(g, w, h, 1.0);
		MoreScenes.heading(g, look, StickerBoard.label(name), w, h, 10);
		int u = Math.min(w, h);
		List<StickerBoard.Spot> spots = new ArrayList<>(board.on(name));
		if (!StickerBoard.EVERY.equals(name))
		{
			// Every-scene stickers show faded underneath, so the player sees what else lands here.
			for (StickerBoard.Spot s : board.on(StickerBoard.EVERY))
			{
				Sticker st = byKey.get(s.sticker);
				if (st != null)
				{
					st.draw(g, s.x * w, s.y * h, s.size * u, s.angle, 0, 0.45);
				}
			}
		}
		for (StickerBoard.Spot s : spots)
		{
			Sticker st = byKey.get(s.sticker);
			if (st == null)
			{
				continue;
			}
			st.draw(g, s.x * w, s.y * h, s.size * u, s.angle, 0, 1);
			if (s == selected)
			{
				double r = s.size * u * 0.55;
				g.setColor(new Color(255, 255, 255, 170));
				g.setStroke(new java.awt.BasicStroke(1.5f, java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND, 1, new float[]{5, 4}, 0));
				g.draw(new java.awt.geom.Rectangle2D.Double(s.x * w - r, s.y * h - r, r * 2, r * 2));
			}
		}
	}

	/** The scene preview, at the output's aspect ratio. */
	private final class Preview extends JComponent
	{
		StickerBoard.Spot selected;
		private StickerBoard.Spot dragging;
		private double grabX;
		private double grabY;

		Preview()
		{
			int h = (int) Math.round(PREVIEW_W * (double) frame.height / frame.width);
			if (h > 560)
			{
				setPreferredSize(new Dimension((int) Math.round(560.0 * frame.width / frame.height), 560));
			}
			else
			{
				setPreferredSize(new Dimension(PREVIEW_W, h));
			}
			setFocusable(true);
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			MouseAdapter mouse = new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					requestFocusInWindow();
					java.awt.Rectangle r = area();
					StickerBoard.Spot hit = hit(e.getX(), e.getY(), r);
					selected = hit;
					dragging = hit;
					if (hit != null)
					{
						grabX = (e.getX() - r.x) / (double) r.width - hit.x;
						grabY = (e.getY() - r.y) / (double) r.height - hit.y;
						if (e.isPopupTrigger() || javax.swing.SwingUtilities.isRightMouseButton(e))
						{
							menu(hit, e);
							dragging = null;
						}
						else
						{
							// Bring to front.
							board.spots.remove(hit);
							board.spots.add(hit);
						}
					}
					repaint();
				}

				@Override
				public void mouseDragged(MouseEvent e)
				{
					if (dragging == null)
					{
						return;
					}
					java.awt.Rectangle r = area();
					dragging.x = Captions.clamp((e.getX() - r.x) / (double) r.width - grabX);
					dragging.y = Captions.clamp((e.getY() - r.y) / (double) r.height - grabY);
					repaint();
				}

				@Override
				public void mouseReleased(MouseEvent e)
				{
					dragging = null;
				}

				@Override
				public void mouseWheelMoved(MouseWheelEvent e)
				{
					java.awt.Rectangle r = area();
					StickerBoard.Spot s = hit(e.getX(), e.getY(), r);
					if (s == null)
					{
						s = selected;
					}
					if (s == null)
					{
						return;
					}
					selected = s;
					double steps = e.getPreciseWheelRotation();
					if (e.isShiftDown())
					{
						s.angle -= steps * Math.toRadians(5);
					}
					else
					{
						s.size = Math.max(StickerBoard.MIN_SIZE, Math.min(StickerBoard.MAX_SIZE, s.size * Math.pow(0.92, steps)));
					}
					repaint();
				}
			};
			addMouseListener(mouse);
			addMouseMotionListener(mouse);
			addMouseWheelListener(mouse);
			getInputMap(WHEN_FOCUSED).put(KeyStroke.getKeyStroke(KeyEvent.VK_DELETE, 0), "remove");
			getInputMap(WHEN_FOCUSED).put(KeyStroke.getKeyStroke(KeyEvent.VK_BACK_SPACE, 0), "remove");
			getActionMap().put("remove", new AbstractAction()
			{
				@Override
				public void actionPerformed(java.awt.event.ActionEvent e)
				{
					if (selected != null)
					{
						board.spots.remove(selected);
						selected = null;
						repaint();
					}
				}
			});
		}

		private void menu(StickerBoard.Spot s, MouseEvent e)
		{
			JPopupMenu m = new JPopupMenu();
			JMenuItem remove = new JMenuItem("Remove");
			remove.addActionListener(a ->
			{
				board.spots.remove(s);
				selected = null;
				repaint();
			});
			JMenuItem straighten = new JMenuItem("Straighten");
			straighten.addActionListener(a ->
			{
				s.angle = 0;
				repaint();
			});
			JMenuItem back = new JMenuItem("Send to back");
			back.addActionListener(a ->
			{
				board.spots.remove(s);
				board.spots.add(0, s);
				repaint();
			});
			m.add(remove);
			m.add(straighten);
			m.add(back);
			m.show(this, e.getX(), e.getY());
		}

		/** The frame's area inside the component, letterboxed to the output aspect. */
		private java.awt.Rectangle area()
		{
			int w = getWidth();
			int h = getHeight();
			double scale = Math.min(w / (double) frame.width, h / (double) frame.height);
			int fw = (int) Math.round(frame.width * scale);
			int fh = (int) Math.round(frame.height * scale);
			return new java.awt.Rectangle((w - fw) / 2, (h - fh) / 2, Math.max(1, fw), Math.max(1, fh));
		}

		/** The topmost sticker of the current scene under (x, y). */
		private StickerBoard.Spot hit(int x, int y, java.awt.Rectangle r)
		{
			int u = Math.min(r.width, r.height);
			List<StickerBoard.Spot> spots = board.on(sceneName);
			for (int i = spots.size() - 1; i >= 0; i--)
			{
				StickerBoard.Spot s = spots.get(i);
				double half = s.size * u / 2;
				if (Math.abs(x - (r.x + s.x * r.width)) <= half && Math.abs(y - (r.y + s.y * r.height)) <= half)
				{
					return s;
				}
			}
			return null;
		}

		@Override
		protected void paintComponent(Graphics g0)
		{
			Graphics2D g = (Graphics2D) g0.create();
			g.setColor(Color.BLACK);
			g.fillRect(0, 0, getWidth(), getHeight());
			java.awt.Rectangle r = area();
			// Paint at output size and scale down, so text and stickers sit exactly as in the video.
			g.translate(r.x, r.y);
			g.scale(r.width / (double) frame.width, r.height / (double) frame.height);
			g.clipRect(0, 0, frame.width, frame.height);
			paintScene(g, frame.width, frame.height, look, board, byKey, sceneName, selected);
			g.dispose();
		}
	}
}

package com.gielinorwrapped;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Font;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.Stroke;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import net.runelite.client.ui.FontManager;

/** Colours, fonts, an animated background and a finishing pass (grade, grain, border) shared by videos and share cards. */
final class Theme
{
	final GielinorWrappedConfig.ThemeName name;
	final Color top;
	final Color bottom;
	final Color panel;
	final Color text;
	final Color muted;
	final Color accent;
	final Color accent2;

	GielinorWrappedConfig.Effect effect = GielinorWrappedConfig.Effect.AUTO;
	GielinorWrappedConfig.FontChoice font = GielinorWrappedConfig.FontChoice.RUNESCAPE;
	GielinorWrappedConfig.Grade grade = GielinorWrappedConfig.Grade.NONE;
	GielinorWrappedConfig.Border border = GielinorWrappedConfig.Border.NONE;
	double vignette;
	double grain;
	boolean scanlines;

	private int[] vignetteMap;
	private int vignetteW;
	private int vignetteH;

	private Theme(GielinorWrappedConfig.ThemeName name, int top, int bottom, int panel, int text, int muted, int accent, int accent2)
	{
		this(name, new Color(top), new Color(bottom), new Color(panel, true), new Color(text), new Color(muted), new Color(accent), new Color(accent2));
	}

	private Theme(GielinorWrappedConfig.ThemeName name, Color top, Color bottom, Color panel, Color text, Color muted, Color accent, Color accent2)
	{
		this.name = name;
		this.top = top;
		this.bottom = bottom;
		this.panel = panel;
		this.text = text;
		this.muted = muted;
		this.accent = accent;
		this.accent2 = accent2;
	}

	static Theme of(GielinorWrappedConfig config)
	{
		Theme t = config.theme() == GielinorWrappedConfig.ThemeName.CUSTOM ? custom(config) : of(config.theme());
		Color accent = config.accent();
		if (config.useAccent() && accent != null)
		{
			t = new Theme(t.name, t.top, t.bottom, t.panel, t.text, t.muted, new Color(accent.getRGB() & 0xFFFFFF), t.accent2);
		}
		t.effect = config.effect();
		t.font = config.font();
		t.grade = config.grade();
		t.border = config.border();
		t.vignette = config.vignette() / 100.0;
		t.grain = config.filmGrain() / 100.0;
		t.scanlines = config.scanlines();
		return t;
	}

	private static Theme custom(GielinorWrappedConfig config)
	{
		Color top = opaque(config.customTop(), 0x1E2A3A);
		Color bottom = opaque(config.customBottom(), 0x3A1E3A);
		Color text = opaque(config.customText(), 0xFFFFFF);
		boolean light = luma(mix(top, bottom, 0.5)) > 0.6;
		Color panel = light ? new Color(255, 255, 255, 208) : alpha(mix(bottom, Color.BLACK, 0.55), 0.69);
		return new Theme(GielinorWrappedConfig.ThemeName.CUSTOM, top, bottom, panel, text, mix(text, bottom, 0.4),
			opaque(config.customAccent(), 0xFFD23F), opaque(config.customAccent2(), 0x3FD2FF));
	}

	static Theme of(GielinorWrappedConfig.ThemeName name)
	{
		switch (name)
		{
			case MIDNIGHT:
				return new Theme(name, 0x0B1026, 0x1B2550, 0xB0141A38, 0xF2F4FF, 0x98A2CC, 0x7CC4FF, 0xC69CFF);
			case NEON:
				return new Theme(name, 0x0D0221, 0x261447, 0xB0180A33, 0xFFFFFF, 0xB59ADB, 0xFF2E97, 0x2DE2E6);
			case WILDERNESS:
				return new Theme(name, 0x1A0A06, 0x3D1309, 0xB0200C08, 0xF6E7D8, 0xC09A86, 0xFF6A2B, 0xFFC247);
			case CLEAN:
				return new Theme(name, 0xFAFAFA, 0xE6E9EF, 0xD0FFFFFF, 0x1D2230, 0x6B7285, 0x3866F2, 0x18A57A);
			case RUNE:
				return new Theme(name, 0x0E1C2B, 0x1F3F5C, 0xB00F1E2E, 0xEAF4FF, 0x8FB0CC, 0x5FD3E8, 0x9AB8D6);
			case DRAGON:
				return new Theme(name, 0x120404, 0x3A0808, 0xB0180606, 0xFFECEC, 0xC79A9A, 0xE8262B, 0xF0C060);
			case BARROWS:
				return new Theme(name, 0x0E0F0E, 0x262A24, 0xB0121410, 0xE6E9DC, 0x9BA190, 0xB8C46A, 0x7E8B6A);
			case ANCIENT:
				return new Theme(name, 0x12061E, 0x2E0F46, 0xB01A0A2A, 0xF5EAFF, 0xB59CCB, 0xB45CFF, 0xFF4F7A);
			case DESERT:
				return new Theme(name, 0xF4DFB0, 0xD9A860, 0xC8FFF3D6, 0x3A2410, 0x7A5A34, 0xC0392B, 0x1F6F8B);
			case FROST:
				return new Theme(name, 0x0B1A2A, 0x2B5276, 0xB00C1C2C, 0xF4FBFF, 0xA9C6DD, 0x9FE8FF, 0x7FA8FF);
			case VAPORWAVE:
				return new Theme(name, 0x2B0F54, 0xAB1F7A, 0xB0200840, 0xFFFFFF, 0xE3B7F5, 0x01CDFE, 0xFF71CE);
			case NOIR:
				return new Theme(name, 0x0A0A0A, 0x262626, 0xB0101010, 0xF2F2F2, 0x9A9A9A, 0xFFFFFF, 0xC8102E);
			case RETRO:
				return new Theme(name, 0x3E3529, 0x5D5447, 0xC02E2820, 0xFFFF00, 0xFF981F, 0x00FF80, 0x00FFFF);
			case TOXIC:
				return new Theme(name, 0x06140A, 0x0F3A1F, 0xB0061A0C, 0xEAFFF0, 0x8FC9A0, 0x6CFF3C, 0x2DE2C8);
			default:
				return new Theme(GielinorWrappedConfig.ThemeName.GIELINOR, 0x2B2217, 0x4A3B26, 0xB01E170F, 0xFFF4DC, 0xCBB89A, 0xFFC83C, 0xFF9B3C);
		}
	}

	/** Light backgrounds want dark text and soft shadows. */
	boolean light()
	{
		return luma(mix(top, bottom, 0.5)) > 0.6;
	}

	/** Bold title font at {@code size} pixels in the chosen typeface. */
	Font bold(float size)
	{
		switch (font)
		{
			case SANS:
				return new Font(Font.SANS_SERIF, Font.BOLD, 1).deriveFont(size);
			case SERIF:
				return new Font(Font.SERIF, Font.BOLD, 1).deriveFont(size);
			case MONO:
				return new Font(Font.MONOSPACED, Font.BOLD, 1).deriveFont(size);
			default:
				return FontManager.getRunescapeBoldFont().deriveFont(size);
		}
	}

	Font regular(float size)
	{
		switch (font)
		{
			case SANS:
				return new Font(Font.SANS_SERIF, Font.PLAIN, 1).deriveFont(size);
			case SERIF:
				return new Font(Font.SERIF, Font.PLAIN, 1).deriveFont(size);
			case MONO:
				return new Font(Font.MONOSPACED, Font.PLAIN, 1).deriveFont(size);
			default:
				return FontManager.getRunescapeFont().deriveFont(size);
		}
	}

	static Color alpha(Color c, double a)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), (int) Math.round(Math.max(0, Math.min(1, a)) * c.getAlpha()));
	}

	static Color mix(Color a, Color b, double t)
	{
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	static double luma(Color c)
	{
		return (0.299 * c.getRed() + 0.587 * c.getGreen() + 0.114 * c.getBlue()) / 255;
	}

	private static Color opaque(Color c, int fallback)
	{
		return new Color(c == null ? fallback : c.getRGB() & 0xFFFFFF);
	}

	/** The effect actually drawn: the chosen one, or the theme's own for {@code AUTO}. */
	GielinorWrappedConfig.Effect effect()
	{
		if (effect != GielinorWrappedConfig.Effect.AUTO)
		{
			return effect;
		}
		switch (name)
		{
			case MIDNIGHT:
				return GielinorWrappedConfig.Effect.STARS;
			case NEON:
			case VAPORWAVE:
				return GielinorWrappedConfig.Effect.GRID;
			case WILDERNESS:
			case DRAGON:
				return GielinorWrappedConfig.Effect.EMBERS;
			case CLEAN:
				return GielinorWrappedConfig.Effect.BLOBS;
			case RUNE:
			case CUSTOM:
				return GielinorWrappedConfig.Effect.SPARKLES;
			case BARROWS:
				return GielinorWrappedConfig.Effect.FOG;
			case ANCIENT:
				return GielinorWrappedConfig.Effect.AURORA;
			case FROST:
				return GielinorWrappedConfig.Effect.SNOW;
			case NOIR:
				return GielinorWrappedConfig.Effect.RAIN;
			case TOXIC:
				return GielinorWrappedConfig.Effect.BUBBLES;
			case DESERT:
				return GielinorWrappedConfig.Effect.RAYS;
			default:
				return GielinorWrappedConfig.Effect.MOTES;
		}
	}

	/** Paints the background at {@code t} seconds; decorations drift slowly so stills and video match. */
	void background(Graphics2D g, int w, int h, double t)
	{
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fillRect(0, 0, w, h);
		Composite old = g.getComposite();
		Stroke oldStroke = g.getStroke();
		int unit = Math.min(w, h);
		switch (effect())
		{
			case STARS:
				// Twinkling stars at fixed pseudo-random spots.
				for (int i = 0; i < 90; i++)
				{
					double x = hash(i, 1) * w;
					double y = hash(i, 2) * h;
					double tw = 0.5 + 0.5 * Math.sin(t * (1 + hash(i, 3) * 2) + i);
					double r = 1 + hash(i, 4) * unit / 400.0;
					g.setColor(alpha(text, 0.25 + 0.6 * tw));
					g.fill(new Ellipse2D.Double(x - r, y - r, r * 2, r * 2));
				}
				break;
			case GRID:
			{
				// A receding grid on the lower half, with a sun on the horizon for vaporwave.
				int horizon = h * 11 / 20;
				if (name == GielinorWrappedConfig.ThemeName.VAPORWAVE)
				{
					double r = unit * 0.22;
					g.setPaint(new GradientPaint(0, (float) (horizon - r * 2), accent2, 0, horizon, new Color(0xFFD319)));
					g.fill(new Ellipse2D.Double(w / 2.0 - r, horizon - r * 1.6, r * 2, r * 2));
					g.setColor(bottom);
					for (int i = 0; i < 5; i++)
					{
						int band = (int) (r * 0.04 * (i + 1));
						g.fillRect(0, (int) (horizon - r * 0.9 + i * r * 0.18), w, band);
					}
					g.setPaint(new GradientPaint(0, horizon, mix(bottom, Color.BLACK, 0.4), 0, h, bottom));
					g.fillRect(0, horizon, w, h - horizon);
				}
				g.setColor(alpha(accent2, 0.25));
				for (int i = -12; i <= 12; i++)
				{
					g.drawLine(w / 2 + i * w / 24, horizon, w / 2 + i * w / 4, h);
				}
				double shift = (t * 0.6) % 1;
				for (int i = 0; i < 10; i++)
				{
					double p = (i + shift) / 10;
					int y = horizon + (int) ((h - horizon) * p * p);
					g.drawLine(0, y, w, y);
				}
				g.setPaint(new RadialGradientPaint(w / 2f, horizon, unit / 3f, new float[]{0, 1}, new Color[]{alpha(accent, 0.35), alpha(accent, 0)}));
				g.fillRect(0, 0, w, h);
				break;
			}
			case EMBERS:
				// Embers rising.
				for (int i = 0; i < 50; i++)
				{
					double speed = 0.03 + hash(i, 1) * 0.06;
					double y = (1 - ((hash(i, 2) + t * speed) % 1)) * h;
					double x = hash(i, 3) * w + Math.sin(t + i) * unit / 60.0;
					double r = 1.5 + hash(i, 4) * unit / 300.0;
					g.setColor(alpha(i % 3 == 0 ? accent2 : accent, 0.3 + 0.4 * hash(i, 5)));
					g.fill(new Ellipse2D.Double(x - r, y - r, r * 2, r * 2));
				}
				break;
			case BLOBS:
				g.setColor(alpha(accent, 0.07));
				g.fill(new Ellipse2D.Double(w * 0.65 + Math.sin(t * 0.3) * unit * 0.03, -h * 0.2, unit * 0.8, unit * 0.8));
				g.setColor(alpha(accent2, 0.06));
				g.fill(new Ellipse2D.Double(-unit * 0.3, h * 0.6 + Math.cos(t * 0.3) * unit * 0.03, unit * 0.7, unit * 0.7));
				break;
			case SNOW:
				for (int i = 0; i < 110; i++)
				{
					double speed = 0.04 + hash(i, 1) * 0.07;
					double y = ((hash(i, 2) + t * speed) % 1) * h;
					double x = hash(i, 3) * w + Math.sin(t * (0.6 + hash(i, 6)) + i) * unit / 40.0;
					double r = 1 + hash(i, 4) * unit / 260.0;
					g.setColor(alpha(Color.WHITE, 0.35 + 0.5 * hash(i, 5)));
					g.fill(new Ellipse2D.Double(x - r, y - r, r * 2, r * 2));
				}
				break;
			case RAIN:
			{
				g.setStroke(new BasicStroke(Math.max(1f, unit / 700f)));
				double len = unit / 22.0;
				for (int i = 0; i < 120; i++)
				{
					double speed = 0.6 + hash(i, 1) * 0.5;
					double y = ((hash(i, 2) + t * speed) % 1) * (h + len) - len;
					double x = hash(i, 3) * (w + h * 0.2) - y * 0.2;
					g.setColor(alpha(text, 0.12 + 0.2 * hash(i, 5)));
					g.drawLine((int) x, (int) y, (int) (x - len * 0.2), (int) (y + len));
				}
				break;
			}
			case BUBBLES:
				g.setStroke(new BasicStroke(Math.max(1f, unit / 500f)));
				for (int i = 0; i < 40; i++)
				{
					double speed = 0.03 + hash(i, 1) * 0.05;
					double y = (1 - ((hash(i, 2) + t * speed) % 1)) * (h * 1.1);
					double x = hash(i, 3) * w + Math.sin(t * 1.3 + i) * unit / 50.0;
					double r = unit / 120.0 + hash(i, 4) * unit / 30.0;
					g.setColor(alpha(i % 2 == 0 ? accent : accent2, 0.25 + 0.3 * hash(i, 5)));
					g.draw(new Ellipse2D.Double(x - r, y - r, r * 2, r * 2));
					g.fill(new Ellipse2D.Double(x - r * 0.45, y - r * 0.55, r * 0.3, r * 0.3));
				}
				break;
			case SPARKLES:
				for (int i = 0; i < 45; i++)
				{
					double tw = Math.max(0, Math.sin(t * (1.2 + hash(i, 3) * 2) + i * 1.7));
					if (tw <= 0.05)
					{
						continue;
					}
					double x = hash(i, 1) * w;
					double y = hash(i, 2) * h;
					double r = (unit / 90.0 + hash(i, 4) * unit / 45.0) * tw;
					g.setColor(alpha(i % 3 == 0 ? accent2 : accent, 0.35 + 0.5 * tw));
					g.fill(star(x, y, r));
				}
				break;
			case AURORA:
				for (int band = 0; band < 3; band++)
				{
					Color c = band == 1 ? accent2 : accent;
					Path2D p = new Path2D.Double();
					double base = h * (0.22 + band * 0.12);
					double thick = h * 0.16;
					p.moveTo(0, base);
					for (int x = 0; x <= w; x += Math.max(4, w / 60))
					{
						p.lineTo(x, base + Math.sin(x * 4.0 / w + t * 0.35 + band * 1.9) * h * 0.06);
					}
					for (int x = w; x >= 0; x -= Math.max(4, w / 60))
					{
						p.lineTo(x, base + thick + Math.sin(x * 3.0 / w + t * 0.3 + band) * h * 0.05);
					}
					p.closePath();
					g.setPaint(new GradientPaint(0, (float) base, alpha(c, 0.28), 0, (float) (base + thick * 1.3), alpha(c, 0)));
					g.fill(p);
				}
				break;
			case FOG:
				for (int i = 0; i < 8; i++)
				{
					double x = ((hash(i, 1) + t * (0.01 + hash(i, 2) * 0.015)) % 1.4 - 0.2) * w;
					double y = h * (0.45 + hash(i, 3) * 0.55);
					float r = (float) (unit * (0.35 + hash(i, 4) * 0.35));
					g.setPaint(new RadialGradientPaint((float) x, (float) y, r, new float[]{0, 1},
						new Color[]{alpha(mix(text, bottom, 0.5), 0.16), alpha(mix(text, bottom, 0.5), 0)}));
					g.fillRect(0, 0, w, h);
				}
				break;
			case RAYS:
			{
				int n = 14;
				double turn = t * 0.05;
				g.setColor(alpha(light() ? Color.WHITE : accent, light() ? 0.25 : 0.08));
				double r = Math.max(w, h) * 1.5;
				for (int i = 0; i < n; i += 2)
				{
					double a0 = turn + i * Math.PI * 2 / n;
					double a1 = turn + (i + 1) * Math.PI * 2 / n;
					Path2D p = new Path2D.Double();
					p.moveTo(w / 2.0, -h * 0.1);
					p.lineTo(w / 2.0 + Math.cos(a0) * r, -h * 0.1 + Math.sin(a0) * r);
					p.lineTo(w / 2.0 + Math.cos(a1) * r, -h * 0.1 + Math.sin(a1) * r);
					p.closePath();
					g.fill(p);
				}
				break;
			}
			case NONE:
				break;
			default:
				// Parchment: soft warm light with a dark vignette.
				g.setPaint(new RadialGradientPaint(w / 2f, h * 0.4f, Math.max(w, h) * 0.75f, new float[]{0, 0.6f, 1},
					new Color[]{alpha(accent, 0.18), alpha(accent, 0.04), new Color(0, 0, 0, light() ? 30 : 120)}));
				g.fillRect(0, 0, w, h);
				for (int i = 0; i < 30; i++)
				{
					double y = (1 - ((hash(i, 2) + t * 0.02) % 1)) * h;
					double r = 1 + hash(i, 4) * unit / 350.0;
					g.setColor(alpha(accent, 0.15 + 0.25 * hash(i, 5)));
					g.fill(new Ellipse2D.Double(hash(i, 3) * w - r, y - r, r * 2, r * 2));
				}
		}
		g.setStroke(oldStroke);
		g.setComposite(old);
	}

	/** A four-pointed twinkle. */
	static Path2D star(double x, double y, double r)
	{
		Path2D p = new Path2D.Double();
		double in = r * 0.22;
		p.moveTo(x, y - r);
		p.lineTo(x + in, y - in);
		p.lineTo(x + r, y);
		p.lineTo(x + in, y + in);
		p.lineTo(x, y + r);
		p.lineTo(x - in, y + in);
		p.lineTo(x - r, y);
		p.lineTo(x - in, y - in);
		p.closePath();
		return p;
	}

	/** Darkens or lightens a band behind text so it reads over busy backgrounds. */
	void scrim(Graphics2D g, int x, int y, int w, int h)
	{
		g.setComposite(AlphaComposite.SrcOver);
		g.setColor(panel);
		g.fillRoundRect(x, y, w, h, Math.min(w, h) / 6, Math.min(w, h) / 6);
	}

	boolean hasFinish()
	{
		return grade != GielinorWrappedConfig.Grade.NONE || vignette > 0 || grain > 0 || scanlines || border != GielinorWrappedConfig.Border.NONE;
	}

	/**
	 * The finishing pass over a whole frame or card: colour grade, vignette, grain, scanlines, then the border.
	 * {@code frame} seeds the grain so it moves from frame to frame.
	 */
	void finish(BufferedImage img, int frame)
	{
		if (!hasFinish())
		{
			return;
		}
		int w = img.getWidth();
		int h = img.getHeight();
		boolean direct = img.getType() == BufferedImage.TYPE_INT_RGB || img.getType() == BufferedImage.TYPE_INT_ARGB;
		int[] px = direct ? ((DataBufferInt) img.getRaster().getDataBuffer()).getData() : img.getRGB(0, 0, w, h, null, 0, w);
		int[] vig = vignette > 0 ? vignetteMap(w, h) : null;
		int grainAmp = (int) Math.round(grain * 48);
		int lineStep = Math.max(2, h / 300);
		long seed = 0x9E3779B97F4A7C15L * (frame + 1);
		for (int y = 0; y < h; y++)
		{
			boolean dark = scanlines && (y / (lineStep / 2 == 0 ? 1 : lineStep / 2)) % 2 == 1;
			int row = y * w;
			for (int x = 0; x < w; x++)
			{
				int i = row + x;
				int c = px[i];
				int r = (c >> 16) & 0xFF;
				int gr = (c >> 8) & 0xFF;
				int b = c & 0xFF;
				if (grade != GielinorWrappedConfig.Grade.NONE)
				{
					int g2 = gradePixel(grade, r, gr, b);
					r = (g2 >> 16) & 0xFF;
					gr = (g2 >> 8) & 0xFF;
					b = g2 & 0xFF;
				}
				int mul = 256;
				if (vig != null)
				{
					mul = vig[i];
				}
				if (dark)
				{
					mul = mul * 210 >> 8;
				}
				if (mul != 256)
				{
					r = r * mul >> 8;
					gr = gr * mul >> 8;
					b = b * mul >> 8;
				}
				if (grainAmp > 0)
				{
					seed ^= seed << 13;
					seed ^= seed >>> 7;
					seed ^= seed << 17;
					int n = (int) ((seed >>> 40) & 0xFF) - 128;
					int d = n * grainAmp >> 7;
					r = clamp255(r + d);
					gr = clamp255(gr + d);
					b = clamp255(b + d);
				}
				px[i] = (c & 0xFF000000) | (r << 16) | (gr << 8) | b;
			}
		}
		if (!direct)
		{
			img.setRGB(0, 0, w, h, px, 0, w);
		}
		if (border != GielinorWrappedConfig.Border.NONE)
		{
			Graphics2D g = img.createGraphics();
			g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
			drawBorder(g, w, h);
			g.dispose();
		}
	}

	private int[] vignetteMap(int w, int h)
	{
		if (vignetteMap != null && vignetteW == w && vignetteH == h)
		{
			return vignetteMap;
		}
		int[] map = new int[w * h];
		double cx = w / 2.0;
		double cy = h / 2.0;
		double max = Math.hypot(cx, cy);
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				double d = Math.hypot(x - cx, y - cy) / max;
				double s = Captions.clamp((d - 0.4) / 0.65);
				s = s * s * (3 - 2 * s);
				map[y * w + x] = (int) Math.round(256 * (1 - vignette * 0.85 * s));
			}
		}
		vignetteMap = map;
		vignetteW = w;
		vignetteH = h;
		return map;
	}

	static int gradePixel(GielinorWrappedConfig.Grade grade, int r, int g, int b)
	{
		double rf = r;
		double gf = g;
		double bf = b;
		double l = 0.299 * r + 0.587 * g + 0.114 * b;
		switch (grade)
		{
			case WARM:
				rf = r * 1.08 + 8;
				gf = g * 1.02 + 2;
				bf = b * 0.86;
				break;
			case COOL:
				rf = r * 0.88;
				gf = g * 1.0 + 2;
				bf = b * 1.08 + 10;
				break;
			case VINTAGE:
				rf = 24 + (l * 0.25 + r * 0.75) * 0.86;
				gf = 18 + (l * 0.25 + g * 0.75) * 0.80;
				bf = 34 + (l * 0.25 + b * 0.75) * 0.64;
				break;
			case SEPIA:
				rf = r * 0.393 + g * 0.769 + b * 0.189;
				gf = r * 0.349 + g * 0.686 + b * 0.168;
				bf = r * 0.272 + g * 0.534 + b * 0.131;
				break;
			case MONO:
			{
				double m = (l - 128) * 1.12 + 128;
				rf = m;
				gf = m;
				bf = m;
				break;
			}
			case VIVID:
				rf = ((l + (r - l) * 1.4) - 128) * 1.08 + 128;
				gf = ((l + (g - l) * 1.4) - 128) * 1.08 + 128;
				bf = ((l + (b - l) * 1.4) - 128) * 1.08 + 128;
				break;
			case DREAMY:
				rf = 28 + (l * 0.2 + r * 0.8) * 0.9 + 10;
				gf = 22 + (l * 0.2 + g * 0.8) * 0.88;
				bf = 30 + (l * 0.2 + b * 0.8) * 0.9 + 8;
				break;
			case TEAL_ORANGE:
			{
				double k = (l / 255 - 0.5) * 2;
				rf = r + k * 26;
				gf = g + k * 6;
				bf = b - k * 30;
				break;
			}
			default:
				break;
		}
		return clamp255((int) rf) << 16 | clamp255((int) gf) << 8 | clamp255((int) bf);
	}

	private static int clamp255(int v)
	{
		return v < 0 ? 0 : v > 255 ? 255 : v;
	}

	private void drawBorder(Graphics2D g, int w, int h)
	{
		int u = Math.min(w, h);
		float line = Math.max(2f, u / 260f);
		int m = u / 36;
		switch (border)
		{
			case LINE:
				g.setColor(accent);
				g.setStroke(new BasicStroke(line));
				g.drawRect(m, m, w - 2 * m, h - 2 * m);
				break;
			case DOUBLE:
				g.setColor(accent);
				g.setStroke(new BasicStroke(line));
				g.drawRect(m, m, w - 2 * m, h - 2 * m);
				g.setStroke(new BasicStroke(line / 2));
				int m2 = m + (int) (line * 3);
				g.drawRect(m2, m2, w - 2 * m2, h - 2 * m2);
				break;
			case CORNERS:
			{
				g.setColor(accent);
				g.setStroke(new BasicStroke(line * 1.5f, BasicStroke.CAP_SQUARE, BasicStroke.JOIN_MITER));
				int len = u / 9;
				int r = w - m;
				int bt = h - m;
				g.drawPolyline(new int[]{m, m, m + len}, new int[]{m + len, m, m}, 3);
				g.drawPolyline(new int[]{r - len, r, r}, new int[]{m, m, m + len}, 3);
				g.drawPolyline(new int[]{m, m, m + len}, new int[]{bt - len, bt, bt}, 3);
				g.drawPolyline(new int[]{r - len, r, r}, new int[]{bt, bt, bt - len}, 3);
				break;
			}
			case INTERFACE:
			{
				// Stone-and-wood frame like the game's interfaces.
				int t = Math.max(6, u / 45);
				g.setColor(new Color(0x3E3529));
				g.fillRect(0, 0, w, t);
				g.fillRect(0, h - t, w, t);
				g.fillRect(0, 0, t, h);
				g.fillRect(w - t, 0, t, h);
				g.setStroke(new BasicStroke(Math.max(1f, t / 5f)));
				g.setColor(new Color(0x5D5447));
				g.drawRect(t / 5, t / 5, w - 2 * t / 5, h - 2 * t / 5);
				g.setColor(new Color(0x18140F));
				g.drawRect(t, t, w - 2 * t, h - 2 * t);
				g.setColor(new Color(0x7A6A52));
				for (int[] c : new int[][]{{0, 0}, {w - t * 2, 0}, {0, h - t * 2}, {w - t * 2, h - t * 2}})
				{
					g.fillRect(c[0] + t / 3, c[1] + t / 3, t * 2 - 2 * t / 3, t * 2 - 2 * t / 3);
				}
				break;
			}
			case POLAROID:
			{
				int s = u / 30;
				int bottomBand = u / 9;
				g.setColor(new Color(0xF7F4EC));
				g.fillRect(0, 0, w, s);
				g.fillRect(0, h - bottomBand, w, bottomBand);
				g.fillRect(0, 0, s, h);
				g.fillRect(w - s, 0, s, h);
				g.setColor(new Color(0, 0, 0, 40));
				g.setStroke(new BasicStroke(Math.max(1f, u / 600f)));
				g.drawRect(s, s, w - 2 * s, h - s - bottomBand);
				break;
			}
			default:
				break;
		}
	}

	/** Deterministic value in [0, 1). */
	static double hash(int i, int salt)
	{
		long x = i * 0x9E3779B97F4A7C15L + salt * 0xC2B2AE3D27D4EB4FL;
		x ^= x >>> 31;
		x *= 0xBF58476D1CE4E5B9L;
		x ^= x >>> 29;
		return (x >>> 11) / (double) (1L << 53);
	}
}

package com.gielinorwrapped;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.Arrays;
import java.util.Collection;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.RejectedExecutionException;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.http.api.item.ItemPrice;

/**
 * Counts the logged-in account's play into today's {@link DayRecord}. Every method runs on the client
 * thread; records are written on the I/O executor.
 */
@Slf4j
class Tracker
{
	/** Save about once a minute while playing. */
	private static final int SAVE_TICKS = 100;
	/** Mouse or keyboard input within this many client cycles (20 ms) counts as active play. */
	private static final int ACTIVE_CYCLES = 3000;
	/** Drops worth less than this aren't kept in the day's drop list. */
	private static final long MIN_LISTED_DROP = 10_000;
	/** A personal-best message within this many ticks of a kill-count message is credited to that boss. */
	private static final int PB_KC_TICKS = 5;
	private static final int GE_BASELINE_TICKS = 3;

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final GielinorWrappedConfig config;
	private final StatsStore store;
	private final ExecutorService io;
	private final Consumer<Moment> onMoment;

	private long account = -1;
	private LocalDate date;
	private DayRecord today;
	/** False until the stored record for today has been read and merged; saving would overwrite it. */
	private boolean loaded;
	private int ticksSinceSave;
	private int tick;
	private int[] lastXp;
	private boolean baselinePending;
	private boolean loggedOut = true;
	private long carryMillis;
	private String lastKcName;
	private int lastKcTick = -100;
	private Moment lastPet;
	private int lastPetTick = -100;
	/** A kill time seen just before its kill-count message, waiting to be credited. */
	private long pendingTime;
	private int pendingTimeTick = -100;
	/** Per Grand Exchange slot: the item, the gp already counted and whether its trade is recorded. */
	private final int[] geItem = new int[8];
	private final long[] geSpent = new long[8];
	private final boolean[] geDone = new boolean[8];
	private final boolean[] geSeen = new boolean[8];
	/** Offers reported up to this tick are the state at login, not new trades. */
	private int geBaselineUntil = -100;
	private volatile String playerName;

	Tracker(Client client, ClientThread clientThread, ItemManager itemManager, GielinorWrappedConfig config,
		StatsStore store, ExecutorService io, Consumer<Moment> onMoment)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.config = config;
		this.store = store;
		this.io = io;
		this.onMoment = onMoment;
	}

	long getAccount()
	{
		return account;
	}

	String getPlayerName()
	{
		return playerName;
	}

	/** Today's record as JSON, for recaps that include today. Client thread only. */
	String snapshot()
	{
		return today == null ? null : store.gson().toJson(today);
	}

	LocalDate getDate()
	{
		return date;
	}

	void loggedIn()
	{
		long hash = client.getAccountHash();
		if (hash == -1)
		{
			return;
		}
		if (hash != account)
		{
			save();
			account = hash;
			playerName = null;
			startDay(LocalDate.now());
		}
		if (loggedOut)
		{
			today.logins++;
			loggedOut = false;
		}
		// Every skill is reported again after a login or world hop; take a fresh baseline on the next tick.
		baselinePending = true;
		// So are Grand Exchange offers, sometimes as empty first and then as they really are.
		geBaselineUntil = tick + GE_BASELINE_TICKS;
	}

	void loggedOut()
	{
		save();
		loggedOut = true;
		baselinePending = true;
		lastXp = null;
		// Offers are reported again on the next login; treat that as a fresh baseline.
		Arrays.fill(geSeen, false);
	}

	/** Saves and forgets the account; used on shutdown. */
	void close()
	{
		save();
		account = -1;
		today = null;
		date = null;
		lastXp = null;
		loggedOut = true;
	}

	private void startDay(LocalDate day)
	{
		date = day;
		today = new DayRecord(day.toString());
		loaded = false;
		long acc = account;
		execute(() ->
		{
			DayRecord stored = store.readDay(acc, day);
			clientThread.invokeLater(() ->
			{
				if (acc != account || !day.equals(date))
				{
					return;
				}
				if (stored != null)
				{
					stored.merge(today);
					today = stored;
				}
				loaded = true;
			});
		});
	}

	void save()
	{
		if (today == null || !loaded || account == -1)
		{
			return;
		}
		ticksSinceSave = 0;
		String json = store.gson().toJson(today);
		long acc = account;
		String day = today.date;
		execute(() ->
		{
			try
			{
				store.writeDay(acc, day, json);
			}
			catch (Exception e)
			{
				log.warn("Unable to save Wrapped stats", e);
			}
		});
	}

	void onTick()
	{
		tick++;
		if (account == -1 || today == null)
		{
			return;
		}
		LocalDate now = LocalDate.now();
		if (!now.equals(date))
		{
			save();
			startDay(now);
		}
		Player player = client.getLocalPlayer();
		if (playerName == null && player != null && player.getName() != null)
		{
			playerName = player.getName();
		}
		if (baselinePending)
		{
			takeBaseline();
		}
		today.accountType = client.getVarbitValue(VarbitID.IRONMAN);

		carryMillis += 600;
		if (carryMillis >= 1000)
		{
			long secs = carryMillis / 1000;
			carryMillis %= 1000;
			today.playSeconds += secs;
			today.hours[LocalTime.now().getHour()] += secs;
			if (Math.min(client.getMouseIdleTicks(), client.getKeyboardIdleTicks()) < ACTIVE_CYCLES)
			{
				today.activeSeconds += secs;
			}
			WorldPoint wp = config.trackAreas() ? location(player) : null;
			if (wp != null)
			{
				String area = Areas.name(wp.getRegionID());
				if (area != null)
				{
					today.areas.merge(area, secs, Long::sum);
				}
				today.regions.merge(Integer.toString(wp.getRegionID()), secs, Long::sum);
			}
		}

		if (++ticksSinceSave >= SAVE_TICKS)
		{
			save();
		}
	}

	private WorldPoint location(Player player)
	{
		if (player == null)
		{
			return null;
		}
		LocalPoint lp = player.getLocalLocation();
		if (lp == null)
		{
			return null;
		}
		return WorldPoint.fromLocalInstance(client, lp);
	}

	private void takeBaseline()
	{
		Skill[] skills = Skill.values();
		lastXp = new int[skills.length];
		for (Skill s : skills)
		{
			lastXp[s.ordinal()] = isOverall(s) ? -1 : client.getSkillExperience(s);
			if (!isOverall(s) && lastXp[s.ordinal()] > 0)
			{
				today.skillXp.put(s.getName(), (long) lastXp[s.ordinal()]);
			}
		}
		baselinePending = false;
	}

	@SuppressWarnings("deprecation")
	private static boolean isOverall(Skill s)
	{
		return s == Skill.OVERALL;
	}

	void onStat(Skill skill, int xp)
	{
		if (today == null || lastXp == null || baselinePending || isOverall(skill))
		{
			return;
		}
		int i = skill.ordinal();
		int prev = lastXp[i];
		lastXp[i] = xp;
		int gained = xp - prev;
		if (prev < 0 || gained <= 0 || gained > 50_000_000)
		{
			return;
		}
		String name = skill.getName();
		today.xp.merge(name, (long) gained, Long::sum);
		today.skillXp.merge(name, (long) xp, Math::max);
		int before = Experience.getLevelForXp(prev);
		int after = Experience.getLevelForXp(xp);
		if (after > before)
		{
			today.levels.merge(name, after - before, Integer::sum);
			if (after >= config.levelMoments() || after == Experience.MAX_REAL_LEVEL)
			{
				boolean max = after == Experience.MAX_REAL_LEVEL;
				int importance = max ? 100 : after >= 90 ? 70 : after % 10 == 0 ? 50 : 25 + after / 4;
				moment(max ? Moment.Type.MAX_LEVEL : Moment.Type.LEVEL_UP, after + " " + name, max ? "Maxed!" : "Level up", after, importance);
			}
		}
	}

	/** Records loot; {@code kill} counts one kill of the source. */
	void onLoot(String source, Collection<ItemStack> items, boolean kill)
	{
		if (today == null || source == null)
		{
			return;
		}
		long total = 0;
		long now = System.currentTimeMillis();
		for (ItemStack stack : items)
		{
			int id = itemManager.canonicalize(stack.getId());
			long value = (long) itemManager.getItemPrice(id) * stack.getQuantity();
			total += value;
			if (value >= MIN_LISTED_DROP)
			{
				String name = itemManager.getItemComposition(id).getName();
				today.addDrop(new DayRecord.Drop(now, id, name, stack.getQuantity(), value, source));
				if (value >= config.dropThreshold())
				{
					String title = stack.getQuantity() > 1 ? stack.getQuantity() + " x " + name : name;
					moment(Moment.Type.DROP, title, "from " + source, value, dropImportance(value)).itemId = id;
				}
			}
		}
		today.lootValue += total;
		today.lootBySource.merge(source, total, Long::sum);
		if (kill)
		{
			today.kills.merge(source, 1, Integer::sum);
		}
	}

	/** 1M is 50, each tenfold adds 17, capped at 100. */
	static int dropImportance(long value)
	{
		if (value <= 0)
		{
			return 0;
		}
		double tens = Math.log10(value) - 6;
		return (int) Math.max(20, Math.min(100, Math.round(50 + tens * 17)));
	}

	void onDeath()
	{
		if (today == null)
		{
			return;
		}
		today.deaths++;
		moment(Moment.Type.DEATH, "Oh dear, you are dead!", null, today.deaths, 40);
	}

	void onGameMessage(String message)
	{
		if (today == null)
		{
			return;
		}
		ChatParser.Result r = ChatParser.parse(message);
		if (r == null)
		{
			return;
		}
		switch (r.kind)
		{
			case KILL_COUNT:
			{
				int count = (int) Math.min(Integer.MAX_VALUE, r.number);
				today.killCounts.merge(r.name, count, Math::max);
				today.bossKills.merge(r.name, 1, Integer::sum);
				lastKcName = r.name;
				lastKcTick = tick;
				if (tick - pendingTimeTick <= PB_KC_TICKS && pendingTime > 0)
				{
					today.fastest.merge(r.name, pendingTime, Math::min);
					pendingTime = 0;
				}
				if (count == 1)
				{
					moment(Moment.Type.KILL_COUNT, "First " + r.name + " kill", "Kill count 1", count, 60);
				}
				else if (count % 100 == 0)
				{
					moment(Moment.Type.KILL_COUNT, count + " " + r.name, "Kill count milestone", count, count % 1000 == 0 ? 65 : 45);
				}
				break;
			}
			case CLUE:
			{
				today.clues.merge(r.name, 1, Integer::sum);
				int importance = clueImportance(r.name);
				moment(Moment.Type.CLUE, capitalize(r.name) + " clue", r.number + " completed", r.number, importance);
				break;
			}
			case PET:
				lastPet = moment(Moment.Type.PET, "Pet drop!", "You have a funny feeling…", 0, 100);
				lastPetTick = tick;
				break;
			case COLLECTION_LOG:
			{
				int id = itemIdByName(r.name);
				moment(Moment.Type.COLLECTION_LOG, r.name, "New collection log slot", 0, 55).itemId = id;
				// The log message right after a pet message names the pet.
				if (lastPet != null && tick - lastPetTick <= PB_KC_TICKS && lastPet.itemId == 0)
				{
					lastPet.itemId = id;
					lastPet.detail = r.name;
				}
				break;
			}
			case QUEST:
				moment(Moment.Type.QUEST, r.name, "Quest complete", 0, 50);
				break;
			case COMBAT_TASK:
				moment(Moment.Type.COMBAT_TASK, r.name, capitalize(r.detail) + " combat task", 0, 30 + tierIndex(r.detail) * 8);
				break;
			case DIARY:
				moment(Moment.Type.DIARY, r.name + " diary task", capitalize(r.detail) + " task", 0, 15 + tierIndex(r.detail) * 8);
				break;
			case PERSONAL_BEST:
			{
				String boss = tick - lastKcTick <= PB_KC_TICKS ? lastKcName : null;
				moment(Moment.Type.PERSONAL_BEST, boss == null ? "New personal best" : boss + " PB", r.detail, r.number, 60);
				killTime(boss, r.number);
				break;
			}
			case DURATION:
				killTime(tick - lastKcTick <= PB_KC_TICKS ? lastKcName : null, r.number);
				break;
			case SLAYER_TASK:
				today.slayerTasks++;
				if (r.name != null && r.number >= 100)
				{
					moment(Moment.Type.KILL_COUNT, r.number + " " + r.name, "Slayer task done", r.number, 25);
				}
				break;
		}
	}

	/** Credits a kill time to the boss, or holds it for a kill-count message that comes right after. */
	private void killTime(String boss, long seconds)
	{
		if (seconds <= 0)
		{
			return;
		}
		if (boss != null)
		{
			today.fastest.merge(boss, seconds, Math::min);
		}
		else
		{
			pendingTime = seconds;
			pendingTimeTick = tick;
		}
	}

	/**
	 * Counts gp moved by a Grand Exchange offer. The first report of each slot after login is a baseline;
	 * after that, gp spent (or received) since the last report is added, and the trade is listed once when
	 * the offer finishes or is cancelled part-way.
	 *
	 * @param state the offer's state name, e.g. BUYING, BOUGHT, CANCELLED_SELL, EMPTY
	 */
	void onGrandExchange(int slot, int itemId, String state, int quantitySold, long spent)
	{
		if (today == null || slot < 0 || slot >= geItem.length || state == null)
		{
			return;
		}
		boolean empty = "EMPTY".equals(state) || itemId <= 0;
		if (!geSeen[slot] || tick <= geBaselineUntil)
		{
			geSeen[slot] = true;
			geItem[slot] = empty ? 0 : itemId;
			geSpent[slot] = empty ? 0 : spent;
			geDone[slot] = !empty && isFinished(state);
			return;
		}
		if (empty)
		{
			geItem[slot] = 0;
			geSpent[slot] = 0;
			geDone[slot] = false;
			return;
		}
		if (itemId != geItem[slot] || spent < geSpent[slot])
		{
			// A new offer in this slot.
			geItem[slot] = itemId;
			geSpent[slot] = 0;
			geDone[slot] = false;
		}
		boolean buy = state.contains("BUY") || "BOUGHT".equals(state);
		long delta = spent - geSpent[slot];
		geSpent[slot] = spent;
		if (delta > 0)
		{
			if (buy)
			{
				today.geBought += delta;
			}
			else
			{
				today.geSold += delta;
			}
		}
		if (isFinished(state) && !geDone[slot] && spent > 0)
		{
			geDone[slot] = true;
			today.geTrades++;
			String name = itemManager.getItemComposition(itemId).getName();
			today.addTrade(new DayRecord.Trade(System.currentTimeMillis(), itemId, name, quantitySold, spent, buy));
		}
	}

	private static boolean isFinished(String state)
	{
		return "BOUGHT".equals(state) || "SOLD".equals(state) || state.startsWith("CANCELLED");
	}

	/** Today's drop with that name, else a tradeable item with exactly that name; 0 if neither. */
	private int itemIdByName(String name)
	{
		for (DayRecord.Drop d : today.drops)
		{
			if (d.itemId > 0 && name.equalsIgnoreCase(d.name))
			{
				return d.itemId;
			}
		}
		for (ItemPrice p : itemManager.search(name))
		{
			if (name.equalsIgnoreCase(p.getName()))
			{
				return p.getId();
			}
		}
		return 0;
	}

	private static int clueImportance(String tier)
	{
		switch (tier)
		{
			case "master":
				return 60;
			case "elite":
				return 50;
			case "hard":
				return 35;
			case "medium":
				return 25;
			case "easy":
				return 20;
			default:
				return 15;
		}
	}

	private static int tierIndex(String tier)
	{
		switch (tier == null ? "" : tier)
		{
			case "grandmaster":
				return 5;
			case "master":
				return 4;
			case "elite":
				return 3;
			case "hard":
				return 2;
			case "medium":
				return 1;
			default:
				return 0;
		}
	}

	static String capitalize(String s)
	{
		return s == null || s.isEmpty() ? "" : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	/** Saves a "Clip that" moment so the clip shows up with the day's highlights. */
	Moment manualMoment()
	{
		if (today == null)
		{
			return null;
		}
		return moment(Moment.Type.MANUAL, "Clip", null, 0, 45);
	}

	private Moment moment(Moment.Type type, String title, String detail, long value, int importance)
	{
		Moment m = new Moment(System.currentTimeMillis(), type, title, detail, value, importance);
		today.addMoment(m);
		onMoment.accept(m);
		return m;
	}

	/** Called on the client thread once a moment's clip is on disk. */
	void clipSaved(Moment m, String clip)
	{
		m.clip = clip;
	}

	private void execute(Runnable r)
	{
		try
		{
			io.execute(r);
		}
		catch (RejectedExecutionException e)
		{
			log.debug("I/O executor is shut down");
		}
	}
}

package com.gielinorwrapped;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * A ready-to-paste title, description and chapter list for uploading a recap video. Chapters follow
 * YouTube's rules: the first at 0:00, at least three, each at least ten seconds long.
 */
final class UploadText
{
	static final String FILE = "upload.txt";
	static final int MIN_CHAPTER_SECONDS = 10;
	static final int MIN_CHAPTERS = 3;

	private static final Map<String, String> TITLES = new HashMap<>();

	static
	{
		TITLES.put("title", "Intro");
		TITLES.put("xp", "Experience");
		TITLES.put("loot", "Loot");
		TITLES.put("kills", "Kills");
		TITLES.put("time", "Time played");
		TITLES.put("clip", "Highlights");
		TITLES.put("footage", "Highlights");
		TITLES.put("custom", "Highlights");
		TITLES.put("timelapse", "Timelapse");
		TITLES.put("map", "Where I played");
		TITLES.put("graphs", "Graphs");
		TITLES.put("bosses", "Bosses and Slayer");
		TITLES.put("collection", "Collection log");
		TITLES.put("ge", "Grand Exchange");
		TITLES.put("montage", "Month by month");
		TITLES.put("deaths", "Deaths");
		TITLES.put("gallery", "Gallery");
		TITLES.put("compare", "Vs last time");
		TITLES.put("versus", "Vs a friend");
		TITLES.put("pace", "Goals");
		TITLES.put("persona", "Persona");
		TITLES.put("outro", "Outro");
	}

	static final class Chapter
	{
		final double start;
		final String title;

		Chapter(double start, String title)
		{
			this.start = start;
			this.title = title;
		}

		String line()
		{
			return MoreScenes.time((long) Math.floor(start)) + " " + title;
		}
	}

	private UploadText()
	{
	}

	static String title(Recap r, boolean hideName)
	{
		String who = hideName || r.player == null ? "My" : r.player + "'s";
		return who + " Gielinor Wrapped: " + r.period.describe();
	}

	static String description(Recap r)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("My Old School RuneScape ").append(r.period.noun()).append(", wrapped.\n\n");
		DayRecord t = r.total;
		if (t.totalXp() > 0)
		{
			sb.append("XP gained: ").append(Recap.number(t.totalXp())).append('\n');
		}
		if (t.totalLevels() > 0)
		{
			sb.append("Levels gained: ").append(t.totalLevels()).append('\n');
		}
		if (t.lootValue > 0)
		{
			sb.append("Loot: ").append(Recap.gp(t.lootValue)).append('\n');
		}
		if (r.totalBossKills() > 0)
		{
			sb.append("Boss kills: ").append(Recap.number(r.totalBossKills())).append('\n');
		}
		if (t.playSeconds > 0)
		{
			sb.append("Time played: ").append(Recap.duration(t.playSeconds)).append('\n');
		}
		if (!r.skills.isEmpty())
		{
			sb.append("Top skill: ").append(r.skills.get(0).name).append('\n');
		}
		if (r.persona != null && r.persona.title != null)
		{
			sb.append("Persona: ").append(r.persona.title).append('\n');
		}
		sb.append("\nMade with the Gielinor Wrapped RuneLite plugin.");
		return sb.toString();
	}

	/** Chapters from the scene list, or an empty list when the video is too short for them. */
	static List<Chapter> chapters(List<Scenes.Scene> scenes, int fps)
	{
		List<Chapter> raw = new ArrayList<>();
		long frames = 0;
		for (Scenes.Scene s : scenes)
		{
			String title = TITLES.getOrDefault(s.name, "Highlights");
			if (raw.isEmpty() || !raw.get(raw.size() - 1).title.equals(title))
			{
				raw.add(new Chapter(frames / (double) fps, title));
			}
			frames += Math.max(1, Math.round(s.duration * fps));
		}
		double end = frames / (double) fps;
		// Group short chapters with the ones after them until each lasts long enough; a short tail joins the last.
		List<Double> starts = new ArrayList<>();
		List<List<String>> titles = new ArrayList<>();
		for (Chapter c : raw)
		{
			if (starts.isEmpty() || c.start - starts.get(starts.size() - 1) >= MIN_CHAPTER_SECONDS)
			{
				starts.add(c.start);
				titles.add(new ArrayList<>());
			}
			List<String> t = titles.get(titles.size() - 1);
			if (!t.contains(c.title))
			{
				t.add(c.title);
			}
		}
		int n = starts.size();
		if (n > 1 && end - starts.get(n - 1) < MIN_CHAPTER_SECONDS)
		{
			for (String t : titles.remove(n - 1))
			{
				if (!titles.get(n - 2).contains(t))
				{
					titles.get(n - 2).add(t);
				}
			}
			starts.remove(n - 1);
		}
		List<Chapter> out = new ArrayList<>();
		for (int i = 0; i < starts.size(); i++)
		{
			out.add(new Chapter(i == 0 ? 0 : starts.get(i), join(titles.get(i))));
		}
		return out.size() >= MIN_CHAPTERS ? out : new ArrayList<>();
	}

	/** "A", "A & B", "A, B & C", "A, B & more". */
	private static String join(List<String> t)
	{
		if (t.size() == 1)
		{
			return t.get(0);
		}
		if (t.size() == 2)
		{
			return t.get(0) + " & " + t.get(1);
		}
		return t.get(0) + ", " + t.get(1) + " & " + (t.size() == 3 ? t.get(2) : "more");
	}

	static String text(Recap r, boolean hideName, List<Scenes.Scene> scenes, int fps)
	{
		StringBuilder sb = new StringBuilder();
		sb.append(title(r, hideName)).append("\n\n").append(description(r));
		List<Chapter> chapters = scenes == null ? new ArrayList<>() : chapters(scenes, fps);
		if (!chapters.isEmpty())
		{
			sb.append("\n\nChapters\n");
			for (Chapter c : chapters)
			{
				sb.append(c.line()).append('\n');
			}
		}
		return sb.toString().trim() + "\n";
	}
}

