	/** Shows a card at a readable size in a small window. */
	void showPreview(Recaps.Saved s, BufferedImage card)
	{
		showImage(s.meta.period().describe(), card);
	}

	void showImage(String title, BufferedImage card)
	{
		JDialog dialog = new JDialog(SwingUtilities.getWindowAncestor(this), title);
		double scale = Math.min(1, Math.min(900.0 / card.getWidth(), 700.0 / card.getHeight()));
		Image img = scale < 1 ? card.getScaledInstance((int) (card.getWidth() * scale), (int) (card.getHeight() * scale), Image.SCALE_SMOOTH) : card;
		dialog.add(new JLabel(new ImageIcon(img)));
		dialog.pack();
		dialog.setLocationRelativeTo(this);
		dialog.setVisible(true);
	}

	void showMessage(String text, boolean error)
	{
		status.setForeground(error ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.PROGRESS_COMPLETE_COLOR);
		status.setText(text == null ? " " : "<html>" + text + "</html>");
	}

	private <E extends Enum<E>> JPanel combo(String label, String key, E[] values, E current)
	{
		JComboBox<E> c = new JComboBox<>(values);
		c.setSelectedItem(current);
		c.setFont(FontManager.getRunescapeSmallFont());
		c.addActionListener(e ->
		{
			Object v = c.getSelectedItem();
			if (v != null)
			{
				actions.setConfig(key, v);
				refreshStyle(key);
			}
		});
		return row(label, c);
	}

	private JCheckBox check(String label, String key, boolean current)
	{
		JCheckBox c = new JCheckBox(label, current);
		c.setOpaque(false);
		c.setFont(FontManager.getRunescapeSmallFont());
		c.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		c.addActionListener(e ->
		{
			actions.setConfig(key, c.isSelected());
			refreshStyle(key);
		});
		return c;
	}

	private JPanel spinner(String label, String key, int current, int min, int max, int step)
	{
		JSpinner s = new JSpinner(new SpinnerNumberModel(Math.max(min, Math.min(max, current)), min, max, step));
		s.setPreferredSize(new Dimension(64, 22));
		s.addChangeListener(e -> actions.setConfig(key, s.getValue()));
		return row(label, s);
	}

	private JPanel color(String label, String key, Color current)
	{
		JButton b = new JButton(" ");
		b.setBackground(current);
		b.setPreferredSize(new Dimension(64, 20));
		b.setToolTipText("Pick a colour");
		b.addActionListener(e ->
		{
			Color c = JColorChooser.showDialog(this, label, b.getBackground());
			if (c != null)
			{
				b.setBackground(c);
				actions.setConfig(key, c);
			}
		});
		return row(label, b);
	}

	private JPanel text(String label, String key, String current)
	{
		JTextField f = new JTextField(current);
		f.setPreferredSize(new Dimension(110, 22));
		String[] saved = {current};
		Consumer<Object> save = x ->
		{
			if (!f.getText().equals(saved[0]))
			{
				saved[0] = f.getText();
				actions.setConfig(key, saved[0]);
			}
		};
		f.addActionListener(save::accept);
		f.addFocusListener(new java.awt.event.FocusAdapter()
		{
			@Override
			public void focusLost(java.awt.event.FocusEvent e)
			{
				save.accept(e);
			}
		});
		return row(label, f);
	}

	/** Rebuilds the style tab after a change that shows or hides options; other changes leave it be. */
	private void refreshStyle(String key)
	{
		if (tab == Tab.STYLE && REBUILDS_STYLE.contains(key))
		{
			SwingUtilities.invokeLater(() -> showTab(Tab.STYLE));
		}
	}

	private static JPanel row(String label, JComponent control)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0))
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		row.setOpaque(false);
		row.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		row.add(small(label), BorderLayout.WEST);
		JPanel east = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		east.setOpaque(false);
		if (control instanceof JComboBox)
		{
			control.setPreferredSize(new Dimension(118, 22));
		}
		east.add(control);
		row.add(east, BorderLayout.CENTER);
		return row;
	}

	private JButton button(String text, String tip, Runnable action)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setToolTipText(tip);
		b.setMargin(new Insets(2, 5, 2, 5));
		b.addActionListener(e -> action.run());
		return b;
	}

	private static JLabel heading(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(Color.WHITE);
		l.setBorder(BorderFactory.createEmptyBorder(8, 0, 4, 0));
		return left(l);
	}

	private static JLabel help(String text)
	{
		// A fixed body width makes Swing wrap the text and size the label to fit it.
		return small("<html><body style='width:" + (THUMB_WIDTH - 44) + "px'>" + text + "</body></html>");
	}

	private static JPanel box()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		p.setAlignmentX(LEFT_ALIGNMENT);
		return p;
	}

	private static JPanel section()
	{
		JPanel p = new JPanel()
		{
			@Override
			public Dimension getMaximumSize()
			{
				// Full width in the panel's BoxLayout, not just as wide as the widest child.
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		p.setAlignmentX(LEFT_ALIGNMENT);
		return p;
	}

	private static JLabel small(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return l;
	}

	/** Stretches a control across the section. */
	private static <T extends JComponent> T wide(T c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		return c;
	}

	private static <T extends JComponent> T left(T c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		return c;
	}
}

package com.gielinorwrapped.music;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/** A standard MIDI file flattened to channel events in time order, with times in seconds. */
public final class Midi
{
	/** Event times in seconds, ascending. */
	final double[] time;
	/** Status byte (type in the top nibble, channel in the bottom). */
	final int[] status;
	final int[] data1;
	final int[] data2;
	/** Time of the last event, in seconds. */
	public final double length;

	private Midi(double[] time, int[] status, int[] data1, int[] data2)
	{
		this.time = time;
		this.status = status;
		this.data1 = data1;
		this.data2 = data2;
		this.length = time.length == 0 ? 0 : time[time.length - 1];
	}

	public int size()
	{
		return time.length;
	}

	/** Parses MIDI file bytes; throws IllegalArgumentException on anything malformed. */
	public static Midi parse(byte[] b)
	{
		try
		{
			return read(b);
		}
		catch (IndexOutOfBoundsException e)
		{
			throw new IllegalArgumentException("Truncated MIDI", e);
		}
	}

	private static Midi read(byte[] b)
	{
		if (int32(b, 0) != 0x4D546864)
		{
			throw new IllegalArgumentException("Not a MIDI file");
		}
		int headerLen = int32(b, 4);
		int tracks = int16(b, 10);
		int division = (short) int16(b, 12);
		int pos = 8 + headerLen;

		// Each raw event packs tick, track order and position so a sort keeps simultaneous events in file order.
		List<long[]> events = new ArrayList<>();
		List<long[]> tempos = new ArrayList<>();
		long seq = 0;
		for (int t = 0; t < tracks && pos + 8 <= b.length; t++)
		{
			if (int32(b, pos) != 0x4D54726B)
			{
				throw new IllegalArgumentException("Bad track chunk");
			}
			int len = int32(b, pos + 4);
			int p = pos + 8;
			int end = Math.min(b.length, p + len);
			pos = p + len;
			long tick = 0;
			int running = 0;
			while (p < end)
			{
				int delta = 0;
				int c;
				do
				{
					c = b[p++] & 0xFF;
					delta = (delta << 7) | (c & 0x7F);
				}
				while ((c & 0x80) != 0);
				tick += delta;
				int st = b[p] & 0xFF;
				if (st >= 0x80)
				{
					p++;
				}
				else
				{
					st = running;
				}
				if (st == 0xFF)
				{
					int type = b[p++] & 0xFF;
					int mlen = 0;
					do
					{
						c = b[p++] & 0xFF;
						mlen = (mlen << 7) | (c & 0x7F);
					}
					while ((c & 0x80) != 0);
					if (type == 0x51 && mlen == 3)
					{
						int us = (b[p] & 0xFF) << 16 | (b[p + 1] & 0xFF) << 8 | (b[p + 2] & 0xFF);
						tempos.add(new long[]{tick, seq++, us});
					}
					p += mlen;
					if (type == 0x2F)
					{
						break;
					}
					continue;
				}
				if (st == 0xF0 || st == 0xF7)
				{
					int slen = 0;
					do
					{
						c = b[p++] & 0xFF;
						slen = (slen << 7) | (c & 0x7F);
					}
					while ((c & 0x80) != 0);
					p += slen;
					continue;
				}
				if (st < 0x80)
				{
					throw new IllegalArgumentException("Data byte without a status");
				}
				running = st;
				int type = st & 0xF0;
				int d1 = b[p++] & 0x7F;
				int d2 = 0;
				if (type != 0xC0 && type != 0xD0)
				{
					d2 = b[p++] & 0x7F;
				}
				events.add(new long[]{tick, seq++, st, d1, d2});
			}
		}

		events.sort((x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
		tempos.sort((x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));

		int n = events.size();
		double[] time = new double[n];
		int[] status = new int[n];
		int[] d1 = new int[n];
		int[] d2 = new int[n];
		double secondsPerTick;
		boolean smpte = division < 0;
		if (smpte)
		{
			int fps = -(division >> 8);
			int sub = division & 0xFF;
			secondsPerTick = 1.0 / (fps * Math.max(1, sub));
		}
		else
		{
			secondsPerTick = 0.5 / Math.max(1, division);
		}
		int ti = 0;
		long lastTick = 0;
		double seconds = 0;
		for (int i = 0; i < n; i++)
		{
			long[] e = events.get(i);
			long tick = e[0];
			while (!smpte && ti < tempos.size() && tempos.get(ti)[0] <= tick)
			{
				long[] tempo = tempos.get(ti++);
				seconds += (tempo[0] - lastTick) * secondsPerTick;
				lastTick = tempo[0];
				secondsPerTick = tempo[2] / 1e6 / Math.max(1, division);
			}
			seconds += (tick - lastTick) * secondsPerTick;
			lastTick = tick;
			time[i] = seconds;
			status[i] = (int) e[2];
			d1[i] = (int) e[3];
			d2[i] = (int) e[4];
		}
		return new Midi(time, status, d1, d2);
	}

	private static int int32(byte[] b, int p)
	{
		return (b[p] & 0xFF) << 24 | (b[p + 1] & 0xFF) << 16 | (b[p + 2] & 0xFF) << 8 | (b[p + 3] & 0xFF);
	}

	private static int int16(byte[] b, int p)
	{
		return (b[p] & 0xFF) << 8 | (b[p + 1] & 0xFF);
	}

	@Override
	public String toString()
	{
		return "Midi[" + time.length + " events, " + String.format("%.1f", length) + "s, " + Arrays.toString(Arrays.copyOf(status, Math.min(4, status.length))) + "...]";
	}
}

package com.gielinorwrapped.music;

import java.util.HashMap;
import java.util.Map;

/**
 * A small General MIDI style synthesizer: band-limited wavetable voices picked by instrument family,
 * plucked and sustained envelopes, synthesized drums on channel 10 and a light stereo reverb. It is an
 * approximation of the game's own instruments, rendered offline to stereo floats at 44.1 kHz.
 */
public final class Synth
{
	public static final int RATE = 44100;
	private static final int TABLE = 2048;
	private static final int BLOCK = 64;
	private static final int MAX_VOICES = 48;
	private static final double LOOP_GAP = 1.0;

	private final Map<Long, float[]> tables = new HashMap<>();
	private final Voice[] voices = new Voice[MAX_VOICES];
	private final Channel[] channels = new Channel[16];
	private long noteCounter;

	private Synth()
	{
		for (int i = 0; i < voices.length; i++)
		{
			voices[i] = new Voice();
		}
		for (int i = 0; i < channels.length; i++)
		{
			channels[i] = new Channel();
		}
	}

	/**
	 * Renders the song for the given length, looping it if it is shorter.
	 *
	 * @param volume 0..1
	 * @param fade fade in over the first second and out over the last two
	 * @return left and right sample arrays in -1..1
	 */
	public static float[][] render(Midi song, double seconds, double volume, boolean fade)
	{
		return new Synth().run(song, seconds, volume, fade);
	}

	private float[][] run(Midi song, double seconds, double volume, boolean fade)
	{
		int total = (int) Math.ceil(seconds * RATE);
		float[] left = new float[total];
		float[] right = new float[total];
		double period = song.length + LOOP_GAP;
		int ev = 0;
		double offset = 0;
		float[] bl = new float[BLOCK];
		float[] br = new float[BLOCK];
		for (int start = 0; start < total; start += BLOCK)
		{
			double now = start / (double) RATE;
			while (song.size() > 0 && offset + song.time[ev] <= now)
			{
				event(song.status[ev], song.data1[ev], song.data2[ev]);
				if (++ev == song.size())
				{
					ev = 0;
					offset += period;
					allNotesOff();
				}
			}
			int n = Math.min(BLOCK, total - start);
			java.util.Arrays.fill(bl, 0);
			java.util.Arrays.fill(br, 0);
			for (Voice v : voices)
			{
				if (v.active)
				{
					v.render(bl, br, n);
				}
			}
			System.arraycopy(bl, 0, left, start, n);
			System.arraycopy(br, 0, right, start, n);
		}
		new Reverb().apply(left, right, 0.18f);
		master(left, right, volume, fade);
		return new float[][]{left, right};
	}

	/** Levels the mix to a steady loudness, soft-limits peaks, applies the volume and the fades. */
	private static void master(float[] left, float[] right, double volume, boolean fade)
	{
		double sum = 0;
		int counted = 0;
		for (int i = 0; i < left.length; i += 4)
		{
			sum += left[i] * left[i] + right[i] * right[i];
			counted += 2;
		}
		double rms = Math.sqrt(sum / Math.max(1, counted));
		double gain = rms < 1e-6 ? 0 : 0.17 / rms;
		int fadeIn = fade ? Math.min(left.length / 4, RATE) : 0;
		int fadeOut = fade ? Math.min(left.length / 3, 2 * RATE) : Math.min(left.length, RATE / 20);
		for (int i = 0; i < left.length; i++)
		{
			double g = gain;
			if (i < fadeIn)
			{
				g *= i / (double) fadeIn;
			}
			int fromEnd = left.length - i;
			if (fromEnd < fadeOut)
			{
				double f = fromEnd / (double) fadeOut;
				g *= f * f;
			}
			left[i] = (float) (limit(left[i] * g) * volume);
			right[i] = (float) (limit(right[i] * g) * volume);
		}
	}

	private static double limit(double x)
	{
		double a = Math.abs(x);
		if (a < 0.6)
		{
			return x;
		}
		double over = (a - 0.6) / 0.4;
		double y = 0.6 + 0.4 * over / (1 + over);
		return Math.copySign(Math.min(y, 0.98), x);
	}

	private void allNotesOff()
	{
		for (Voice v : voices)
		{
			if (v.active)
			{
				v.release();
			}
		}
		for (Channel c : channels)
		{
			c.sustain = false;
		}
	}

	private void event(int status, int d1, int d2)
	{
		int type = status & 0xF0;
		int ch = status & 0x0F;
		Channel c = channels[ch];
		switch (type)
		{
			case 0x90:
				if (d2 > 0)
				{
					noteOn(ch, d1, d2);
					break;
				}
				// velocity 0 is a note off
			case 0x80:
				for (Voice v : voices)
				{
					if (v.active && !v.released && v.channel == ch && v.note == d1)
					{
						if (c.sustain)
						{
							v.held = true;
						}
						else
						{
							v.release();
						}
					}
				}
				break;
			case 0xB0:
				control(c, ch, d1, d2);
				break;
			case 0xC0:
				c.program = d1;
				break;
			case 0xE0:
				c.bend = ((d2 << 7 | d1) - 8192) / 8192.0;
				break;
			default:
				break;
		}
	}

	private void control(Channel c, int ch, int cc, int value)
	{
		switch (cc)
		{
			case 6:
				if (c.rpn == 0)
				{
					c.bendRange = Math.max(1, value);
				}
				break;
			case 7:
				c.volume = value / 127.0;
				break;
			case 10:
				c.pan = value / 127.0;
				break;
			case 11:
				c.expression = value / 127.0;
				break;
			case 64:
				c.sustain = value >= 64;
				if (!c.sustain)
				{
					for (Voice v : voices)
					{
						if (v.active && v.held && v.channel == ch)
						{
							v.release();
						}
					}
				}
				break;
			case 100:
				c.rpn = (c.rpn & ~0x7F) | value;
				break;
			case 101:
				c.rpn = (c.rpn & 0x7F) | value << 7;
				break;
			case 120:
			case 123:
				for (Voice v : voices)
				{
					if (v.active && v.channel == ch)
					{
						v.release();
					}
				}
				break;
			case 121:
				c.reset();
				break;
			default:
				break;
		}
	}

	private void noteOn(int ch, int note, int velocity)
	{
		Channel c = channels[ch];
		Voice v = null;
		for (Voice x : voices)
		{
			if (x.active && x.channel == ch && x.note == note)
			{
				// Restriking a ringing note: reuse its voice so notes do not pile up.
				v = x;
				break;
			}
		}
		if (v == null)
		{
			for (Voice x : voices)
			{
				if (!x.active)
				{
					v = x;
					break;
				}
			}
		}
		if (v == null)
		{
			Voice quietest = null;
			for (Voice x : voices)
			{
				double level = x.env * (x.released ? 0.25 : 1);
				if (quietest == null || level < quietest.env * (quietest.released ? 0.25 : 1))
				{
					quietest = x;
				}
			}
			v = quietest;
		}
		v.start(c, ch, note, velocity, ch == 9 ? null : Patch.of(c.program), noteCounter++);
	}

	private float[] table(Patch p, int note)
	{
		int octave = Math.max(0, Math.min(10, note / 12));
		long key = (long) p.spectrum.hashCode() << 8 | octave;
		float[] t = tables.get(key);
		if (t == null)
		{
			double topFreq = 440 * Math.pow(2, ((octave + 1) * 12 + 2 - 69) / 12.0);
			int harmonics = Math.max(1, Math.min(p.spectrum.length, (int) (18000 / topFreq)));
			t = new float[TABLE + 1];
			double peak = 0;
			double[] raw = new double[TABLE];
			for (int k = 1; k <= harmonics; k++)
			{
				double a = p.spectrum[k - 1];
				if (a == 0)
				{
					continue;
				}
				for (int i = 0; i < TABLE; i++)
				{
					raw[i] += a * Math.sin(2 * Math.PI * k * i / TABLE);
				}
			}
			for (double r : raw)
			{
				peak = Math.max(peak, Math.abs(r));
			}
			for (int i = 0; i < TABLE; i++)
			{
				t[i] = (float) (raw[i] / Math.max(peak, 1e-9));
			}
			t[TABLE] = t[0];
			tables.put(key, t);
		}
		return t;
	}

	private static final class Channel
	{
		int program;
		double volume;
		double expression;
		double pan;
		double bend;
		int bendRange;
		int rpn;
		boolean sustain;

		Channel()
		{
			reset();
		}

		void reset()
		{
			volume = 100 / 127.0;
			expression = 1;
			pan = 0.5;
			bend = 0;
			bendRange = 2;
			rpn = 0x3FFF;
			sustain = false;
		}
	}

	private final class Voice
	{
		boolean active;
		boolean released;
		boolean held;
		boolean attacking;
		int channel;
		int note;
		long order;
		Channel ch;
		Patch patch;
		Drum drum;
		float[] wave;
		double phase;
		double phase2;
		double env;
		double gain;
		double age;
		double attackStep;
		double decayCoef;
		double releaseCoef;
		double lp1;
		double lp2;
		double baseFreq;
		int noise = 0x2545F491;
		double drumLp;

		void start(Channel c, int chIndex, int note, int velocity, Patch p, long order)
		{
			boolean restrike = active && this.note == note && channel == chIndex;
			active = true;
			released = false;
			held = false;
			channel = chIndex;
			this.note = note;
			this.order = order;
			ch = c;
			patch = p;
			age = 0;
			double vel = velocity / 127.0;
			if (p == null)
			{
				drum = Drum.of(note);
				wave = null;
				gain = vel * vel * drum.gain * 0.5;
				env = 1;
				noise ^= (int) (order * 0x9E3779B9L);
				if (noise == 0)
				{
					noise = 0x2545F491;
				}
				drumLp = 0;
				phase = 0;
				return;
			}
			drum = null;
			wave = table(p, note);
			baseFreq = 440 * Math.pow(2, (note - 69) / 12.0);
			gain = vel * vel * p.gain * 0.3;
			if (!restrike)
			{
				env = 0;
				phase = 0;
				phase2 = 0.37;
				lp1 = 0;
				lp2 = 0;
			}
			attackStep = 1.0 / Math.max(1, p.attack * RATE);
			attacking = true;
			// Plucked notes ring shorter the higher they are.
			double t60 = p.sustainLevel > 0 ? p.decay : p.decay * Math.pow(2, -(note - 60) / 24.0);
			decayCoef = Math.pow(10, -3 / (Math.max(0.02, t60) * RATE));
			releaseCoef = Math.pow(10, -3 / (Math.max(0.02, p.release) * RATE));
		}

		void release()
		{
			released = true;
			held = false;
		}

		void render(float[] left, float[] right, int n)
		{
			double level = gain * ch.volume * ch.volume * ch.expression;
			double pan = ch.pan;
			float l = (float) (level * Math.cos(pan * Math.PI / 2) * 1.41);
			float r = (float) (level * Math.sin(pan * Math.PI / 2) * 1.41);
			if (drum != null)
			{
				renderDrum(left, right, n, l, r);
				return;
			}
			Patch p = patch;
			double cents = p.vibrato * Math.min(1, Math.max(0, (age - 0.25) * 2)) * Math.sin(2 * Math.PI * 5.5 * age);
			double freq = baseFreq * Math.pow(2, (ch.bend * ch.bendRange + cents / 100) / 12);
			double inc = freq * TABLE / RATE;
			double inc2 = p.detune == 0 ? 0 : inc * Math.pow(2, p.detune / 1200);
			double cutoff = freq * (p.filterEnd + (p.filterStart - p.filterEnd) * Math.exp(-age / p.filterTime));
			double a = cutoff >= RATE * 0.45 ? 1 : 1 - Math.exp(-2 * Math.PI * cutoff / RATE);
			float[] w = wave;
			for (int i = 0; i < n; i++)
			{
				if (released)
				{
					env *= releaseCoef;
				}
				else if (attacking)
				{
					env += attackStep;
					if (env >= 1)
					{
						env = 1;
						attacking = false;
					}
				}
				else if (p.sustainLevel > 0)
				{
					env += (p.sustainLevel - env) * (1 - decayCoef) * 4;
				}
				else
				{
					env *= decayCoef;
				}
				int idx = (int) phase;
				double frac = phase - idx;
				double s = w[idx] + (w[idx + 1] - w[idx]) * frac;
				phase += inc;
				if (phase >= TABLE)
				{
					phase -= TABLE;
				}
				if (inc2 != 0)
				{
					int i2 = (int) phase2;
					double f2 = phase2 - i2;
					s = (s + w[i2] + (w[i2 + 1] - w[i2]) * f2) * 0.6;
					phase2 += inc2;
					if (phase2 >= TABLE)
					{
						phase2 -= TABLE;
					}
				}
				lp1 += a * (s - lp1);
				lp2 += a * (lp1 - lp2);
				float out = (float) (lp2 * env);
				left[i] += out * l;
				right[i] += out * r;
			}
			age += n / (double) RATE;
			if (env < 1e-4 && (released || p.sustainLevel == 0) && age > p.attack)
			{
				active = false;
			}
		}

		private void renderDrum(float[] left, float[] right, int n, float l, float r)
		{
			Drum d = drum;
			double toneCoef = Math.pow(10, -3 / (d.toneDecay * RATE));
			double noiseCoef = Math.pow(10, -3 / (d.noiseDecay * RATE));
			double hp = 1 - Math.exp(-2 * Math.PI * d.highpass / RATE);
			double toneEnv = Math.pow(toneCoef, age * RATE);
			double noiseEnv = Math.pow(noiseCoef, age * RATE);
			for (int i = 0; i < n; i++)
			{
				double t = age + i / (double) RATE;
				double f = d.toneEnd + (d.toneStart - d.toneEnd) * Math.exp(-t / d.sweep);
				phase += f / RATE;
				if (phase >= 1)
				{
					phase -= 1;
				}
				double tone = Math.sin(2 * Math.PI * phase);
				if (d.tone2 > 0)
				{
					tone = 0.6 * tone + 0.4 * Math.sin(2 * Math.PI * phase * d.tone2);
				}
				noise ^= noise << 13;
				noise ^= noise >>> 17;
				noise ^= noise << 5;
				double nz = noise / 2147483648.0;
				drumLp += hp * (nz - drumLp);
				nz -= drumLp;
				double s = tone * toneEnv * d.toneLevel + nz * noiseEnv * d.noiseLevel;
				toneEnv *= toneCoef;
				noiseEnv *= noiseCoef;
				float out = (float) s;
				left[i] += out * l;
				right[i] += out * r;
			}
			age += n / (double) RATE;
			if (toneEnv * d.toneLevel + noiseEnv * d.noiseLevel < 1e-4)
			{
				active = false;
			}
		}
	}

	/** An instrument: harmonic spectrum, envelope and tone filter. */
	static final class Patch
	{
		private static final double[] SINE = {1};
		private static final double[] SAW = series(32, 1, 1, false);
		private static final double[] SQUARE = series(32, 1, 1, true);
		private static final double[] SOFT_SQUARE = series(24, 1, 1.4, true);
		private static final double[] TRIANGLE = series(16, 1, 2, true);
		private static final double[] PIANO = series(28, 1, 1.35, false);
		private static final double[] BRASS = series(28, 1, 0.85, false);
		private static final double[] STRINGS = series(32, 1, 1.1, false);
		private static final double[] ORGAN = {1, 0.65, 0.45, 0.35, 0, 0.22, 0, 0.16};
		private static final double[] BELL = {1, 0.15, 0, 0.4, 0, 0.12, 0, 0, 0, 0.18};
		private static final double[] MARIMBA = {1, 0, 0, 0.3, 0, 0, 0, 0, 0, 0.08};
		private static final double[] FLUTE = {1, 0.32, 0.12, 0.05};
		private static final double[] CLARINET = {1, 0.04, 0.55, 0.03, 0.32, 0.02, 0.2, 0, 0.12, 0, 0.07};
		private static final double[] OBOE = {0.7, 1, 0.85, 0.5, 0.42, 0.25, 0.18, 0.1, 0.06};
		private static final double[] VOICE = {1, 0.55, 0.65, 0.35, 0.12, 0.1, 0.05};
		private static final Patch[] CACHE = new Patch[128];

		final double[] spectrum;
		double attack = 0.005;
		/** Plucked: seconds to fade by 60 dB at middle C. Sustained: seconds to settle to the sustain level. */
		double decay = 1.5;
		double sustainLevel;
		double release = 0.25;
		double filterStart = 40;
		double filterEnd = 40;
		double filterTime = 0.3;
		double vibrato;
		double detune;
		double gain = 1;

		private Patch(double[] spectrum)
		{
			this.spectrum = spectrum;
		}

		private static double[] series(int n, double first, double power, boolean oddOnly)
		{
			double[] s = new double[n];
			for (int k = 1; k <= n; k++)
			{
				s[k - 1] = oddOnly && k % 2 == 0 ? 0 : first / Math.pow(k, power);
			}
			return s;
		}

		private Patch plucked(double t60, double release, double filterStart, double filterEnd, double filterTime)
		{
			this.decay = t60;
			this.sustainLevel = 0;
			this.release = release;
			this.filterStart = filterStart;
			this.filterEnd = filterEnd;
			this.filterTime = filterTime;
			return this;
		}

		private Patch sustained(double attack, double level, double release)
		{
			this.attack = attack;
			this.sustainLevel = level;
			this.decay = 0.3;
			this.release = release;
			return this;
		}

		private Patch tone(double filter, double vibrato, double detune, double gain)
		{
			this.filterStart = filter;
			this.filterEnd = filter;
			this.vibrato = vibrato;
			this.detune = detune;
			this.gain = gain;
			return this;
		}

		static Patch of(int program)
		{
			program &= 127;
			Patch p = CACHE[program];
			if (p == null)
			{
				p = make(program);
				CACHE[program] = p;
			}
			return p;
		}

		private static Patch make(int program)
		{
			switch (program)
			{
				case 12:
				case 13:
					return new Patch(MARIMBA).plucked(0.5, 0.3, 40, 40, 1);
				case 14:
					return new Patch(BELL).plucked(4, 3, 40, 40, 1);
				case 21:
				case 22:
				case 23:
					return new Patch(SOFT_SQUARE).sustained(0.03, 0.85, 0.1).tone(8, 6, 0, 0.7);
				case 29:
				case 30:
					return new Patch(SAW).sustained(0.01, 0.8, 0.15).tone(6, 0, 6, 0.65);
