	 * macroblock in quarter pels, all against the one reference picture.
	 */
	static void filter(int[] y, int[] u, int[] v, int pw, int cw, int mbW, int mbH,
		boolean[] intra, int[] mvx, int[] mvy, int[] nzY, int qp, int qpc)
