package com.gielinorwrapped;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.Collections;
import java.util.Map;
import org.junit.Test;

public class RecapTest
{
	private static DayRecord day(String date, long playSecs, String skill, long xp)
	{
		DayRecord d = new DayRecord(date);
		d.playSeconds = playSecs;
		d.hours[20] = playSecs;
		d.xp.put(skill, xp);
		return d;
	}

	@Test
	public void periods()
	{
		LocalDate sun = LocalDate.of(2026, 10, 25);
		Period week = Period.containing(Period.Kind.WEEK, sun, DayOfWeek.MONDAY);
		assertEquals(LocalDate.of(2026, 10, 19), week.from);
		assertEquals(LocalDate.of(2026, 10, 25), week.to);
		assertEquals("19 Oct – 25 Oct 2026", week.describe());
		assertEquals(Period.containing(Period.Kind.WEEK, LocalDate.of(2026, 10, 12), DayOfWeek.MONDAY), week.before());

		Period lastMonth = Period.previous(Period.Kind.MONTH, LocalDate.of(2026, 10, 26), DayOfWeek.MONDAY);
		assertEquals(LocalDate.of(2026, 9, 1), lastMonth.from);
		assertEquals(LocalDate.of(2026, 9, 30), lastMonth.to);
		assertEquals("September 2026", lastMonth.describe());
		assertEquals(LocalDate.of(2025, 1, 1), Period.previous(Period.Kind.YEAR, LocalDate.of(2026, 1, 1), DayOfWeek.MONDAY).from);

		Period custom = new Period(Period.Kind.CUSTOM, LocalDate.of(2026, 10, 1), LocalDate.of(2026, 10, 10));
		assertEquals(LocalDate.of(2026, 9, 21), custom.before().from);
		assertEquals("custom-2026-10-01-2026-10-10", custom.id());
	}

	@Test
	public void summarises()
	{
		Period week = Period.containing(Period.Kind.WEEK, LocalDate.of(2026, 10, 19), DayOfWeek.MONDAY);
		DayRecord mon = day("2026-10-19", 3600, "Mining", 200_000);
		DayRecord tue = day("2026-10-20", 7200, "Mining", 300_000);
		tue.xp.put("Fishing", 50_000L);
		tue.kills.put("Zulrah", 12);
		tue.addDrop(new DayRecord.Drop(1, 12922, "Tanzanite fang", 1, 3_000_000, "Zulrah"));
		tue.addMoment(new Moment(5, Moment.Type.DROP, "Tanzanite fang", null, 3_000_000, 58));
		tue.addMoment(new Moment(2, Moment.Type.LEVEL_UP, "80 Mining", null, 80, 50));
		DayRecord thu = day("2026-10-22", 1800, "Mining", 10_000);

		Recap r = Recap.build(week, "Zezima", Arrays.asList(mon, tue, thu), Collections.singletonList(day("2026-10-12", 60, "Mining", 280_000)));
		assertEquals(3, r.daysPlayed);
		assertEquals(2, r.longestStreak);
		assertEquals("Mining", r.skills.get(0).name);
		assertEquals(LocalDate.of(2026, 10, 20), r.busiestDay);
		assertEquals(Integer.valueOf(100), r.xpChange);
		assertEquals("Tanzanite fang", r.highlights.get(0).title);
		assertEquals("The Gatherer", r.persona.title);

		Map<String, String> t = r.tokens(false);
		assertEquals("Zezima's Weekly Wrapped", Recap.fill("{player}'s {period} Wrapped", t));
		assertEquals("You gained 560,000 XP|Mostly Mining: 510,000 XP {nope}", Recap.fill("You gained {xp} XP|Mostly {topSkill}: {topSkillXp} {nope}", t));
		assertEquals("3h 30m played over 3 days", Recap.fill("{hours} played over {days}", t));
		assertEquals("Adventurer", r.tokens(true).get("player"));
		assertEquals("8pm", t.get("peakHour"));
		assertEquals("+100%", t.get("xpChange"));
	}

	@Test
	public void noComparisonWithoutHistory()
	{
		Period day = Period.containing(Period.Kind.DAY, LocalDate.of(2026, 10, 26), DayOfWeek.MONDAY);
		Recap r = Recap.build(day, null, Collections.emptyList(), Collections.emptyList());
		assertNull(r.xpChange);
		assertEquals("The Explorer", r.persona.title);
		assertEquals("nothing yet", r.tokens(false).get("topSkill"));
	}

	@Test
	public void formatting()
	{
		assertEquals("999", Recap.number(999));
		assertEquals("1.23M", Recap.number(1_234_567));
		assertEquals("12.3M", Recap.number(12_345_678));
		assertEquals("2.1B", Recap.number(2_147_483_647));
		assertEquals("54,321 gp", Recap.gp(54_321));
		assertEquals("250K gp", Recap.gp(250_000));
		assertEquals("2.5M gp", Recap.gp(2_500_000));
		assertEquals("-3.1M gp", Recap.gp(-3_100_000));
		assertEquals("1.2B gp", Recap.gp(1_250_000_000L));
		assertEquals("-2.1B gp", Recap.gp(-2_147_000_000L));
		assertEquals("45.6M gp", Recap.gp(45_600_000));
		assertEquals("45m", Recap.duration(2700));
		assertEquals("2h", Recap.duration(7200));
		assertEquals("12am", Recap.hour(0));
		assertEquals("12pm", Recap.hour(12));
	}
}

package com.gielinorwrapped;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import javax.imageio.ImageIO;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** Makes recaps end to end on disk (under build/test-home, see build.gradle). */
public class RecapsTest
{
	private static final long ACCOUNT = 42;
	private static final long T0 = 1_761_000_000_000L;

	@PluginDescriptor(name = "Recaps test", internalName = "gielinorwrappedtest")
	public static class DirPlugin extends Plugin
	{
		Filepath dir() throws IOException
		{
			return getPluginDirectory();
		}
	}

	private static class Config implements GielinorWrappedConfig
	{
		@Override
		public Quality quality()
		{
			return Quality.SMALL;
		}

		@Override
		public int maxLength()
		{
			return 6;
		}

		@Override
		public int videoFps()
		{
			return 10;
		}

		@Override
		public boolean autoDaily()
		{
			return false;
		}

		@Override
		public boolean autoWeekly()
		{
			return true;
		}

		@Override
		public boolean autoMonthly()
		{
			return false;
		}

		@Override
		public boolean autoYearly()
		{
			return false;
		}

		@Override
		public DayOfWeek weekStart()
		{
			return DayOfWeek.MONDAY;
		}

		@Override
		public boolean autoVideo()
		{
			return true;
		}

		@Override
		public boolean notifyReady()
		{
			return true;
		}
	}

	private Filepath root;
	private StatsStore store;
	private Recaps recaps;

	@Before
	public void setUp() throws IOException
	{
		Filepath data = new DirPlugin().dir();
		data.createDirectories();
		root = data.createTempDir("recaps");
		store = new StatsStore(new Gson(), root);
		ClipLibrary library = new ClipLibrary(store);

		List<ClipFile.Frame> frames = new ArrayList<>();
		for (int i = 0; i < 40; i++)
		{
			frames.add(new ClipFile.Frame(T0 + i * 100, jpeg(i)));
		}
		DayRecord d = new DayRecord("2026-10-20");
		d.playSeconds = 5400;
		d.xp.put("Woodcutting", 120_000L);
		d.levels.put("Woodcutting", 1);
		Moment m = new Moment(T0 + 2000, Moment.Type.LEVEL_UP, "70 Woodcutting", null, 70, 50);
		m.clip = library.writeClip(ACCOUNT, m.time, m.importance, frames);
		d.addMoment(m);
		store.writeDay(ACCOUNT, d.date, store.gson().toJson(d));

		recaps = new Recaps(store, library, new Shots(store), new DeathLog(store), null, new Config(), j -> { });
	}

	@After
	public void tearDown() throws Exception
	{
		if (recaps != null)
		{
			recaps.close();
		}
		if (root != null)
		{
			root.deleteRecursively();
		}
	}

	@Test
	public void makesCardAndVideo() throws Exception
	{
		Period week = Period.containing(Period.Kind.WEEK, LocalDate.of(2026, 10, 20), DayOfWeek.MONDAY);
		Recaps.Job job = await(recaps.request(ACCOUNT, "Zezima", week, true));
		assertEquals(job.message, Recaps.Status.DONE, job.status);

		List<Recaps.Saved> saved = recaps.saved(ACCOUNT);
		assertEquals(1, saved.size());
		Recaps.Saved s = saved.get(0);
		assertEquals(week, s.meta.period());
		assertEquals("Zezima", s.meta.player);
		assertTrue(s.card().size() > 1000);
		assertNotNull(s.video());
		assertTrue(s.video().size() > 1000);
		try (java.util.stream.Stream<Filepath> files = s.dir.walk(1))
		{
			assertTrue("no partial files", files.noneMatch(f -> f.getFileName().endsWith(".part") || f.getFileName().endsWith(".tmp")));
		}

		recaps.delete(s);
		assertTrue(recaps.saved(ACCOUNT).isEmpty());
	}

	@Test
	public void emptyPeriodFails() throws Exception
	{
		Period day = Period.containing(Period.Kind.DAY, LocalDate.of(2026, 10, 21), DayOfWeek.MONDAY);
		Recaps.Job job = await(recaps.request(ACCOUNT, "Zezima", day, false));
		assertEquals(Recaps.Status.FAILED, job.status);
		assertTrue(recaps.saved(ACCOUNT).isEmpty());
	}

	@Test
	public void scheduleRunsOnce() throws Exception
	{
		List<String> ready = new ArrayList<>();
		LocalDate monday = LocalDate.of(2026, 10, 26);
		recaps.checkSchedule(ACCOUNT, "Zezima", monday, ready::add);
		assertEquals(1, recaps.jobs().size());
		await(recaps.jobs().get(0));
		recaps.checkSchedule(ACCOUNT, "Zezima", monday, ready::add);
		assertEquals(1, recaps.jobs().size());

		// The notification is queued behind the render.
		for (int i = 0; i < 250 && ready.isEmpty(); i++)
		{
			Thread.sleep(20);
		}
		assertEquals(ready.toString(), 1, ready.size());
		assertTrue(ready.get(0), ready.get(0).contains("weekly"));
		assertEquals(1, recaps.saved(ACCOUNT).size());
	}

	private static Recaps.Job await(Recaps.Job job) throws InterruptedException
	{
		long end = System.currentTimeMillis() + 60_000;
		while (!job.status.finished() && System.currentTimeMillis() < end)
		{
			Thread.sleep(20);
		}
		return job;
	}

	private static byte[] jpeg(int i) throws IOException
	{
		BufferedImage img = new BufferedImage(160, 100, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = img.createGraphics();
		g.setColor(Color.getHSBColor(i / 40f, 0.5f, 0.7f));
		g.fillRect(0, 0, 160, 100);
		g.dispose();
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		ImageIO.write(img, "jpg", out);
		return out.toByteArray();
	}
}

package com.gielinorwrapped;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.List;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;
import org.junit.Test;

public class ReplayGifTest
{
	private static final long START = 1_761_000_000_000L;

	/** A small animated GIF: a red square moving right over a blue background. */
	static byte[] gif(int frames) throws IOException
	{
		ImageWriter writer = ImageIO.getImageWritersByFormatName("gif").next();
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ImageOutputStream out = ImageIO.createImageOutputStream(bytes))
		{
			writer.setOutput(out);
			writer.prepareWriteSequence(null);
			for (int i = 0; i < frames; i++)
			{
				BufferedImage img = new BufferedImage(80, 40, BufferedImage.TYPE_INT_RGB);
				Graphics2D g = img.createGraphics();
				g.setColor(Color.BLUE);
				g.fillRect(0, 0, 80, 40);
				g.setColor(Color.RED);
				g.fillRect(i * 10, 10, 20, 20);
				g.dispose();
				writer.writeToSequence(new IIOImage(img, null, null), null);
			}
			writer.endWriteSequence();
		}
		finally
		{
			writer.dispose();
		}
		return bytes.toByteArray();
	}

	@Test
	public void framesFollowReplayTimes() throws IOException
	{
		List<ClipFile.Frame> frames = ReplayGif.frames(gif(4), START, new int[]{-1800, -1200, -600, 0}, 40);
		assertEquals(4, frames.size());
		assertEquals(START - 1800, frames.get(0).time);
		assertEquals(START, frames.get(3).time);
		BufferedImage last = ImageIO.read(new ByteArrayInputStream(frames.get(3).jpeg));
		assertEquals("scaled to the clip width", 40, last.getWidth());
		Color c = new Color(last.getRGB(18, 10));
		assertTrue("the square moved: " + c, c.getRed() > 150 && c.getBlue() < 100);
	}

	@Test
	public void dropsFramesWithoutTimes() throws IOException
	{
		assertEquals(2, ReplayGif.frames(gif(4), START, new int[]{0, 600}, 80).size());
		assertEquals("times must go forward", 2, ReplayGif.frames(gif(3), START, new int[]{0, 0, 600}, 80).size());
	}

	@Test
	public void survivesBadData()
	{
		assertTrue(ReplayGif.frames(new byte[]{1, 2, 3}, START, new int[]{0}, 80).isEmpty());
		assertTrue(ReplayGif.frames(null, START, new int[]{0}, 80).isEmpty());
	}
}

