package com.gielinorwrapped.music;

import java.io.ByteArrayOutputStream;
import javax.sound.midi.MetaMessage;
import javax.sound.midi.MidiEvent;
import javax.sound.midi.MidiSystem;
import javax.sound.midi.Sequence;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Track;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Builds a small song with javax.sound.midi, then checks the parser's timing and the synth's output. */
public class SynthTest
{
	public static byte[] song() throws Exception
	{
		Sequence seq = new Sequence(Sequence.PPQ, 96);
		Track tempo = seq.createTrack();
		// 120 bpm for the first bar, then 60 bpm.
		tempo.add(new MidiEvent(new MetaMessage(0x51, new byte[]{0x07, (byte) 0xA1, 0x20}, 3), 0));
		tempo.add(new MidiEvent(new MetaMessage(0x51, new byte[]{0x0F, 0x42, 0x40}, 3), 384));
		Track melody = seq.createTrack();
		int[] programs = {0, 48, 73, 33};
		for (int ch = 0; ch < programs.length; ch++)
		{
			melody.add(new MidiEvent(new ShortMessage(ShortMessage.PROGRAM_CHANGE, ch, programs[ch], 0), 0));
			melody.add(new MidiEvent(new ShortMessage(ShortMessage.CONTROL_CHANGE, ch, 10, 20 + ch * 30), 0));
		}
		int[] notes = {60, 64, 67, 72, 67, 64, 60, 55};
		for (int i = 0; i < notes.length; i++)
		{
			int ch = i % programs.length;
			melody.add(new MidiEvent(new ShortMessage(ShortMessage.NOTE_ON, ch, notes[i], 100), i * 96));
			melody.add(new MidiEvent(new ShortMessage(ShortMessage.NOTE_ON, ch, notes[i], 0), i * 96 + 90));
		}
		melody.add(new MidiEvent(new ShortMessage(ShortMessage.PITCH_BEND, 2, 0, 96), 400));
		Track drums = seq.createTrack();
		for (int i = 0; i < 8; i++)
		{
			int note = i % 2 == 0 ? 36 : 38;
			drums.add(new MidiEvent(new ShortMessage(ShortMessage.NOTE_ON, 9, note, 110), i * 96));
			drums.add(new MidiEvent(new ShortMessage(ShortMessage.NOTE_OFF, 9, note, 0), i * 96 + 10));
			drums.add(new MidiEvent(new ShortMessage(ShortMessage.NOTE_ON, 9, 42, 70), i * 96 + 48));
		}
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		MidiSystem.write(seq, 1, out);
		return out.toByteArray();
	}

	@Test
	public void parsesTempoChanges() throws Exception
	{
		Midi m = Midi.parse(song());
		assertTrue(m.size() > 30);
		for (int i = 1; i < m.size(); i++)
		{
			assertTrue(m.time[i] >= m.time[i - 1]);
		}
		// Notes 0-3 at 0.5 s per beat, then 1 s per beat after tick 384: the last note-off is at tick 762.
		assertEquals(2 + (762 - 384) / 96.0, m.length, 1e-6);
	}

	@Test
	public void rendersAudibleLoopingStereo() throws Exception
	{
		Midi m = Midi.parse(song());
		double seconds = 15;
		float[][] pcm = Synth.render(m, seconds, 0.8, true);
		assertEquals(2, pcm.length);
		assertEquals((int) Math.ceil(seconds * Synth.RATE), pcm[0].length);
		double peak = 0;
		double diff = 0;
		for (int c = 0; c < 2; c++)
		{
			for (float s : pcm[c])
			{
				assertTrue(!Float.isNaN(s) && !Float.isInfinite(s));
				peak = Math.max(peak, Math.abs(s));
			}
		}
		for (int i = 0; i < pcm[0].length; i++)
		{
			diff += Math.abs(pcm[0][i] - pcm[1][i]);
		}
		assertTrue("peak " + peak, peak > 0.1 && peak <= 1);
		assertTrue("panned channels differ", diff > 100);
		// The song is about 6 s long, so the second pass (from about 7 s) must also make sound.
		assertTrue("loops", rms(pcm[0], 8 * Synth.RATE, 10 * Synth.RATE) > 0.02);
		// Fades: quiet at both ends.
		assertTrue(rms(pcm[0], 0, 2000) < rms(pcm[0], Synth.RATE * 2, Synth.RATE * 3));
		assertTrue(Math.abs(pcm[0][pcm[0].length - 1]) < 0.01);
	}

	@Test
	public void emptySongIsSilent()
	{
		byte[] header = {'M', 'T', 'h', 'd', 0, 0, 0, 6, 0, 0, 0, 0, 0, 96};
		float[][] pcm = Synth.render(Midi.parse(header), 1, 1, false);
		for (float s : pcm[0])
		{
			assertEquals(0, s, 0);
		}
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsGarbage()
	{
		Midi.parse(new byte[]{1, 2, 3, 4, 5, 6, 7, 8});
	}

	@Test(expected = IllegalArgumentException.class)
	public void trackLoaderRejectsGarbage()
	{
		TrackLoader.toMidi(new byte[]{1, 2, 3, 4, 5, 6, 7, 8, 9});
	}

	private static double rms(float[] a, int from, int to)
	{
		double s = 0;
		for (int i = from; i < to; i++)
		{
			s += a[i] * a[i];
		}
		return Math.sqrt(s / (to - from));
	}
}

package com.gielinorwrapped.video;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Files;
import java.util.List;
import java.util.concurrent.TimeUnit;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;
import org.junit.Test;

/** Checks the MDCT against the direct formula, then decodes a muxed AAC track with ffmpeg and measures it. */
public class AacEncoderTest
{
	@Test
	public void mdctMatchesDirectFormula()
	{
		int n = 64;
		float[] x = new float[2 * n];
		java.util.Random rnd = new java.util.Random(3);
		for (int i = 0; i < x.length; i++)
		{
			x[i] = rnd.nextFloat() * 2 - 1;
		}
		float[] fast = new float[n];
		new AacEncoder.Mdct(n).forward(x, fast);
		for (int k = 0; k < n; k++)
		{
			double sum = 0;
			for (int i = 0; i < 2 * n; i++)
			{
				sum += x[i] * Math.cos(Math.PI / n * (i + 0.5 + n / 2.0) * (k + 0.5));
			}
			assertEquals("bin " + k, sum, fast[k], 1e-3);
		}
	}

	@Test
	public void decodesWithFfmpeg() throws Exception
	{
		assumeTrue(H264EncoderTest.haveFfmpeg());
		int rate = AacEncoder.SAMPLE_RATE;
		int samples = rate * 2;
		float[] left = new float[samples];
		float[] right = new float[samples];
		for (int i = 0; i < samples; i++)
		{
			double t = i / (double) rate;
			double env = Math.min(1, t * 20) * Math.min(1, (samples - i) / (rate * 0.05));
			left[i] = (float) (env * (0.4 * Math.sin(2 * Math.PI * 440 * t) + 0.15 * Math.sin(2 * Math.PI * 1320 * t)));
			right[i] = (float) (env * (0.3 * Math.sin(2 * Math.PI * 330 * t) + 0.2 * Math.sin(2 * Math.PI * 2475 * t)));
		}
		AacEncoder aac = new AacEncoder(2, 128000);
		long start = System.nanoTime();
		List<byte[]> frames = aac.encode(left, right);
		System.out.printf("aac: %d frames in %d ms%n", frames.size(), (System.nanoTime() - start) / 1000000);

		int w = 64;
		int h = 64;
		H264Encoder enc = new H264Encoder(w, h, 30);
		Mp4Writer mp4 = new Mp4Writer(w, h, 30, enc.sps(), enc.pps());
		File dir = Files.createTempDirectory("gw-aac").toFile();
		File media = new File(dir, "media.tmp");
		File out = new File(dir, "out.mp4");
		try (OutputStream m = new FileOutputStream(media))
		{
			for (int t = 0; t < 60; t++)
			{
				mp4.addFrame(enc.encode(H264EncoderTest.scene(w, h, t, 3), false), m);
			}
		}
		mp4.setAudio(aac.audioSpecificConfig(), 2, 128000, frames, AacEncoder.PRIMING, samples);
		try (OutputStream o = new FileOutputStream(out); InputStream m = new FileInputStream(media))
		{
			mp4.finish(o, m);
		}

		String probe = run("ffprobe", "-v", "error", "-select_streams", "a:0",
			"-show_entries", "stream=codec_name,profile,sample_rate,channels",
			"-of", "default=noprint_wrappers=1", out.getPath());
		assertTrue(probe, probe.contains("codec_name=aac"));
		assertTrue(probe, probe.contains("sample_rate=44100"));
		assertTrue(probe, probe.contains("channels=2"));

		File pcm = new File(dir, "out.f32");
		String err = run("ffmpeg", "-v", "error", "-y", "-i", out.getPath(), "-map", "0:a", "-f", "f32le",
			"-ac", "2", pcm.getPath());
		assertEquals("", err.trim());
		ByteBuffer buf = ByteBuffer.wrap(Files.readAllBytes(pcm.toPath())).order(ByteOrder.LITTLE_ENDIAN);
		int got = buf.remaining() / 8;
		float[][] dec = new float[2][got];
		for (int i = 0; i < got; i++)
		{
			dec[0][i] = buf.getFloat();
			dec[1][i] = buf.getFloat();
		}
		System.out.printf("aac: decoded %d of %d samples, %d bytes%n", got, samples, out.length());
		assertTrue("length " + got, Math.abs(got - samples) <= 1024);
		float[][] src = {left, right};
		for (int c = 0; c < 2; c++)
		{
			int bestLag = 0;
			double best = -1e9;
			for (int lag = -1100; lag <= 1100; lag++)
			{
				double s = snr(src[c], dec[c], lag);
				if (s > best)
				{
					best = s;
					bestLag = lag;
				}
			}
			double gain = rms(dec[c]) / rms(src[c]);
			System.out.printf("aac channel %d: snr %.1f dB at lag %d, gain %.3f%n", c, best, bestLag, gain);
			assertEquals("lag", 0, bestLag, 2);
			assertTrue("snr " + best, best > 20);
			assertEquals("gain", 1, gain, 0.1);
		}
	}

	private static double snr(float[] a, float[] b, int lag)
	{
		double sig = 0;
		double noise = 0;
		for (int i = 4096; i < a.length - 4096; i += 3)
		{
			int j = i + lag;
			if (j < 0 || j >= b.length)
			{
				continue;
			}
			sig += a[i] * a[i];
			double d = a[i] - b[j];
			noise += d * d;
		}
		return 10 * Math.log10(sig / Math.max(noise, 1e-12));
	}

	private static double rms(float[] a)
	{
		double s = 0;
		for (int i = 4096; i < Math.min(a.length, 80000); i++)
		{
			s += a[i] * a[i];
		}
		return Math.sqrt(s / (Math.min(a.length, 80000) - 4096));
	}

	private static String run(String... cmd) throws Exception
	{
		Process p = new ProcessBuilder(cmd).redirectErrorStream(true).start();
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (InputStream in = p.getInputStream())
		{
			in.transferTo(bytes);
		}
		p.waitFor(60, TimeUnit.SECONDS);
		return bytes.toString("UTF-8");
	}
}

package com.gielinorwrapped.video;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.TimeUnit;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;
import org.junit.Test;

/** Decodes encoder output with ffmpeg (skipped when ffmpeg isn't installed) and compares it with the encoder's reconstruction. */
public class H264EncoderTest
{
	static boolean haveFfmpeg()
	{
		try
		{
			Process p = new ProcessBuilder("ffmpeg", "-version").redirectErrorStream(true).start();
			p.getInputStream().readAllBytes();
			return p.waitFor(10, TimeUnit.SECONDS) && p.exitValue() == 0;
		}
		catch (IOException | InterruptedException e)
		{
			return false;
		}
	}

	/** A moving scene: gradient, drifting textured square, a bouncing dot and noise speckles. */
	static int[] scene(int w, int h, int t, long seed)
	{
		int[] px = new int[w * h];
		Random rnd = new Random(seed + t);
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				int r = (x * 255 / w + t * 3) & 0xFF;
				int g = y * 255 / h;
				int b = ((x ^ y) & 0x3F) + 96;
				int sx = x - t * 2 - 20;
				int sy = y - t - 10;
				if (sx >= 0 && sx < 48 && sy >= 0 && sy < 40)
				{
					r = ((sx / 4 + sy / 4) & 1) != 0 ? 240 : 30;
					g = 200 - sy * 3;
					b = sx * 5;
				}
				int dx = x - (int) (w / 2 + Math.sin(t / 5.0) * w / 3);
				int dy = y - (int) (h / 2 + Math.cos(t / 7.0) * h / 3);
				if (dx * dx + dy * dy < 81)
				{
					r = 255;
					g = 255;
					b = 0;
				}
				if (rnd.nextInt(200) == 0)
				{
					r = g = b = rnd.nextInt(256);
				}
				px[y * w + x] = 0xFF000000 | (r << 16) | (g << 8) | b;
			}
		}
		return px;
	}

	@Test
	public void decodesExactlyAsReconstructed() throws Exception
	{
		assumeTrue(haveFfmpeg());
		check(200, 120, 26, 60, 25);
		check(64, 48, 40, 20, 8);
		check(34, 18, 18, 6, 3);
		check(160, 96, 44, 30, 30);
	}

	private void check(int w, int h, int qp, int frames, int keyInterval) throws Exception
	{
		H264Encoder enc = new H264Encoder(w, h, 30);
		enc.setQp(qp);
		enc.setKeyInterval(keyInterval);
		File dir = Files.createTempDirectory("gw-h264").toFile();
		File stream = new File(dir, "out.h264");
		List<int[][]> recon = new ArrayList<>();
		List<int[]> sources = new ArrayList<>();
		try (OutputStream out = new FileOutputStream(stream))
		{
			writeNal(out, enc.sps());
			writeNal(out, enc.pps());
			for (int t = 0; t < frames; t++)
			{
				int[] src = scene(w, h, t, 7);
				sources.add(src);
				writeNal(out, enc.encode(src, false).nal);
				recon.add(enc.reconstruction());
			}
		}

		File yuv = new File(dir, "out.yuv");
		Process p = new ProcessBuilder("ffmpeg", "-v", "error", "-y", "-i", stream.getPath(), "-f", "rawvideo", "-pix_fmt", "yuv420p", yuv.getPath())
			.redirectErrorStream(true).start();
		String log = new String(readAll(p.getInputStream()));
		assertTrue(p.waitFor(60, TimeUnit.SECONDS));
		assertEquals("ffmpeg errors: " + log, "", log.trim());

		byte[] decoded = Files.readAllBytes(yuv.toPath());
		int frameSize = w * h * 3 / 2;
		assertEquals(frames * frameSize, decoded.length);
		double mse = 0;
		for (int f = 0; f < frames; f++)
		{
			int[][] planes = recon.get(f);
			int o = f * frameSize;
			for (int[] plane : planes)
			{
				for (int i = 0; i < plane.length; i++)
				{
					int d = decoded[o + i] & 0xFF;
					if (d != plane[i])
					{
						throw new AssertionError(w + "x" + h + " frame " + f + " plane offset " + (o - f * frameSize) + " index " + i + ": decoder " + d + " encoder " + plane[i]);
					}
				}
				o += plane.length;
			}
			int[] src = sources.get(f);
			for (int i = 0; i < w * h; i++)
			{
				int c = src[i];
				int y = ((11966 * ((c >> 16) & 0xFF) + 40254 * ((c >> 8) & 0xFF) + 4064 * (c & 0xFF) + 32768) >> 16) + 16;
				double d = y - planes[0][i];
				mse += d * d;
			}
		}
		mse /= (double) frames * w * h;
		double psnr = 10 * Math.log10(255 * 255 / Math.max(mse, 1e-9));
		System.out.printf("%dx%d qp %d: %d bytes for %d frames, luma PSNR %.2f dB%n", w, h, qp, stream.length(), frames, psnr);
		assertTrue("PSNR " + psnr, psnr > (qp <= 26 ? 34 : 26));
	}

	static void writeNal(OutputStream out, byte[] nal) throws IOException
	{
		out.write(new byte[]{0, 0, 0, 1});
		out.write(nal);
	}

	static byte[] readAll(InputStream in) throws IOException
	{
		ByteArrayOutputStream b = new ByteArrayOutputStream();
		byte[] buf = new byte[8192];
		int n;
		while ((n = in.read(buf)) > 0)
		{
			b.write(buf, 0, n);
		}
		return b.toByteArray();
	}
}

package com.gielinorwrapped.video;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;
import org.junit.Test;

/** Muxes encoded frames, then checks ffprobe's view of the file and that ffmpeg decodes it bit-exactly. */
public class Mp4WriterTest
{
	@Test
	public void muxesPlayableMp4() throws Exception
	{
		assumeTrue(H264EncoderTest.haveFfmpeg());
		int w = 160;
		int h = 90;
		int frames = 45;
		H264Encoder enc = new H264Encoder(w, h, 30);
		enc.setQp(28);
		enc.setKeyInterval(20);
		Mp4Writer mp4 = new Mp4Writer(w, h, 30, enc.sps(), enc.pps());
		File dir = Files.createTempDirectory("gw-mp4").toFile();
		File media = new File(dir, "media.tmp");
		File out = new File(dir, "out.mp4");
		List<int[][]> recon = new ArrayList<>();
		try (OutputStream m = new FileOutputStream(media))
		{
			for (int t = 0; t < frames; t++)
			{
				mp4.addFrame(enc.encode(H264EncoderTest.scene(w, h, t, 3), false), m);
				recon.add(enc.reconstruction());
			}
		}
		try (OutputStream o = new FileOutputStream(out); InputStream m = new FileInputStream(media))
		{
			mp4.finish(o, m);
		}

		String probe = run("ffprobe", "-v", "error", "-select_streams", "v:0", "-count_frames",
			"-show_entries", "stream=codec_name,width,height,r_frame_rate,nb_read_frames,duration",
			"-of", "default=noprint_wrappers=1", out.getPath());
		assertTrue(probe, probe.contains("codec_name=h264"));
		assertTrue(probe, probe.contains("width=" + w));
		assertTrue(probe, probe.contains("height=" + h));
		assertTrue(probe, probe.contains("r_frame_rate=30/1"));
		assertTrue(probe, probe.contains("nb_read_frames=" + frames));
		assertTrue(probe, probe.contains("duration=1.500000"));

		File yuv = new File(dir, "out.yuv");
		assertEquals("", run("ffmpeg", "-v", "error", "-y", "-i", out.getPath(), "-f", "rawvideo", "-pix_fmt", "yuv420p", yuv.getPath()).trim());
		byte[] decoded = Files.readAllBytes(yuv.toPath());
		int frameSize = w * h * 3 / 2;
		assertEquals(frames * frameSize, decoded.length);
		for (int f = 0; f < frames; f++)
		{
			int o = f * frameSize;
			for (int[] plane : recon.get(f))
			{
				for (int i = 0; i < plane.length; i++)
				{
					assertEquals("frame " + f, plane[i], decoded[o + i] & 0xFF);
				}
				o += plane.length;
			}
		}
		System.out.printf("mp4 %dx%d: %d bytes, %d frames%n", w, h, out.length(), frames);
	}

	private static String run(String... cmd) throws Exception
	{
		Process p = new ProcessBuilder(cmd).redirectErrorStream(true).start();
		String log = new String(H264EncoderTest.readAll(p.getInputStream()));
		assertTrue(p.waitFor(60, TimeUnit.SECONDS));
		return log;
	}
}
